/* CSEC Study Hub — practice bank
 *
 * These questions are written for this hub in CSEC Paper 01 style. They are not
 * copies of CXC past papers — CXC owns those and sells them, so the hub links
 * out to the official store rather than reproducing them. Every item is tagged
 * to a syllabus strand so a wrong answer moves the right strand in the mastery
 * model and comes back in the daily plan.
 *
 * Fields: id, subj, strand, form (earliest form it fits), diff 1-3,
 *         q, opts[], a (index of correct option), why, tech (exam technique)
 */
window.CSEC_QUESTIONS = [

/* ============================ MATHEMATICS ============================ */
{id:'ma1',subj:'mathematics',strand:'ma-number',level:6,diff:1,q:'Simplify: 3/4 + 2/5',opts:['23/20','5/9','23/40','6/20'],a:0,why:'Use a common denominator of 20: 3/4 = 15/20 and 2/5 = 8/20. 15/20 + 8/20 = 23/20, which is 1 3/20.',tech:'Never add denominators. Find the LCM first, convert both, then add only the numerators.'},
{id:'ma2',subj:'mathematics',strand:'ma-number',level:7,diff:2,q:'Write 0.00045 in standard form.',opts:['4.5 × 10⁻⁴','45 × 10⁻⁵','4.5 × 10⁴','0.45 × 10⁻³'],a:0,why:'Standard form needs one non-zero digit before the point. Moving the point 4 places right gives 4.5, so the index is −4.',tech:'Small number → negative index. Large number → positive index. Count the jumps of the decimal point.'},
{id:'ma3',subj:'mathematics',strand:'ma-number',level:7,diff:1,q:'Evaluate (2³)²',opts:['64','32','12','36'],a:0,why:'Power of a power means multiply the indices: (2³)² = 2⁶ = 64.',tech:'Multiply indices for a power of a power; add them when multiplying the same base.'},
{id:'ma4',subj:'mathematics',strand:'ma-consumer',level:7,diff:2,q:'A television is marked $2 400 before VAT. VAT is charged at 12.5%. What is the price including VAT?',opts:['$2 700.00','$2 412.50','$2 550.00','$3 000.00'],a:0,why:'VAT = 12.5% of 2 400 = $300. Total = 2 400 + 300 = $2 700.',tech:'Adding a percentage? Multiply by 1.125 in one step instead of finding the VAT and adding it — fewer chances to slip.'},
{id:'ma5',subj:'mathematics',strand:'ma-consumer',level:8,diff:2,q:'Kavita borrows $8 000 at 5% simple interest per annum for 3 years. How much interest does she pay?',opts:['$1 200','$400','$1 260','$2 400'],a:0,why:'Simple interest I = PRT/100 = (8 000 × 5 × 3)/100 = $1 200.',tech:'Read whether the question wants the interest or the total amount repaid. It is the commonest lost mark in this topic.'},
{id:'ma6',subj:'mathematics',strand:'ma-sets',level:7,diff:2,q:'In a class of 40 students, 25 study Spanish and 18 study French. 7 study both. How many study neither?',opts:['4','3','11','15'],a:0,why:'Students doing at least one = 25 + 18 − 7 = 36. Neither = 40 − 36 = 4.',tech:'Draw the Venn diagram and fill the intersection FIRST, then work outwards. Subtract the overlap so it is not counted twice.'},
{id:'ma7',subj:'mathematics',strand:'ma-measure',level:7,diff:2,q:'Find the area of a circle of radius 7 cm. Use π = 22/7.',opts:['154 cm²','44 cm²','49 cm²','308 cm²'],a:0,why:'A = πr² = 22/7 × 7 × 7 = 154 cm².',tech:'Area uses r², circumference uses 2r. Mixing them up is the single commonest circle error.'},
{id:'ma8',subj:'mathematics',strand:'ma-measure',level:8,diff:2,q:'A cylinder has radius 3 cm and height 10 cm. Taking π = 3.14, find its volume.',opts:['282.6 cm³','94.2 cm³','188.4 cm³','90 cm³'],a:0,why:'V = πr²h = 3.14 × 9 × 10 = 282.6 cm³.',tech:'Volume of any prism or cylinder = area of the cross-section × length. Learn one rule, not five.'},
{id:'ma9',subj:'mathematics',strand:'ma-stats',level:7,diff:1,q:'Find the mean of: 4, 7, 9, 12, 3',opts:['7','9','8','6'],a:0,why:'Sum = 35, and there are 5 values, so the mean = 35 ÷ 5 = 7.',tech:'Mean = add and divide. Median = order first, then take the middle. Mode = most frequent. Write the three definitions on your paper before you start the question.'},
{id:'ma10',subj:'mathematics',strand:'ma-stats',level:8,diff:2,q:'A bag contains 3 red and 5 blue marbles. One marble is drawn at random. What is the probability that it is red?',opts:['3/8','3/5','5/8','1/3'],a:0,why:'P(red) = number of red ÷ total = 3 ÷ 8 = 3/8.',tech:'The denominator is always the TOTAL. Count everything in the bag before you write the fraction.'},
{id:'ma11',subj:'mathematics',strand:'ma-algebra',level:6,diff:1,q:'Solve: 3x − 7 = 14',opts:['x = 7','x = 21','x = 2⅓','x = 3'],a:0,why:'Add 7 to both sides: 3x = 21. Divide by 3: x = 7.',tech:'Undo in reverse order — clear the addition or subtraction first, then the multiplication.'},
{id:'ma12',subj:'mathematics',strand:'ma-algebra',level:8,diff:2,q:'Factorise completely: x² + 5x + 6',opts:['(x + 2)(x + 3)','(x + 1)(x + 6)','(x − 2)(x − 3)','(x + 5)(x + 1)'],a:0,why:'Two numbers that multiply to 6 and add to 5 are 2 and 3, giving (x + 2)(x + 3).',tech:'Multiply your brackets back out to check. It takes ten seconds and catches every sign error.'},
{id:'ma13',subj:'mathematics',strand:'ma-algebra',level:8,diff:2,q:'Solve the pair: x + y = 10 and x − y = 4',opts:['x = 7, y = 3','x = 3, y = 7','x = 6, y = 4','x = 5, y = 5'],a:0,why:'Adding the equations eliminates y: 2x = 14, so x = 7. Substituting back gives y = 3.',tech:'When the same letter has opposite signs, ADD to eliminate. Same signs, subtract.'},
{id:'ma14',subj:'mathematics',strand:'ma-algebra',level:9,diff:3,q:'Solve: x² − 5x + 6 = 0',opts:['x = 2 or x = 3','x = −2 or x = −3','x = 1 or x = 6','x = 5 or x = 6'],a:0,why:'Factorising gives (x − 2)(x − 3) = 0, so x = 2 or x = 3.',tech:'A quadratic has two answers. Writing only one loses half the marks even when that one is right.'},
{id:'ma15',subj:'mathematics',strand:'ma-relations',level:8,diff:2,q:'Find the gradient of the line joining (1, 2) and (3, 8).',opts:['3','2','1/3','6'],a:0,why:'Gradient = (8 − 2) ÷ (3 − 1) = 6 ÷ 2 = 3.',tech:'Gradient is rise over run — the y difference on top. Taking them the other way up is the classic slip.'},
{id:'ma16',subj:'mathematics',strand:'ma-geom',level:7,diff:2,q:'What is the sum of the interior angles of a hexagon?',opts:['720°','1080°','540°','360°'],a:0,why:'Sum = (n − 2) × 180° = (6 − 2) × 180° = 720°.',tech:'Interior sum = (n − 2) × 180°. The EXTERIOR angles of any polygon always add to 360°.'},
{id:'ma17',subj:'mathematics',strand:'ma-geom',level:8,diff:2,q:'A right-angled triangle has legs of 6 cm and 8 cm. Find the hypotenuse.',opts:['10 cm','14 cm','48 cm','7 cm'],a:0,why:'By Pythagoras, h² = 6² + 8² = 36 + 64 = 100, so h = 10 cm.',tech:'The hypotenuse is always opposite the right angle and always the longest side. If your answer is smaller than a leg, it is wrong.'},
{id:'ma18',subj:'mathematics',strand:'ma-geom',level:9,diff:2,q:'What is the value of sin 30°?',opts:['0.5','1','0.866','0.577'],a:0,why:'sin 30° = 1/2 = 0.5. It comes from the half of an equilateral triangle.',tech:'Learn the exact values for 30°, 45° and 60°. They appear every year and save calculator time.'},
{id:'ma19',subj:'mathematics',strand:'ma-number',level:7,diff:1,q:'Divide $600 in the ratio 2 : 3. What is the LARGER share?',opts:['$360','$240','$300','$400'],a:0,why:'Total parts = 5, so one part = $120. The larger share is 3 parts = $360.',tech:'Always find the value of ONE part first. Then read carefully whether the question wants the larger or smaller share.'},
{id:'ma20',subj:'mathematics',strand:'ma-vectors',level:9,diff:3,q:'If a = (3, 1) and b = (−1, 4), find a + b.',opts:['(2, 5)','(4, −3)','(2, −3)','(−3, 4)'],a:0,why:'Add the matching components: (3 + (−1), 1 + 4) = (2, 5).',tech:'Add vectors component by component — never multiply them out. Keep the columns lined up on your page.'},

/* ============================ ENGLISH A ============================ */
{id:'ea1',subj:'english-a',strand:'ea-grammar',level:6,diff:1,q:'Choose the correct sentence.',opts:['Neither of the boys has finished his work.','Neither of the boys have finished their work.','Neither of the boys have finished his work.','Neither of the boys has finished their work.'],a:0,why:'"Neither" is singular, so it takes the singular verb "has" and the singular pronoun "his". The phrase "of the boys" does not change the subject.',tech:'Cover the phrase between the subject and the verb. The verb must agree with what is left.'},
{id:'ea2',subj:'english-a',strand:'ea-grammar',level:7,diff:2,q:'Which sentence uses the apostrophe correctly?',opts:['The students’ books were collected.','The students books’ were collected.','The student’s books were collected by all forty of them.','The students’s books were collected.'],a:0,why:'For a plural noun already ending in s, the apostrophe goes after the s: students’.',tech:'Ask who owns it. If the owner is plural and ends in s, apostrophe after. If singular, apostrophe then s.'},
{id:'ea3',subj:'english-a',strand:'ea-grammar',level:7,diff:2,q:'Identify the sentence with a dangling modifier.',opts:['Walking to school, the rain soaked Amara.','Walking to school, Amara was soaked by the rain.','As Amara walked to school, the rain soaked her.','Amara was soaked by the rain as she walked to school.'],a:0,why:'The opening phrase must describe the subject that follows. As written, the rain is walking to school.',tech:'After an -ing opening, the very next noun must be the one doing it. Check that noun every time.'},
{id:'ea4',subj:'english-a',strand:'ea-vocab',level:7,diff:2,q:'"The politician gave a *terse* reply." The word "terse" most nearly means:',opts:['brief and abrupt','long and detailed','warm and friendly','confused and unclear'],a:0,why:'Terse means using few words, often to the point of curtness.',tech:'When a word is unfamiliar, read the whole sentence for tone. The surrounding words usually narrow it to one option.'},
{id:'ea5',subj:'english-a',strand:'ea-comp',level:7,diff:2,q:'A question asks you to state what the writer IMPLIES about a character. This means you should:',opts:['work out what the writer suggests without stating directly','copy the sentence that describes the character','give your own opinion of the character','summarise the whole passage'],a:0,why:'To imply is to suggest indirectly. You infer it from the evidence rather than lifting a stated line.',tech:'"State" means lift it. "Suggest", "imply" or "infer" means work it out and then quote the evidence you used.'},
{id:'ea6',subj:'english-a',strand:'ea-summary',level:8,diff:3,q:'In a CSEC summary question, which is the MOST important rule?',opts:['Use your own words and keep within the word limit','Copy the best sentences from the passage','Include every example the writer gives','Write as much as you can to be safe'],a:0,why:'The summary tests whether you can identify main ideas and re-express them concisely in your own words within the stated limit.',tech:'Underline the main idea of each paragraph, then write one sentence per idea. Count your words — going over loses marks.'},
{id:'ea7',subj:'english-a',strand:'ea-arg',level:8,diff:2,q:'Which is the strongest thesis statement for an argumentative essay?',opts:['Secondary schools should ban mobile phones during class time because they measurably reduce concentration.','This essay is about mobile phones in school.','Mobile phones are a very interesting topic today.','There are many opinions about mobile phones in schools.'],a:0,why:'A thesis takes a clear, arguable position and signals the reason. The others announce a topic without arguing anything.',tech:'Your thesis must be something a reasonable person could disagree with. If nobody could argue back, it is not a thesis.'},
{id:'ea8',subj:'english-a',strand:'ea-narr',level:7,diff:2,q:'Which opening best shows rather than tells?',opts:['Her hands shook as she reached for the envelope.','She was very nervous about the envelope.','She felt nervous and worried and scared.','The envelope made her feel extremely nervous.'],a:0,why:'The physical detail of shaking hands lets the reader conclude she is nervous. The others simply name the emotion.',tech:'Show through action, gesture and detail. Naming the feeling is the fastest way to a mid-band mark.'},
{id:'ea9',subj:'english-a',strand:'ea-persuade',level:9,diff:2,q:'You must write a letter to the Principal requesting a change to the timetable. Which register is appropriate?',opts:['Formal and respectful, with a clear request and reasons','Casual and friendly, as if writing to a classmate','Emotional and demanding','Very short, with no explanation'],a:0,why:'Audience and purpose set register. A Principal is a formal audience, so the letter needs formal courtesy and reasoned support.',tech:'Before writing a directed piece, note the audience, purpose and format in the margin. Marks are awarded for all three.'},
{id:'ea10',subj:'english-a',strand:'ea-grammar',level:8,diff:2,q:'Which sentence is in the passive voice?',opts:['The report was written by the committee.','The committee wrote the report.','The committee is writing the report.','The committee will write the report.'],a:0,why:'In the passive, the subject receives the action. "The report" receives the writing, and the doer follows "by".',tech:'Passive = a form of "to be" + past participle. Useful in formal writing, but overusing it makes essays limp.'},

/* ============================ ENGLISH B ============================ */
{id:'eb1',subj:'english-b',strand:'eb-devices',level:6,diff:1,q:'"The wind whispered through the cane." This is an example of:',opts:['personification','simile','hyperbole','onomatopoeia'],a:0,why:'The wind is given a human ability — whispering — so it is personification.',tech:'Personification gives a human quality to something non-human. Simile needs "like" or "as".'},
{id:'eb2',subj:'english-b',strand:'eb-devices',level:6,diff:1,q:'"He was as stubborn as a mule." This is:',opts:['a simile','a metaphor','personification','an oxymoron'],a:0,why:'The comparison uses "as", which makes it a simile. A metaphor would say he WAS a mule.',tech:'Like or as → simile. Direct statement of one thing being another → metaphor.'},
{id:'eb3',subj:'english-b',strand:'eb-devices',level:7,diff:2,q:'"I have told you a million times." This is:',opts:['hyperbole','understatement','irony','alliteration'],a:0,why:'Hyperbole is deliberate exaggeration for effect — the speaker has not literally spoken a million times.',tech:'Do not just name the device. Say what EFFECT it creates — that is where the marks are.'},
{id:'eb4',subj:'english-b',strand:'eb-poetry',level:7,diff:2,q:'A poem with the rhyme scheme ABAB CDCD EFEF GG in fourteen lines is MOST likely:',opts:['a Shakespearean sonnet','a ballad','free verse','a haiku'],a:0,why:'Fourteen lines in three quatrains and a closing couplet with that scheme is the Shakespearean (English) sonnet form.',tech:'Count the lines first, then map the rhyme with letters down the margin. Form often points straight at the theme.'},
{id:'eb5',subj:'english-b',strand:'eb-poetry',level:7,diff:2,q:'The MOOD of a poem refers to:',opts:['the feeling the poem creates in the reader','the poet’s attitude to the subject','the number of syllables per line','the rhyme scheme'],a:0,why:'Mood is the atmosphere felt by the reader. The poet’s attitude is TONE — a different thing.',tech:'Tone belongs to the speaker, mood belongs to the reader. Examiners test that you can tell them apart.'},
{id:'eb6',subj:'english-b',strand:'eb-prose',level:8,diff:2,q:'In a novel, the term "protagonist" means:',opts:['the central character whose story we follow','the character who opposes the hero','the narrator of the story','the author’s spokesperson'],a:0,why:'The protagonist is the main character. The one who opposes them is the antagonist.',tech:'Do not assume the protagonist is likeable or the narrator. Many novels separate these deliberately.'},
{id:'eb7',subj:'english-b',strand:'eb-drama',level:8,diff:3,q:'Dramatic irony occurs when:',opts:['the audience knows something a character does not','a character says the opposite of what is meant','the ending is unexpected','two characters argue on stage'],a:0,why:'Dramatic irony depends on the gap between the audience’s knowledge and the character’s, which builds tension.',tech:'Verbal irony is in the words, situational irony is in the outcome, dramatic irony is in who knows what.'},
{id:'eb8',subj:'english-b',strand:'eb-essay',level:8,diff:3,q:'In a literature essay, the strongest paragraph structure is:',opts:['Point, Evidence, Explanation','Evidence, Point, Summary','Story retelling, then opinion','Quotation, then the next quotation'],a:0,why:'State the point, support it with a short quotation, then explain how that quotation proves the point and links to the question.',tech:'The Explanation is where most students lose marks. Never let a quotation stand without saying what it proves.'},
{id:'eb9',subj:'english-b',strand:'eb-short',level:7,diff:2,q:'Short stories usually differ from novels because they:',opts:['concentrate on a single effect or moment','always have a happy ending','contain no dialogue','are written only in the first person'],a:0,why:'The compressed form pushes a short story towards one central incident, effect or revelation.',tech:'In a short-story question, identify the turning point early — most questions circle back to it.'},
{id:'eb10',subj:'english-b',strand:'eb-devices',level:8,diff:2,q:'"The sea is a hungry dog" is:',opts:['a metaphor','a simile','alliteration','assonance'],a:0,why:'The sea is stated to BE a dog, with no "like" or "as", which makes it a metaphor.',tech:'When asked to comment on a metaphor, explain what quality is transferred — here, restless appetite and threat.'}
];

/* ===================== SCIENCES, HUMANITIES, LANGUAGES, TECHNICAL ===================== */
window.CSEC_QUESTIONS.push(

/* ---------------------------- PHYSICS ---------------------------- */
{id:'ph1',subj:'physics',strand:'ph-measure',level:6,diff:1,q:'The SI unit of force is the:',opts:['newton','joule','watt','pascal'],a:0,why:'Force is measured in newtons (N). The joule is energy, the watt is power and the pascal is pressure.',tech:'Learn the unit with the quantity from Form 1. Paper 01 gives away marks for units every single year.'},
{id:'ph2',subj:'physics',strand:'ph-mech',level:7,diff:1,q:'A runner covers 100 m in 20 s. What is the average speed?',opts:['5 m/s','2 000 m/s','0.2 m/s','20 m/s'],a:0,why:'Speed = distance ÷ time = 100 ÷ 20 = 5 m/s.',tech:'Write the formula, substitute, then compute. Examiners award a mark for the correct formula even if the arithmetic slips.'},
{id:'ph3',subj:'physics',strand:'ph-mech',level:7,diff:2,q:'A block has mass 200 g and volume 100 cm³. Find its density.',opts:['2 g/cm³','0.5 g/cm³','20 000 g/cm³','100 g/cm³'],a:0,why:'Density = mass ÷ volume = 200 ÷ 100 = 2 g/cm³.',tech:'Check the units match before dividing. Grams with cm³, kilograms with m³ — never mix them.'},
{id:'ph4',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'Newton’s Third Law states that:',opts:['for every action there is an equal and opposite reaction','force equals mass times acceleration','an object stays at rest unless acted on by a force','energy cannot be created or destroyed'],a:0,why:'The Third Law describes paired forces acting on two different bodies, equal in size and opposite in direction.',tech:'The action-reaction pair acts on DIFFERENT objects. That is why they never cancel each other out.'},
{id:'ph5',subj:'physics',strand:'ph-waves',level:8,diff:2,q:'A wave has frequency 50 Hz and wavelength 2 m. Find its speed.',opts:['100 m/s','25 m/s','52 m/s','0.04 m/s'],a:0,why:'v = fλ = 50 × 2 = 100 m/s.',tech:'v = fλ is the one wave equation you must never forget. Rearrange it rather than learning three versions.'},
{id:'ph6',subj:'physics',strand:'ph-waves',level:7,diff:1,q:'When light reflects from a plane mirror, the angle of incidence is:',opts:['equal to the angle of reflection','twice the angle of reflection','always 90°','always zero'],a:0,why:'The law of reflection states that the angle of incidence equals the angle of reflection, both measured from the normal.',tech:'Both angles are measured from the NORMAL, not from the mirror surface. Draw the normal first.'},
{id:'ph7',subj:'physics',strand:'ph-elec',level:8,diff:2,q:'A 12 V supply drives current through a 4 Ω resistor. What is the current?',opts:['3 A','48 A','0.33 A','8 A'],a:0,why:'By Ohm’s law, I = V ÷ R = 12 ÷ 4 = 3 A.',tech:'V = IR. Cover the quantity you want with your finger to see whether to multiply or divide.'},
{id:'ph8',subj:'physics',strand:'ph-thermal',level:9,diff:2,q:'Latent heat is the energy needed to:',opts:['change the state of a substance without changing its temperature','raise the temperature of a substance','melt only solids','boil only liquids'],a:0,why:'During a change of state, the energy supplied breaks bonds between particles rather than raising temperature.',tech:'On a heating curve, the flat sections are where latent heat is being absorbed. Point to them in your answer.'},
{id:'ph9',subj:'physics',strand:'ph-atom',level:9,diff:3,q:'A radioactive sample has a half-life of 5 days. What fraction remains after 15 days?',opts:['1/8','1/3','1/15','1/5'],a:0,why:'15 days is three half-lives. After each one the amount halves: 1 → 1/2 → 1/4 → 1/8.',tech:'Count how many half-lives fit into the time given, then halve that many times. Never divide by the number of days.'},
{id:'ph10',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'The moment of a force about a point is calculated as:',opts:['force × perpendicular distance from the point','force ÷ distance','force + distance','mass × acceleration'],a:0,why:'Moment = F × d, where d is the perpendicular distance from the pivot to the line of action of the force.',tech:'The distance must be PERPENDICULAR. If the force is at an angle, resolve it or use the perpendicular distance.'},

/* ---------------------------- CHEMISTRY ---------------------------- */
{id:'ch1',subj:'chemistry',strand:'ch-matter',level:6,diff:1,q:'Which method best separates sand from water?',opts:['filtration','distillation','chromatography','evaporation'],a:0,why:'Sand is insoluble, so it stays on the filter paper while water passes through as the filtrate.',tech:'Ask whether the solid dissolves. Insoluble → filter. Soluble and you want the solid → evaporate. Want the liquid → distil.'},
{id:'ch2',subj:'chemistry',strand:'ch-matter',level:7,diff:2,q:'Which technique would you use to separate the dyes in a sample of ink?',opts:['paper chromatography','filtration','decanting','magnetic separation'],a:0,why:'Chromatography separates dissolved substances by how far each travels up the paper with the solvent.',tech:'Always draw the pencil baseline ABOVE the solvent level. A pen line would dissolve and ruin the run.'},
{id:'ch3',subj:'chemistry',strand:'ch-atomic',level:7,diff:1,q:'The atomic number of an element tells you the number of:',opts:['protons in the nucleus','neutrons in the nucleus','protons and neutrons together','electron shells'],a:0,why:'Atomic number = proton number. In a neutral atom it also equals the number of electrons.',tech:'Mass number − atomic number = neutrons. Write that line at the top of the page in every structure question.'},
{id:'ch4',subj:'chemistry',strand:'ch-atomic',level:8,diff:2,q:'An ionic bond is formed when:',opts:['electrons are transferred from a metal to a non-metal','electrons are shared between two non-metals','protons move between atoms','atoms exchange neutrons'],a:0,why:'The metal loses electrons to form a positive ion and the non-metal gains them to form a negative ion; opposite charges attract.',tech:'Metal + non-metal → ionic. Non-metal + non-metal → covalent. That one line answers most bonding questions.'},
{id:'ch5',subj:'chemistry',strand:'ch-acids',level:7,diff:1,q:'A solution with pH 3 is:',opts:['acidic','alkaline','neutral','a strong base'],a:0,why:'The pH scale runs 0 to 14. Below 7 is acidic, 7 is neutral and above 7 is alkaline.',tech:'The LOWER the pH, the STRONGER the acid. Students routinely reverse this under pressure.'},
{id:'ch6',subj:'chemistry',strand:'ch-acids',level:8,diff:2,q:'Complete the general equation: acid + base →',opts:['salt + water','salt + hydrogen','salt + carbon dioxide + water','hydrogen + oxygen'],a:0,why:'Neutralisation of an acid by a base produces a salt and water only.',tech:'Acid + metal → salt + hydrogen. Acid + carbonate → salt + water + carbon dioxide. Learn all three pairs together.'},
{id:'ch7',subj:'chemistry',strand:'ch-mole',level:9,diff:2,q:'What is the relative molecular mass of water, H₂O? (H = 1, O = 16)',opts:['18','17','32','20'],a:0,why:'(2 × 1) + 16 = 18.',tech:'Multiply each atomic mass by the number of that atom BEFORE adding. The subscript applies only to the atom it follows.'},
{id:'ch8',subj:'chemistry',strand:'ch-organic',level:9,diff:2,q:'The general formula of the alkanes is:',opts:['CₙH₂ₙ₊₂','CₙH₂ₙ','CₙH₂ₙ₋₂','CₙHₙ'],a:0,why:'Alkanes are saturated hydrocarbons with only single bonds, giving CₙH₂ₙ₊₂. Alkenes are CₙH₂ₙ.',tech:'Alkane = all single bonds, saturated. Alkene = one double bond, unsaturated, decolourises bromine water.'},
{id:'ch9',subj:'chemistry',strand:'ch-inorg',level:9,diff:2,q:'A gas turns limewater milky. The gas is:',opts:['carbon dioxide','oxygen','hydrogen','ammonia'],a:0,why:'Carbon dioxide reacts with limewater (calcium hydroxide) to form insoluble calcium carbonate, which makes it cloudy.',tech:'Learn the four gas tests as a set: CO₂ milky limewater, O₂ relights a glowing splint, H₂ pops, NH₃ turns damp red litmus blue.'},
{id:'ch10',subj:'chemistry',strand:'ch-redox',level:9,diff:3,q:'During electrolysis, positive ions move towards the:',opts:['cathode','anode','electrolyte','battery'],a:0,why:'Positive ions (cations) are attracted to the negative electrode, which is the cathode, where they gain electrons.',tech:'Remember PANIC — Positive is Anode, Negative Is Cathode. Then cations go to the cathode.'},

/* ---------------------------- BIOLOGY ---------------------------- */
{id:'bi1',subj:'biology',strand:'bi-cells',level:6,diff:1,q:'Which structure is found in a plant cell but NOT in an animal cell?',opts:['cell wall','nucleus','cytoplasm','cell membrane'],a:0,why:'The cellulose cell wall, chloroplasts and a large permanent vacuole are plant features. All four options exist in both, except the cell wall.',tech:'Learn the three plant-only structures as a set: cell wall, chloroplast, large vacuole.'},
{id:'bi2',subj:'biology',strand:'bi-cells',level:7,diff:2,q:'Osmosis is the movement of:',opts:['water from high to low water potential through a partially permeable membrane','any substance from high to low concentration','water against a concentration gradient using energy','solutes through a membrane'],a:0,why:'Osmosis is specifically water moving down its water-potential gradient through a partially permeable membrane.',tech:'Say WATER and say PARTIALLY PERMEABLE MEMBRANE. A definition missing either word rarely scores full marks.'},
{id:'bi3',subj:'biology',strand:'bi-nutri',level:7,diff:2,q:'Which are the raw materials for photosynthesis?',opts:['carbon dioxide and water','oxygen and glucose','glucose and water','nitrogen and water'],a:0,why:'Carbon dioxide + water, in the presence of light and chlorophyll, produce glucose and oxygen.',tech:'Write the word equation before answering any photosynthesis question. It settles inputs versus outputs instantly.'},
{id:'bi4',subj:'biology',strand:'bi-nutri',level:8,diff:2,q:'Enzymes are:',opts:['proteins that speed up reactions and are affected by temperature and pH','carbohydrates that provide energy','lipids that store energy','minerals used in respiration'],a:0,why:'Enzymes are protein catalysts. High temperature or the wrong pH denatures the active site.',tech:'Use the word DENATURED, not "killed". Enzymes are molecules, not living things — that wording costs marks.'},
{id:'bi5',subj:'biology',strand:'bi-resp',level:8,diff:2,q:'The products of aerobic respiration in humans are:',opts:['carbon dioxide, water and energy','lactic acid and energy','glucose and oxygen','alcohol and carbon dioxide'],a:0,why:'Glucose + oxygen → carbon dioxide + water + energy. Lactic acid comes from ANAEROBIC respiration in muscle.',tech:'Anaerobic in muscle gives lactic acid; in yeast it gives alcohol and CO₂. Keep the two organisms separate.'},
{id:'bi6',subj:'biology',strand:'bi-nutri',level:7,diff:1,q:'Red blood cells transport oxygen because they contain:',opts:['haemoglobin','plasma','platelets','antibodies'],a:0,why:'Haemoglobin binds oxygen to form oxyhaemoglobin in the lungs and releases it in the tissues.',tech:'Match each blood component to its job: red cells oxygen, white cells defence, platelets clotting, plasma transport.'},
{id:'bi7',subj:'biology',strand:'bi-env',level:6,diff:1,q:'In a food chain, the first organism is always:',opts:['a producer','a herbivore','a carnivore','a decomposer'],a:0,why:'Food chains begin with a producer — usually a green plant that makes its own food by photosynthesis.',tech:'The arrows in a food chain show the direction ENERGY flows, not who eats whom. Draw them pointing away from the producer.'},
{id:'bi8',subj:'biology',strand:'bi-genes',level:9,diff:3,q:'A plant with genotype Tt is crossed with tt. What proportion of offspring will be tall if T is dominant?',opts:['50%','100%','75%','25%'],a:0,why:'The Punnett square gives Tt, Tt, tt, tt — half carry the dominant allele, so 50% are tall.',tech:'Always draw the Punnett square. An answer without it loses the method marks even when the ratio is right.'},
{id:'bi9',subj:'biology',strand:'bi-resp',level:8,diff:2,q:'Which is an example of EXCRETION rather than egestion?',opts:['removal of urea in urine','removal of faeces from the anus','removal of undigested fibre','removal of food that was never absorbed'],a:0,why:'Excretion removes waste made by the body’s own metabolism, such as urea. Egestion removes material that was never absorbed.',tech:'If the body MADE it, that is excretion. If it merely passed through, that is egestion.'},
{id:'bi10',subj:'biology',strand:'bi-health',level:8,diff:2,q:'Which disease is caused by a vector-borne virus common in the Caribbean?',opts:['dengue','diabetes','anaemia','asthma'],a:0,why:'Dengue is a viral disease transmitted by the Aedes aegypti mosquito, which is the vector. The others are not infectious.',tech:'Name the pathogen AND the vector when a question asks about transmission. Both carry marks.'},

/* ---------------------------- GEOGRAPHY ---------------------------- */
{id:'ge1',subj:'geography',strand:'ge-maps',level:6,diff:2,q:'When giving a grid reference, you read:',opts:['eastings first, then northings','northings first, then eastings','the largest number first','the contour value first'],a:0,why:'The convention is along the corridor then up the stairs — eastings (across) before northings (up).',tech:'"Along the corridor, up the stairs." Say it out loud in the exam; it prevents a reversed reference.'},
{id:'ge2',subj:'geography',strand:'ge-maps',level:7,diff:2,q:'On a map, contour lines drawn very close together indicate:',opts:['a steep slope','a gentle slope','flat land','a valley floor'],a:0,why:'Closely spaced contours mean a large height change over a short horizontal distance, which is a steep slope.',tech:'Close = steep, wide = gentle. Check the contour interval in the key before describing any relief.'},
{id:'ge3',subj:'geography',strand:'ge-tectonic',level:8,diff:2,q:'Volcanoes and earthquakes in the Eastern Caribbean occur mainly at a:',opts:['destructive (convergent) plate boundary','constructive plate boundary','conservative plate boundary','the centre of a plate'],a:0,why:'The Atlantic plate subducts beneath the Caribbean plate, producing the volcanic island arc of the Lesser Antilles.',tech:'Name the actual plates in your answer — Atlantic and Caribbean. Generic answers score in the lowest band.'},
{id:'ge4',subj:'geography',strand:'ge-weather',level:7,diff:1,q:'The Atlantic hurricane season officially runs from:',opts:['1 June to 30 November','1 January to 30 June','1 March to 31 August','1 September to 31 December'],a:0,why:'The official Atlantic hurricane season is 1 June to 30 November, when sea temperatures and conditions favour formation.',tech:'Learn the conditions needed too: sea above about 27 °C, low wind shear, and distance from the equator for the Coriolis effect.'},
{id:'ge5',subj:'geography',strand:'ge-weather',level:8,diff:2,q:'Relief rainfall occurs when:',opts:['moist air is forced to rise over high ground, cools and condenses','the ground heats and air rises by convection','two air masses of different temperature meet','cold air sinks over the sea'],a:0,why:'Air forced up a mountain barrier cools, condenses and rains on the windward side, leaving a rain shadow to leeward.',tech:'Three rainfall types: relief, convectional and frontal. Say which side is windward and name the rain shadow.'},
{id:'ge6',subj:'geography',strand:'ge-pop',level:7,diff:2,q:'Population density is calculated as:',opts:['total population ÷ land area','total population × land area','births minus deaths','population ÷ number of households'],a:0,why:'Density is people per square kilometre — population divided by area.',tech:'Density is how crowded; distribution is where people are. Questions often ask for one and students answer the other.'},
{id:'ge7',subj:'geography',strand:'ge-econ',level:8,diff:2,q:'Which is Trinidad and Tobago’s most important export sector by value?',opts:['petroleum and petrochemicals','tourism','agriculture','textiles'],a:0,why:'Oil, natural gas and downstream petrochemicals such as ammonia and methanol dominate the country’s export earnings.',tech:'For any Caribbean economy question, know one named example in detail rather than four in outline.'},
{id:'ge8',subj:'geography',strand:'ge-hazard',level:8,diff:2,q:'Which is a MITIGATION measure against earthquake damage?',opts:['enforcing building codes for earthquake-resistant construction','issuing a warning one hour before','evacuating after the shaking stops','rebuilding in the same way afterwards'],a:0,why:'Mitigation reduces impact before an event. Earthquakes cannot yet be predicted, so resistant construction is the main defence.',tech:'Separate preparation, mitigation and response in your notes. Questions almost always name one of the three.'},

/* ---------------------------- HISTORY ---------------------------- */
{id:'hi1',subj:'history',strand:'hi-indigenous',level:6,diff:1,q:'The indigenous people who mainly settled the Greater Antilles before European contact were the:',opts:['Taino','Maya','Aztec','Inca'],a:0,why:'The Taino occupied the Greater Antilles and the Bahamas. The Kalinago were concentrated in the Lesser Antilles.',tech:'Keep Taino and Kalinago straight by geography — Greater Antilles versus Lesser Antilles.'},
{id:'hi2',subj:'history',strand:'hi-indigenous',level:6,diff:1,q:'Columbus first reached the Caribbean in the year:',opts:['1492','1592','1445','1502'],a:0,why:'Columbus made landfall in the Bahamas in October 1492 on his first voyage.',tech:'Anchor the syllabus to a handful of dates: 1492, 1834, 1838, 1845, 1937, 1962. Everything else hangs off them.'},
{id:'hi3',subj:'history',strand:'hi-slavery',level:7,diff:2,q:'The Sugar Revolution in the Caribbean led MOST directly to:',opts:['a large increase in the demand for enslaved African labour','the end of plantation agriculture','the growth of small peasant farms','a decline in European settlement'],a:0,why:'Sugar required large estates and heavy year-round labour, which planters met by massively expanding the trade in enslaved Africans.',tech:'"Most directly" means pick the immediate consequence, not a later one. Read that phrase carefully.'},
{id:'hi4',subj:'history',strand:'hi-slavery',level:7,diff:2,q:'The Middle Passage refers to the:',opts:['voyage of enslaved Africans across the Atlantic to the Americas','journey of sugar from the Caribbean to Europe','march of captives to the African coast','return voyage of ships to Europe'],a:0,why:'It is the middle leg of the triangular trade, carrying enslaved Africans from West Africa to the Americas.',tech:'Be able to name all three legs of the triangular trade and the cargo on each.'},
{id:'hi5',subj:'history',strand:'hi-resist',level:8,diff:2,q:'The Haitian Revolution (1791–1804) is significant because it:',opts:['produced the first independent Black republic in the world','restored French control of Saint-Domingue','ended slavery throughout the Caribbean at once','was led by British abolitionists'],a:0,why:'The revolution defeated French, Spanish and British forces and established Haiti as the first Black republic in 1804.',tech:'Link Toussaint Louverture and Dessalines to their stages of the revolution. Named leaders lift an essay out of the middle band.'},
{id:'hi6',subj:'history',strand:'hi-emanc',level:8,diff:2,q:'Full freedom for the formerly enslaved in the British Caribbean came in:',opts:['1838, at the end of apprenticeship','1834, when the Act took effect','1833, when the Act was passed','1845'],a:0,why:'Emancipation took effect in 1834 but bound most people to apprenticeship. Full freedom came when apprenticeship ended in 1838.',tech:'1833 passed, 1834 in force, 1838 full freedom. Examiners test whether you know all three are different.'},
{id:'hi7',subj:'history',strand:'hi-adjust',level:8,diff:2,q:'The first ship carrying Indian indentured immigrants to Trinidad arrived in 1845. It was the:',opts:['Fatel Razack','Mayflower','Windrush','Santa Maria'],a:0,why:'The Fatel Razack arrived on 30 May 1845, an event now marked as Indian Arrival Day in Trinidad and Tobago.',tech:'For a Trinidad-based candidate this is a gift topic. Know the push and pull factors behind indentureship as well as the date.'},
{id:'hi8',subj:'history',strand:'hi-indep',level:9,diff:2,q:'The labour disturbances of 1937 in Trinidad were led in the oilfields by:',opts:['Uriah "Buzz" Butler','Eric Williams','Norman Manley','Alexander Bustamante'],a:0,why:'Butler led the oilfield workers’ protests of 1937, which fed directly into the growth of the trade union movement.',tech:'The 1930s labour unrest is the bridge from colonial rule to independence. Every "movements towards independence" essay should mention it.'},
{id:'hi9',subj:'history',strand:'hi-indep',level:9,diff:2,q:'The West Indies Federation existed between:',opts:['1958 and 1962','1945 and 1950','1962 and 1970','1973 and 1980'],a:0,why:'The Federation was formed in 1958 and dissolved in 1962 after Jamaica’s withdrawal following its referendum.',tech:'Do not confuse the Federation (1958–62) with CARICOM (1973). They are different bodies with different aims.'},
{id:'hi10',subj:'history',strand:'hi-skills',level:7,diff:2,q:'When a History question says "Explain TWO reasons", the best approach is to:',opts:['state each reason and develop it with specific evidence','list as many reasons as you can remember','describe the events in the order they happened','give your personal opinion'],a:0,why:'"Explain" requires reasons developed with supporting detail. Listing without development scores in the lowest band.',tech:'If it says TWO, give exactly two and develop both. A third undeveloped reason earns nothing and costs time.'},

/* ------------------------- SOCIAL STUDIES ------------------------- */
{id:'ss1',subj:'social-studies',strand:'ss-family',level:6,diff:1,q:'A family consisting of a mother, father and their children only is called a:',opts:['nuclear family','extended family','sibling household','single-parent family'],a:0,why:'The nuclear family is two parents and their children. Adding grandparents, aunts or uncles makes it extended.',tech:'Learn the family types with one Caribbean example each. Examples are what separate a Grade I from a Grade III.'},
{id:'ss2',subj:'social-studies',strand:'ss-family',level:7,diff:2,q:'Which is the PRIMARY agent of socialisation?',opts:['the family','the school','the media','peer groups'],a:0,why:'The family is primary because it is the first and most influential agent, shaping values before any other institution.',tech:'Primary means first and most formative. School, peers, media and religion are secondary agents.'},
{id:'ss3',subj:'social-studies',strand:'ss-region',level:8,diff:2,q:'CARICOM was established by the Treaty of Chaguaramas in:',opts:['1973','1958','1962','1989'],a:0,why:'The Treaty of Chaguaramas established the Caribbean Community and Common Market in 1973.',tech:'1973 CARICOM, 1989 Grand Anse Declaration leading to the CSME. Two dates, two different achievements.'},
{id:'ss4',subj:'social-studies',strand:'ss-region',level:8,diff:2,q:'The CSME is intended to allow the free movement of:',opts:['goods, services, capital and skilled labour','goods only','people on holiday only','currency only'],a:0,why:'The CARICOM Single Market and Economy provides for free movement of goods, services, capital and approved categories of skilled labour.',tech:'Note that labour movement is for APPROVED CATEGORIES, not everyone. That precision earns the mark.'},
{id:'ss5',subj:'social-studies',strand:'ss-gov',level:7,diff:2,q:'In Trinidad and Tobago, the arm of government that makes laws is the:',opts:['legislature','judiciary','executive','civil service'],a:0,why:'The legislature (Parliament) makes law, the executive implements it and the judiciary interprets it.',tech:'Three arms, three verbs: make, implement, interpret. That sentence answers half the government questions.'},
{id:'ss6',subj:'social-studies',strand:'ss-research',level:9,diff:2,q:'In an SBA, the statement of the problem should:',opts:['clearly identify what is being investigated and where','list all your findings','thank everyone who helped','describe your conclusion'],a:0,why:'The statement of the problem sets out the specific issue, the location and the scope of the investigation.',tech:'Keep the statement narrow enough to research with one questionnaire. Broad topics cannot be evidenced and lose marks.'},

/* ---------------------------- SPANISH ---------------------------- */
{id:'sp1',subj:'spanish',strand:'sp-gram',level:6,diff:1,q:'Complete: "Yo ___ estudiante."',opts:['soy','estoy','tengo','es'],a:0,why:'"Ser" is used for permanent characteristics and identity, so "yo soy estudiante".',tech:'SER for identity, origin and permanent traits. ESTAR for location and temporary states. It is tested every year.'},
{id:'sp2',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'Complete: "La biblioteca ___ cerca de la escuela."',opts:['está','es','son','tiene'],a:0,why:'Location always takes "estar", so "la biblioteca está cerca".',tech:'If the sentence says WHERE something is, use estar — with no exceptions at CSEC level.'},
{id:'sp3',subj:'spanish',strand:'sp-gram',level:8,diff:2,q:'What is the "yo" form of "hablar" in the preterite tense?',opts:['hablé','hablo','hablaba','hablaré'],a:0,why:'The preterite yo form of an -ar verb ends in -é: hablé (I spoke).',tech:'Preterite = completed action. Imperfect = used to / was doing. The accent on -é is part of the mark.'},
{id:'sp4',subj:'spanish',strand:'sp-themes',level:6,diff:1,q:'"¿Cómo te llamas?" means:',opts:['What is your name?','How are you?','Where do you live?','How old are you?'],a:0,why:'Literally "how do you call yourself" — it asks for the person’s name.',tech:'Learn the core question words as a block: qué, quién, dónde, cuándo, cómo, por qué, cuánto.'},
{id:'sp5',subj:'spanish',strand:'sp-themes',level:6,diff:1,q:'Which is the correct definite article: "___ casa"?',opts:['la','el','los','las'],a:0,why:'"Casa" is a feminine singular noun, so it takes "la".',tech:'Most nouns ending in -a are feminine and -o masculine. Learn the exceptions (el día, la mano) as a short list.'},
{id:'sp6',subj:'spanish',strand:'sp-read',level:7,diff:2,q:'A sign reads "PROHIBIDO FUMAR". It means:',opts:['No smoking','No entry','No parking','No photographs'],a:0,why:'"Prohibido" means forbidden and "fumar" means to smoke.',tech:'In the reading paper, signs and notices come first and are the quickest marks. Do not rush them.'},

/* ---------------------------- FRENCH ---------------------------- */
{id:'fr1',subj:'french',strand:'fr-gram',level:6,diff:1,q:'Complete: "Je ___ quatorze ans."',opts:['ai','suis','est','as'],a:0,why:'French expresses age with "avoir" — j’ai quatorze ans, literally "I have fourteen years".',tech:'Age, hunger, thirst and fear all use AVOIR in French, not être. English speakers reach for "suis" and lose the mark.'},
{id:'fr2',subj:'french',strand:'fr-gram',level:8,diff:2,q:'Which auxiliary does "aller" take in the passé composé?',opts:['être','avoir','faire','venir'],a:0,why:'"Aller" is one of the verbs of motion that take "être": je suis allé(e).',tech:'Learn the être verbs with DR & MRS VANDERTRAMP, and remember the past participle must agree with the subject.'},
{id:'fr3',subj:'french',strand:'fr-themes',level:6,diff:1,q:'"Comment t’appelles-tu ?" means:',opts:['What is your name?','How old are you?','Where are you from?','How are you?'],a:0,why:'Literally "how do you call yourself" — it asks for the name.',tech:'Do not confuse it with "Comment ça va ?" which asks how you are.'},
{id:'fr4',subj:'french',strand:'fr-gram',level:6,diff:1,q:'Which is the correct definite article: "___ école"?',opts:['l’','le','la','les'],a:0,why:'"École" begins with a vowel, so le/la elides to l’.',tech:'Before a vowel or silent h, le and la both become l’. The gender still matters for adjective agreement.'},
{id:'fr5',subj:'french',strand:'fr-read',level:7,diff:2,q:'A notice reads "DÉFENSE DE STATIONNER". It means:',opts:['No parking','No smoking','No entry','Do not touch'],a:0,why:'"Stationner" means to park, and "défense de" means it is forbidden.',tech:'"Défense de" and "interdit" both mean forbidden. Learn the common public notices — they are free marks.'},
{id:'fr6',subj:'french',strand:'fr-write',level:8,diff:2,q:'In a CSEC directed writing task with a 130–150 word limit, writing 200 words will:',opts:['lose marks, because the limit is part of the task','gain marks for extra detail','make no difference','only matter in the oral'],a:0,why:'The word limit is a stated requirement; exceeding it is penalised regardless of quality.',tech:'Count in blocks of ten as you write. Finishing inside the limit is worth more than one extra idea.'},

/* -------------------------- VISUAL ARTS -------------------------- */
{id:'va1',subj:'visual-arts',strand:'va-elements',level:6,diff:1,q:'The three primary colours are:',opts:['red, yellow and blue','red, green and blue','orange, green and purple','black, white and grey'],a:0,why:'In pigment, red, yellow and blue cannot be mixed from other colours and combine to make the secondaries.',tech:'Primary → secondary → tertiary. Be ready to name which two primaries make each secondary.'},
{id:'va2',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Which pair are complementary colours?',opts:['red and green','red and orange','blue and purple','yellow and orange'],a:0,why:'Complementary colours sit opposite each other on the colour wheel. Red faces green, blue faces orange, yellow faces purple.',tech:'Complementary pairs placed together intensify each other. Say that effect when you use the term in a critique.'},
{id:'va3',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Balance, rhythm, contrast and unity are:',opts:['principles of design','elements of art','types of media','art movements'],a:0,why:'Elements are the building blocks — line, shape, colour, texture, form, space, value. Principles are how they are arranged.',tech:'Elements are WHAT you use, principles are HOW you arrange them. Critique questions want both.'},
{id:'va4',subj:'visual-arts',strand:'va-draw',level:8,diff:2,q:'In one-point perspective, all receding parallel lines converge at:',opts:['a single vanishing point on the horizon','two vanishing points','the centre of the paper','the top corner'],a:0,why:'One-point perspective has a single vanishing point on the eye-level horizon line.',tech:'Draw the horizon line and mark the vanishing point before anything else. Freehand guessing is visible to the examiner.'},

/* ------------------- PHYSICAL EDUCATION & SPORT ------------------- */
{id:'pe1',subj:'physical-education',strand:'pe-fitness',level:6,diff:1,q:'Which is a component of HEALTH-related fitness?',opts:['cardiovascular endurance','agility','reaction time','coordination'],a:0,why:'Health-related components are cardiovascular endurance, muscular strength, muscular endurance, flexibility and body composition. Agility, reaction time and coordination are skill-related.',tech:'Learn the five health-related and six skill-related components as two separate lists. Questions test the split.'},
{id:'pe2',subj:'physical-education',strand:'pe-injury',level:7,diff:1,q:'RICE, the immediate treatment for a soft-tissue injury, stands for:',opts:['Rest, Ice, Compression, Elevation','Run, Ice, Cool, Exercise','Rest, Injure, Cool, Extend','Rest, Immobilise, Cover, Elevate'],a:0,why:'Rest, Ice, Compression and Elevation limit swelling and pain in the first 48 hours after a sprain or strain.',tech:'Be able to say WHY each step works — reduces blood flow, limits swelling. Naming alone is a one-mark answer.'},
{id:'pe3',subj:'physical-education',strand:'pe-fitness',level:7,diff:2,q:'The FITT principle stands for:',opts:['Frequency, Intensity, Time, Type','Fitness, Interval, Training, Technique','Force, Impact, Tempo, Timing','Flexibility, Intensity, Training, Type'],a:0,why:'FITT is the framework for designing a training programme: how often, how hard, how long and what kind.',tech:'Apply FITT to a named sport in your answer. Generic programmes score low.'},
{id:'pe4',subj:'physical-education',strand:'pe-anatomy',level:8,diff:2,q:'Which is NOT a function of the skeleton?',opts:['production of hormones for growth','support of the body','protection of vital organs','production of blood cells'],a:0,why:'The skeleton supports, protects, allows movement, stores minerals and makes blood cells in the marrow. Hormones are made by the endocrine glands.',tech:'"NOT" questions catch tired candidates. Underline the word NOT before you look at the options.'},
{id:'pe5',subj:'physical-education',strand:'pe-nutri',level:7,diff:2,q:'Which nutrient is the body’s MAIN source of energy for high-intensity exercise?',opts:['carbohydrate','protein','fat','vitamins'],a:0,why:'Carbohydrate is broken down to glucose, the fastest fuel available and the one used at high intensity.',tech:'Fat fuels low-intensity endurance work; protein is for growth and repair, not a main fuel.'},

/* --------------------- INFORMATION TECHNOLOGY --------------------- */
{id:'it1',subj:'information-technology',strand:'it-hardware',level:6,diff:1,q:'Which of the following is an INPUT device?',opts:['scanner','monitor','printer','speaker'],a:0,why:'A scanner sends data into the computer. Monitors, printers and speakers all output data.',tech:'Ask which way the data flows — into the machine is input, out of it is output.'},
{id:'it2',subj:'information-technology',strand:'it-hardware',level:7,diff:2,q:'RAM is described as volatile because it:',opts:['loses its contents when power is removed','can be written to only once','stores data permanently','is slower than the hard disk'],a:0,why:'Volatile memory needs continuous power. Switch the machine off and RAM is cleared; ROM and disk storage are not.',tech:'RAM volatile and temporary, ROM non-volatile and permanent. One sentence, several marks a year.'},
{id:'it3',subj:'information-technology',strand:'it-data',level:7,diff:2,q:'The binary number 1011 is equal to which decimal number?',opts:['11','13','9','15'],a:0,why:'Place values 8, 4, 2, 1 give (1×8) + (0×4) + (1×2) + (1×1) = 11.',tech:'Write the place values 8 4 2 1 above the digits before converting. It removes the guesswork.'},
{id:'it4',subj:'information-technology',strand:'it-solve',level:8,diff:2,q:'In a flowchart, the diamond shape represents:',opts:['a decision','a process','input or output','the start or end'],a:0,why:'The diamond is a decision with two exit paths, normally labelled Yes and No.',tech:'Oval start/stop, parallelogram input/output, rectangle process, diamond decision. Label BOTH branches of every diamond.'},
{id:'it5',subj:'information-technology',strand:'it-productivity',level:7,diff:2,q:'In a spreadsheet, which formula adds the values in cells A1 to A10?',opts:['=SUM(A1:A10)','=ADD(A1:A10)','=TOTAL(A1-A10)','=SUM(A1+A10)'],a:0,why:'SUM with a colon range adds every cell from A1 through A10 inclusive.',tech:'Every formula starts with =. The colon means a RANGE; a comma means a list of separate cells.'},
{id:'it6',subj:'information-technology',strand:'it-impact',level:8,diff:2,q:'Checking that a date of birth entered as 32/13/2011 is impossible is an example of:',opts:['validation','verification','encryption','compression'],a:0,why:'Validation checks that data is reasonable and within allowed limits. Verification checks it was copied accurately.',tech:'Validation = sensible. Verification = accurate. Give an example of each and the marks follow.'},
{id:'it7',subj:'information-technology',strand:'it-solve',level:9,diff:3,q:'In an IPO chart, the "P" stands for:',opts:['Processing','Program','Print','Procedure'],a:0,why:'IPO stands for Input, Processing and Output — the three stages of defining a problem before designing an algorithm.',tech:'Fill the Output column first. Knowing what you must produce tells you what inputs and processing you need.'}
);

/* ===================== Launch top-up — brings every default subject to 12+ ===================== */
window.CSEC_QUESTIONS.push(

/* ------------------------------- SPANISH ------------------------------- */
{id:'sp7',subj:'spanish',strand:'sp-gram',level:6,diff:1,q:'Which is the correct plural: "___ libros"?',opts:['los','las','el','la'],a:0,why:'"Libro" is masculine, so the masculine plural article is "los".',tech:'Singular el/la become plural los/las. The noun takes -s (or -es after a consonant).'},
{id:'sp8',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'"Tengo que estudiar" means:',opts:['I have to study','I want to study','I am studying','I studied'],a:0,why:'"Tener que" + infinitive expresses obligation — to have to do something.',tech:'Learn the three obligation forms together: tener que, hay que, deber. They are examined most years.'},
{id:'sp9',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'"Voy a comer" means:',opts:['I am going to eat','I ate','I eat every day','I would eat'],a:0,why:'"Ir a" + infinitive is the near future — going to do something.',tech:'The near future is far more common in speech than the true future tense. Use it in the oral.'},
{id:'sp10',subj:'spanish',strand:'sp-gram',level:7,diff:2,q:'Choose the correct form: "la casa ___"',opts:['blanca','blanco','blancos','blancas'],a:0,why:'Adjectives agree with the noun. "Casa" is feminine singular, so "blanca".',tech:'Check gender AND number on every adjective. It is the commonest slip in the writing paper.'},
{id:'sp11',subj:'spanish',strand:'sp-themes',level:6,diff:1,q:'What is "treinta y cinco" in figures?',opts:['35','25','45','53'],a:0,why:'Treinta is 30 and cinco is 5, joined by "y" to give 35.',tech:'Numbers 16-29 are written as one word; 31 upwards use "y". Prices and times depend on these.'},
{id:'sp12',subj:'spanish',strand:'sp-themes',level:7,diff:2,q:'"Me gusta el fútbol" literally means:',opts:['football is pleasing to me','I like to play football','I am playing football','football is mine'],a:0,why:'Gustar works backwards from English: the thing liked is the subject. Understanding this stops the classic errors with gustar.',tech:'Singular thing → me gusta. Plural things → me gustan. Say it aloud before you write it.'},

/* -------------------------------- FRENCH -------------------------------- */
{id:'fr7',subj:'french',strand:'fr-gram',level:6,diff:1,q:'Which is the plural definite article in French?',opts:['les','le','la','un'],a:0,why:'Le and la both become "les" in the plural, whatever the gender.',tech:'French plural nouns usually add -s but it is silent. The article is what you hear.'},
{id:'fr8',subj:'french',strand:'fr-themes',level:6,diff:1,q:'"Il fait froid" means:',opts:['it is cold','he is cold','it is hot','he is making something'],a:0,why:'Weather uses "il fait" — it makes. "Il fait froid" is "it is cold".',tech:'Learn the weather block as fixed phrases: il fait beau, il fait chaud, il pleut, il neige.'},
{id:'fr9',subj:'french',strand:'fr-gram',level:7,diff:2,q:'"Je vais manger" means:',opts:['I am going to eat','I ate','I eat','I was eating'],a:0,why:'"Aller" + infinitive is the futur proche — going to do something.',tech:'The futur proche is safer than the future tense in the oral and is fully acceptable.'},
{id:'fr10',subj:'french',strand:'fr-gram',level:7,diff:2,q:'Choose the correct form: "une ___ maison"',opts:['petite','petit','petits','petites'],a:0,why:'"Maison" is feminine singular, so the adjective takes the feminine singular form "petite".',tech:'Most French adjectives follow the noun, but a short group — petit, grand, bon, beau, jeune — comes before it.'},
{id:'fr11',subj:'french',strand:'fr-themes',level:6,diff:1,q:'What is "quarante" in figures?',opts:['40','14','44','30'],a:0,why:'Quarante is 40. Quatorze is 14 — the two are easily confused.',tech:'Say the number aloud. Quatorze and quarante sound different even though they look similar.'},
{id:'fr12',subj:'french',strand:'fr-write',level:8,diff:2,q:'In the French oral examination, if you do not understand the question you should:',opts:['politely ask the examiner to repeat it in French','stay silent','answer in English','guess and change the subject'],a:0,why:'"Pouvez-vous répéter, s’il vous plaît ?" keeps you in French and loses no marks. Silence scores nothing.',tech:'Learn three repair phrases before the oral. Using them well shows control of the language.'},

/* ---------------------------- SOCIAL STUDIES ---------------------------- */
{id:'ss7',subj:'social-studies',strand:'ss-family',level:6,diff:1,q:'A household containing parents, children, grandparents and an aunt is a:',opts:['extended family','nuclear family','single-parent family','sibling household'],a:0,why:'An extended family includes relatives beyond the parents and children.',tech:'Caribbean examples matter here — extended and grandparent-headed households are common and worth naming.'},
{id:'ss8',subj:'social-studies',strand:'ss-gov',level:8,diff:2,q:'Universal adult suffrage means:',opts:['every adult citizen has the right to vote','only property owners may vote','voting is compulsory','only men may vote'],a:0,why:'It is the right of all adult citizens to vote regardless of race, sex, religion or property. Trinidad and Tobago gained it in 1946.',tech:'Know the date for your own country. Examiners reward local specificity.'},
{id:'ss9',subj:'social-studies',strand:'ss-dev',level:8,diff:2,q:'Sustainable development is best defined as development that:',opts:['meets present needs without compromising future generations','produces the fastest possible economic growth','uses only renewable resources','avoids all industry'],a:0,why:'The standard definition balances present needs against the ability of future generations to meet theirs.',tech:'Quote the definition, then give a Caribbean example — reef protection, reforestation, solar.'},
{id:'ss10',subj:'social-studies',strand:'ss-issues',level:7,diff:2,q:'Which is a PUSH factor causing migration from a country?',opts:['high unemployment at home','better schools abroad','family already living abroad','a higher wage abroad'],a:0,why:'Push factors drive people away from the source; pull factors attract them to the destination. Unemployment at home pushes.',tech:'Sort every factor into push or pull before writing. Questions usually ask for one or the other, not both.'},
{id:'ss11',subj:'social-studies',strand:'ss-issues',level:8,diff:2,q:'Which is a consumer RIGHT rather than a responsibility?',opts:['the right to be informed about a product','checking the expiry date','reading the warranty','complaining through the proper channel'],a:0,why:'Rights are what the consumer is owed; responsibilities are what the consumer must do. Being informed is a right.',tech:'Learn the rights and responsibilities as two matched lists. Questions test whether you can separate them.'},
{id:'ss12',subj:'social-studies',strand:'ss-gov',level:8,diff:2,q:'A pressure group differs from a political party because it:',opts:['seeks to influence policy without seeking to govern','contests general elections','forms the government','appoints judges'],a:0,why:'Pressure groups lobby for a cause; parties contest elections in order to govern.',tech:'Name a real Caribbean pressure group — a trade union or an environmental body — to lift the answer.'},

/* ------------------------------ VISUAL ARTS ------------------------------ */
{id:'va5',subj:'visual-arts',strand:'va-elements',level:6,diff:1,q:'Which set are the secondary colours?',opts:['orange, green, purple','red, yellow, blue','black, white, grey','brown, pink, cream'],a:0,why:'Secondary colours are made by mixing two primaries: red+yellow=orange, blue+yellow=green, red+blue=purple.',tech:'Be ready to state which two primaries make each secondary — that is the usual follow-up.'},
{id:'va6',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Adding white to a colour produces a:',opts:['tint','shade','tone','hue'],a:0,why:'White makes a tint, black makes a shade, grey makes a tone. Hue is the colour itself.',tech:'Four words, four meanings. Use them correctly in a critique and the vocabulary marks follow.'},
{id:'va7',subj:'visual-arts',strand:'va-elements',level:7,diff:2,q:'Reds, oranges and yellows are described as:',opts:['warm colours','cool colours','neutral colours','complementary colours'],a:0,why:'Warm colours suggest heat and advance towards the viewer; blues and greens are cool and recede.',tech:'Warm advances, cool recedes. That single fact explains most questions about depth in a painting.'},
{id:'va8',subj:'visual-arts',strand:'va-draw',level:7,diff:2,q:'In figure drawing, the adult human body is conventionally about how many heads tall?',opts:['seven to eight','four','twelve','five'],a:0,why:'The standard canon is roughly seven and a half to eight head-lengths for an adult.',tech:'Measure with your pencil held at arm’s length. Proportion errors are the first thing an examiner notices.'},
{id:'va9',subj:'visual-arts',strand:'va-elements',level:8,diff:2,q:'Texture that you can see but not feel is called:',opts:['implied texture','actual texture','relief texture','impasto'],a:0,why:'Implied (visual) texture is created with mark-making on a smooth surface; actual texture can be felt.',tech:'In a critique, say which kind of texture and how it was made — hatching, stippling, dry brush.'},
{id:'va10',subj:'visual-arts',strand:'va-print',level:8,diff:2,q:'In relief printing, the ink sits on:',opts:['the raised surface that was not cut away','the lines cut into the block','the whole block evenly','the paper before printing'],a:0,why:'In relief printing — lino and woodcut — you cut away what should stay white, and the raised surface takes the ink.',tech:'Remember the print is a mirror image. Any lettering must be cut in reverse.'},
{id:'va11',subj:'visual-arts',strand:'va-elements',level:8,diff:2,q:'The focal point of a composition is:',opts:['the area the eye is drawn to first','the exact centre of the page','the darkest area','the largest shape'],a:0,why:'The focal point is where the artist directs attention, through contrast, placement, colour or line. It need not be central or largest.',tech:'When asked how an artist creates a focal point, name the device — contrast, converging lines, isolation.'},
{id:'va12',subj:'visual-arts',strand:'va-history',level:9,diff:2,q:'Caribbean art of the twentieth century is most often discussed in terms of:',opts:['identity, heritage and the post-colonial experience','classical Greek proportion','Renaissance perspective','Dutch still life'],a:0,why:'Caribbean artists have consistently worked with questions of identity, African and Indian heritage, landscape and independence.',tech:'Know two named Caribbean artists and one work each. A general answer about "culture" scores in the lowest band.'},

/* --------------------- PHYSICAL EDUCATION & SPORT --------------------- */
{id:'pe6',subj:'physical-education',strand:'pe-anatomy',level:8,diff:2,q:'Muscles that work in antagonistic pairs mean that:',opts:['as one contracts the other relaxes','both contract together','both relax together','one replaces the other'],a:0,why:'Muscles pull but cannot push, so they work in pairs — the biceps and triceps at the elbow are the standard example.',tech:'Always name the pair AND the joint. "Biceps and triceps at the elbow" earns more than "arm muscles".'},
{id:'pe7',subj:'physical-education',strand:'pe-fitness',level:7,diff:2,q:'The main purpose of a warm-up is to:',opts:['raise body temperature and blood flow to reduce injury risk','tire the muscles before play','lose weight','practise the rules'],a:0,why:'A warm-up gradually raises heart rate, muscle temperature and joint mobility, which lowers the risk of strains.',tech:'Describe the three stages: pulse-raiser, mobility, sport-specific. A one-line answer loses marks.'},
{id:'pe8',subj:'physical-education',strand:'pe-anatomy',level:8,diff:2,q:'Anaerobic activity is BEST described as:',opts:['short, high-intensity effort without enough oxygen','long, steady effort using oxygen','any activity done indoors','stretching and flexibility work'],a:0,why:'Anaerobic means without oxygen — short, maximal efforts such as a 100 m sprint, producing lactic acid.',tech:'Match the energy system to the event: 100 m anaerobic, marathon aerobic, 800 m a mixture.'},
{id:'pe9',subj:'physical-education',strand:'pe-fitness',level:8,diff:2,q:'Which test measures cardiovascular endurance?',opts:['the multi-stage fitness (bleep) test','the sit-and-reach test','the standing broad jump','the grip dynamometer'],a:0,why:'The bleep test measures aerobic capacity. Sit-and-reach measures flexibility, broad jump power, dynamometer strength.',tech:'Learn one test per fitness component. Questions pair a component with its test almost every year.'},
{id:'pe10',subj:'physical-education',strand:'pe-nutri',level:7,diff:2,q:'During prolonged exercise in Caribbean heat, the greatest immediate risk is:',opts:['dehydration','vitamin deficiency','protein shortage','too much fibre'],a:0,why:'Heavy sweating in high heat and humidity causes fluid and electrolyte loss, which impairs performance and can be dangerous.',tech:'Mention the climate. A Caribbean candidate writing about heat and humidity is answering the real question.'},
{id:'pe11',subj:'physical-education',strand:'pe-injury',level:8,diff:2,q:'Which is a preventative measure rather than a treatment?',opts:['wearing correct protective equipment','applying ice to a sprain','strapping an injured ankle','resting a torn muscle'],a:0,why:'Prevention happens before injury; the other three are responses after it.',tech:'Sort your revision into prevention, immediate treatment and rehabilitation. Questions name one of the three.'},
{id:'pe12',subj:'physical-education',strand:'pe-sport',level:9,diff:2,q:'The use of banned performance-enhancing drugs in sport is primarily an issue of:',opts:['fairness and athlete health','entertainment value','team selection','ticket pricing'],a:0,why:'Doping undermines fair competition and carries serious long-term health risks, which is why it is banned and tested for.',tech:'Give both sides of the argument, then a judgement. "Discuss" questions expect a position at the end.'},

/* ---------------------- INFORMATION TECHNOLOGY ---------------------- */
{id:'it8',subj:'information-technology',strand:'it-hardware',level:6,diff:1,q:'Which is an OUTPUT device?',opts:['plotter','keyboard','mouse','microphone'],a:0,why:'A plotter produces printed drawings — data leaving the computer. The other three send data in.',tech:'Some devices are both, such as a touchscreen. If a question offers one, read the wording carefully.'},
{id:'it9',subj:'information-technology',strand:'it-hardware',level:7,diff:2,q:'The main purpose of an operating system is to:',opts:['manage the hardware and provide a platform for applications','create documents','protect against viruses','connect to the internet'],a:0,why:'The OS manages memory, files, processes and devices, and gives applications a consistent interface to them.',tech:'Name specific functions — memory management, file management, device control. A vague answer scores low.'},
{id:'it10',subj:'information-technology',strand:'it-impact',level:8,diff:2,q:'An e-mail pretending to be from your bank and asking you to confirm your password is:',opts:['phishing','spam','a firewall','encryption'],a:0,why:'Phishing impersonates a trusted organisation to trick you into giving up credentials or card details.',tech:'Be able to state one countermeasure for each threat. Naming the threat alone is half the mark.'},
{id:'it11',subj:'information-technology',strand:'it-database',level:9,diff:2,q:'In a database table, the primary key is the field that:',opts:['uniquely identifies each record','holds the most data','comes first alphabetically','links to the internet'],a:0,why:'A primary key is unique for every record, which is what allows records to be found and related reliably.',tech:'A good primary key never repeats and never changes — an ID number, not a surname.'},
{id:'it12',subj:'information-technology',strand:'it-data',level:8,diff:2,q:'Roughly how many bytes are in one kilobyte?',opts:['1024','100','10','1000000'],a:0,why:'One kilobyte is 2¹⁰ = 1024 bytes, because storage is measured in powers of two.',tech:'Learn the ladder: bit, byte, KB, MB, GB, TB, each 1024 times the last. File-size questions depend on it.'},

/* ------------------------------ GEOGRAPHY ------------------------------ */
{id:'ge9',subj:'geography',strand:'ge-maps',level:7,diff:2,q:'Lines of latitude run:',opts:['east to west, measuring distance north or south of the Equator','north to south, measuring distance east or west','only through the poles','along the Greenwich Meridian'],a:0,why:'Latitude lines are parallel to the Equator and measure how far north or south a place lies. Longitude lines run pole to pole.',tech:'LatitudE is flat like a ladder rung. Trinidad sits at about 10°N, which explains its climate.'},
{id:'ge10',subj:'geography',strand:'ge-tectonic',level:8,diff:2,q:'A waterfall, a gorge and rapids are features of a river’s:',opts:['upper course','lower course','delta','estuary'],a:0,why:'The upper course is steep and fast, eroding vertically to give waterfalls, gorges and V-shaped valleys. Meanders and deltas belong to the lower course.',tech:'Learn the three courses with two features each. Questions almost always name a course.'},
{id:'ge11',subj:'geography',strand:'ge-maps',level:7,diff:2,q:'On a 1:50 000 map, 2 cm represents:',opts:['1 km','500 m','2 km','5 km'],a:0,why:'1 cm represents 50 000 cm, which is 500 m. So 2 cm represents 1 000 m, or 1 km.',tech:'Convert the scale to metres once at the start and write it in the margin. Then every distance is arithmetic.'},
{id:'ge12',subj:'geography',strand:'ge-econ',level:8,diff:2,q:'Which is a DISADVANTAGE of tourism for a Caribbean island?',opts:['pressure on water and waste systems in peak season','creation of employment','earning of foreign exchange','improvement of airports and roads'],a:0,why:'Visitor numbers can exceed what local water supply, sewage and waste disposal were built for. The other three are benefits.',tech:'Prepare three advantages and three disadvantages with a named island. Balance earns the higher band.'},

/* --------------------------- ENGLISH A & B --------------------------- */
{id:'ea11',subj:'english-a',strand:'ea-comp',level:7,diff:2,q:'A topic sentence in a paragraph:',opts:['states the main idea the paragraph will develop','gives an example','concludes the argument','asks a question'],a:0,why:'The topic sentence announces the paragraph’s single main idea, which the rest of the paragraph supports.',tech:'One idea per paragraph. If you find two, split it — examiners reward clear structure.'},
{id:'ea12',subj:'english-a',strand:'ea-vocab',level:8,diff:2,q:'Which sentence is written in the most FORMAL register?',opts:['I am writing to request permission to leave early.','Just letting you know I gotta go early.','Can I bounce early today?','Heads up — leaving early.'],a:0,why:'Formal register avoids contractions and slang and uses complete, courteous constructions.',tech:'Match register to audience. A formal letter with slang in it loses marks no matter how clear the point is.'},
{id:'eb11',subj:'english-b',strand:'eb-prose',level:7,diff:2,q:'The ATMOSPHERE of a setting refers to:',opts:['the feeling the place creates','the time of day','the geographical location','the number of characters present'],a:0,why:'Setting is where and when; atmosphere is the emotional quality the writer builds through detail and word choice.',tech:'Quote the specific words that build the atmosphere. Naming it without evidence earns little.'},
{id:'eb12',subj:'english-b',strand:'eb-poetry',level:8,diff:2,q:'Enjambment in poetry is when:',opts:['a sentence runs past the end of a line without a pause','every line rhymes','a line is repeated','the poem has no punctuation at all'],a:0,why:'Enjambment carries the sense over the line break, which can create momentum, urgency or surprise at the next line.',tech:'Say what the enjambment DOES. "Creates flow" is weak; "hurries the reader into the next image" is not.'},

/* --------------------------- SCIENCES & HISTORY --------------------------- */
{id:'ph11',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'A ball is held above the ground and released. The main energy change is:',opts:['gravitational potential to kinetic','kinetic to chemical','heat to potential','sound to kinetic'],a:0,why:'The stored gravitational potential energy converts to kinetic energy as the ball speeds up while falling.',tech:'Write energy changes as "X energy → Y energy". Examiners look for that exact form.'},
{id:'ph12',subj:'physics',strand:'ph-mech',level:8,diff:2,q:'A force of 200 N acts over an area of 0.5 m². What is the pressure?',opts:['400 Pa','100 Pa','0.0025 Pa','200 Pa'],a:0,why:'Pressure = force ÷ area = 200 ÷ 0.5 = 400 Pa.',tech:'Dividing by a number less than one makes the answer LARGER. If yours got smaller, check the division.'},
{id:'ch11',subj:'chemistry',strand:'ch-matter',level:6,diff:1,q:'In a salt solution, the salt is the:',opts:['solute','solvent','solution','suspension'],a:0,why:'The solute dissolves, the solvent does the dissolving, and together they form the solution.',tech:'Three words, one sentence: solute + solvent = solution. It removes most of the confusion in this topic.'},
{id:'ch12',subj:'chemistry',strand:'ch-mole',level:9,diff:2,q:'Which change would INCREASE the rate of a reaction?',opts:['raising the temperature','using larger lumps of solid','lowering the concentration','removing the catalyst'],a:0,why:'Higher temperature means faster particles and more frequent successful collisions. The other three all slow it down.',tech:'Explain rate through collision theory — more frequent collisions with enough energy. That phrase carries the mark.'},
{id:'bi11',subj:'biology',strand:'bi-nutri',level:7,diff:2,q:'A diet lacking vitamin C leads to:',opts:['scurvy','rickets','anaemia','goitre'],a:0,why:'Vitamin C deficiency causes scurvy. Rickets is vitamin D, anaemia is iron, goitre is iodine.',tech:'Learn deficiency diseases as nutrient-disease pairs. They appear in Paper 01 most years.'},
{id:'bi12',subj:'biology',strand:'bi-repro',level:8,diff:2,q:'Pollination is BEST defined as the transfer of pollen from:',opts:['anther to stigma','stigma to ovule','ovary to anther','petal to sepal'],a:0,why:'Pollination is anther to stigma. Fertilisation happens afterwards, when the male nucleus reaches the ovule.',tech:'Pollination and fertilisation are two different events. Confusing them is the commonest error in this topic.'},
{id:'hi11',subj:'history',strand:'hi-indigenous',level:7,diff:2,q:'The encomienda system in the Spanish Caribbean was:',opts:['a grant of indigenous labour to a Spanish settler','a form of paid employment','a trading agreement between islands','a religious order'],a:0,why:'It granted a settler the labour and tribute of a group of indigenous people, nominally in exchange for protection and instruction. In practice it was forced labour and contributed to catastrophic population decline.',tech:'Link the encomienda to the collapse of the indigenous population and then to the turn to African labour.'},
{id:'hi12',subj:'history',strand:'hi-indep',level:9,diff:3,q:'The West Indies Federation collapsed in 1962 chiefly because:',opts:['Jamaica withdrew after a referendum','Britain dissolved it without warning','the islands ran out of money immediately','no island wanted independence'],a:0,why:'Jamaica’s 1961 referendum voted to leave; Trinidad and Tobago then withdrew, and the Federation was dissolved in 1962.',tech:'Know the deeper causes too — island insularity, freedom of movement, unequal contributions, weak central powers.'}
);

/* ========================= PRIMARY — Standards 1 to 5 =========================
 * Written for the SEA papers: Mathematics (Number, Measurement, Geometry,
 * Statistics), English Language Arts (spelling, punctuation, grammar, reading
 * comprehension) and ELA Writing. Language is pitched at the age, and the
 * reasoning is written to be read by a child, not about one.
 */
window.CSEC_QUESTIONS.push(

/* ---------------------------- MATHEMATICS ---------------------------- */
{id:'pm1',subj:'p-mathematics',strand:'pm-place',level:1,diff:1,q:'What is the value of the 7 in the number 472?',opts:['70','7','700','7000'],a:0,why:'Counting from the right, 2 is ones, 7 is tens and 4 is hundreds. Seven tens is 70.',tech:'Write the headings H T O above the digits before you answer. It takes five seconds and stops the guessing.'},
{id:'pm2',subj:'p-mathematics',strand:'pm-place',level:3,diff:2,q:'Round 3 847 to the nearest hundred.',opts:['3 800','3 900','3 850','4 000'],a:0,why:'Look at the tens digit, which is 4. Four is less than five, so the hundreds digit stays the same and 3 847 becomes 3 800.',tech:'Underline the digit you are rounding to, then look at the ONE digit to its right. Five or more rounds up.'},
{id:'pm3',subj:'p-mathematics',strand:'pm-place',level:4,diff:2,q:'Which number is the largest?',opts:['9 087','9 078','8 987','9 008'],a:0,why:'All start with 9 except 8 987. Compare the hundreds next: 9 087 has 0 hundreds and 8 tens, 9 078 has 0 hundreds and 7 tens. So 9 087 is largest.',tech:'Line the numbers up one under the other and compare from the left. The first column where they differ decides it.'},
{id:'pm4',subj:'p-mathematics',strand:'pm-ops',level:2,diff:1,q:'What is 6 × 7?',opts:['42','48','36','56'],a:0,why:'Six sevens are 42. If you know 6 × 7 you also know 7 × 6 — they give the same answer.',tech:'Learn tables both ways round. It halves what you have to remember.'},
{id:'pm5',subj:'p-mathematics',strand:'pm-ops',level:3,diff:2,q:'A box holds 24 mangoes. How many mangoes are in 15 boxes?',opts:['360','340','240','380'],a:0,why:'24 × 15. Do 24 × 10 = 240 and 24 × 5 = 120, then add: 240 + 120 = 360.',tech:'Split the harder number into tens and ones, multiply each, then add. Much safer than long multiplication under pressure.'},
{id:'pm6',subj:'p-mathematics',strand:'pm-ops',level:4,diff:2,q:'Share 486 sweets equally among 6 children. How many does each child get?',opts:['81','80','76','86'],a:0,why:'486 ÷ 6. Six goes into 48 eight times, and into 6 once, giving 81.',tech:'Check a division by multiplying back: 81 × 6 = 486. If it does not match, you have made a slip.'},
{id:'pm7',subj:'p-mathematics',strand:'pm-fractions',level:2,diff:1,q:'Which fraction is the same as one half?',opts:['2/4','1/3','2/3','3/4'],a:0,why:'Two quarters make one half — cut a roti into four and take two pieces.',tech:'Draw the shape and shade it if you are unsure. A picture settles most fraction questions.'},
{id:'pm8',subj:'p-mathematics',strand:'pm-fractions',level:4,diff:2,q:'What is 1/4 of 60?',opts:['15','20','24','30'],a:0,why:'A quarter means share into 4 equal parts: 60 ÷ 4 = 15.',tech:'"Of" means multiply, and a unit fraction means divide by the bottom number. 1/4 of something is that thing ÷ 4.'},
{id:'pm9',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:3,q:'What is 3/5 + 1/5?',opts:['4/5','4/10','3/10','2/5'],a:0,why:'The bottom numbers are already the same, so add only the tops: 3 + 1 = 4, giving 4/5. The bottom stays 5.',tech:'Never add the bottom numbers. If the bottoms are different, make them the same FIRST.'},
{id:'pm10',subj:'p-mathematics',strand:'pm-decimals',level:4,diff:2,q:'What is 0.6 written as a fraction in its simplest form?',opts:['3/5','6/10','1/6','60/10'],a:0,why:'0.6 is six tenths, 6/10. Both 6 and 10 divide by 2, giving 3/5.',tech:'One decimal place means tenths, two places means hundredths. Then simplify.'},
{id:'pm11',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'Find 25% of TT$80.',opts:['TT$20','TT$25','TT$16','TT$40'],a:0,why:'25% is the same as one quarter, so 80 ÷ 4 = TT$20.',tech:'Learn the easy ones: 50% is half, 25% is a quarter, 10% is divide by 10. Most SEA percent questions are one of those.'},
{id:'pm12',subj:'p-mathematics',strand:'pm-money',level:2,diff:1,q:'A drink costs TT$4.50. You pay with a TT$10 note. How much change?',opts:['TT$5.50','TT$6.50','TT$4.50','TT$5.00'],a:0,why:'10.00 − 4.50 = 5.50.',tech:'Count up from the price to the note: 4.50 to 5.00 is 50 cents, 5.00 to 10.00 is 5 dollars. That is TT$5.50.'},
{id:'pm13',subj:'p-mathematics',strand:'pm-money',level:4,diff:2,q:'Three books cost TT$27.60 altogether. What does one book cost?',opts:['TT$9.20','TT$9.02','TT$8.20','TT$9.60'],a:0,why:'27.60 ÷ 3 = 9.20.',tech:'Keep the decimal points lined up when you divide money, and always write two figures after the point.'},
{id:'pm14',subj:'p-mathematics',strand:'pm-time',level:3,diff:2,q:'A film starts at 2:45 p.m. and lasts 1 hour 30 minutes. When does it finish?',opts:['4:15 p.m.','4:45 p.m.','3:15 p.m.','4:05 p.m.'],a:0,why:'2:45 plus 1 hour is 3:45. Plus 30 more minutes is 4:15 p.m.',tech:'Add the hours first, then the minutes. If the minutes go past 60, carry an hour.'},
{id:'pm15',subj:'p-mathematics',strand:'pm-time',level:4,diff:2,q:'Write 7:20 p.m. using the 24-hour clock.',opts:['19:20','07:20','17:20','20:07'],a:0,why:'After midday add 12 to the hour: 7 + 12 = 19, so 19:20.',tech:'a.m. hours stay the same. p.m. hours get 12 added — except 12 p.m., which stays 12.'},
{id:'pm16',subj:'p-mathematics',strand:'pm-measure',level:3,diff:2,q:'How many centimetres are in 2.5 metres?',opts:['250 cm','25 cm','2 500 cm','205 cm'],a:0,why:'One metre is 100 cm, so 2.5 × 100 = 250 cm.',tech:'Changing to a SMALLER unit makes the number BIGGER. If your answer got smaller, you divided when you should have multiplied.'},
{id:'pm17',subj:'p-mathematics',strand:'pm-measure',level:4,diff:2,q:'A bottle holds 1.5 litres. How many millilitres is that?',opts:['1 500 ml','150 ml','15 000 ml','1 050 ml'],a:0,why:'One litre is 1 000 ml, so 1.5 × 1 000 = 1 500 ml.',tech:'Learn the three ladders: km-m-cm-mm, kg-g, l-ml. Each step is ×1000 or ×100.'},
{id:'pm18',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'A rectangle is 8 cm long and 5 cm wide. What is its area?',opts:['40 cm²','26 cm²','13 cm²','80 cm²'],a:0,why:'Area of a rectangle is length × width: 8 × 5 = 40 cm².',tech:'Area is measured in square units (cm²). Perimeter is the distance all the way round and uses plain cm.'},
{id:'pm19',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'A square has sides of 7 cm. What is its perimeter?',opts:['28 cm','49 cm','14 cm','21 cm'],a:0,why:'Perimeter is all four sides added: 7 + 7 + 7 + 7 = 28 cm, or 4 × 7.',tech:'Read carefully whether the question wants perimeter or area. Mixing them up is the commonest mistake in this topic.'},
{id:'pm20',subj:'p-mathematics',strand:'pm-area',level:5,diff:3,q:'A box is 4 cm by 3 cm by 2 cm. What is its volume?',opts:['24 cm³','9 cm³','12 cm³','48 cm³'],a:0,why:'Volume of a cuboid is length × width × height: 4 × 3 × 2 = 24 cm³.',tech:'Volume uses cubic units (cm³) because you multiplied three measurements together.'},
{id:'pm21',subj:'p-mathematics',strand:'pm-shapes',level:2,diff:1,q:'How many faces does a cube have?',opts:['6','8','12','4'],a:0,why:'A cube has six square faces — think of a dice.',tech:'Faces are the flat surfaces, edges are the lines where they meet, vertices are the corners. A cube has 6, 12 and 8.'},
{id:'pm22',subj:'p-mathematics',strand:'pm-shapes',level:3,diff:2,q:'A shape has 3 sides and 3 angles. What is it?',opts:['a triangle','a square','a pentagon','a rectangle'],a:0,why:'Three sides and three angles make a triangle.',tech:'Count the sides to name the shape: 3 triangle, 4 quadrilateral, 5 pentagon, 6 hexagon, 8 octagon.'},
{id:'pm23',subj:'p-mathematics',strand:'pm-angles',level:4,diff:2,q:'An angle that is exactly 90° is called:',opts:['a right angle','an acute angle','an obtuse angle','a straight angle'],a:0,why:'A 90° angle is a right angle — the corner of a book or a door.',tech:'Less than 90° is acute, more than 90° but less than 180° is obtuse, exactly 180° is a straight angle.'},
{id:'pm24',subj:'p-mathematics',strand:'pm-graphs',level:3,diff:2,q:'On a pictograph, one symbol stands for 5 books. A row shows 4 symbols. How many books is that?',opts:['20','9','4','15'],a:0,why:'Each symbol is 5 books, so 4 × 5 = 20.',tech:'ALWAYS read the key first. The commonest pictograph mistake is counting symbols instead of using the key.'},
{id:'pm25',subj:'p-mathematics',strand:'pm-average',level:5,diff:2,q:'Find the mean of 4, 8, 6 and 10.',opts:['7','6','8','28'],a:0,why:'Add them: 4 + 8 + 6 + 10 = 28. There are 4 numbers, so 28 ÷ 4 = 7.',tech:'Mean is add-then-divide. Mode is the one that appears most. Median is the middle one after ordering.'},

/* ------------------------ ENGLISH LANGUAGE ARTS ------------------------ */
{id:'pel1',subj:'p-ela',strand:'pe-spell',level:2,diff:1,q:'Which word is spelled correctly?',opts:['because','becuase','becouse','becasue'],a:0,why:'It is b-e-c-a-u-s-e. The "au" in the middle is what most people get wrong.',tech:'Say the tricky part out loud in syllables: be-cause. Then write it three times.'},
{id:'pel2',subj:'p-ela',strand:'pe-spell',level:4,diff:2,q:'Which word is spelled correctly?',opts:['separate','seperate','seperete','separete'],a:0,why:'It is s-e-p-a-r-a-t-e. There is "a rat" in the middle of separate.',tech:'Find a small word hiding inside a hard word. It gives you something to hold on to.'},
{id:'pel3',subj:'p-ela',strand:'pe-punct',level:2,diff:1,q:'Which sentence is punctuated correctly?',opts:['My friend Anisa lives in Arima.','my friend anisa lives in arima.','My friend anisa lives in Arima','My Friend Anisa lives in arima.'],a:0,why:'A sentence starts with a capital, names of people and places take capitals, and it ends with a full stop.',tech:'Check three things every time: capital at the start, capitals on names, full stop at the end.'},
{id:'pel4',subj:'p-ela',strand:'pe-punct',level:4,diff:2,q:'Which sentence uses speech marks correctly?',opts:['"Where are you going?" asked Mummy.','"Where are you going? asked Mummy."','Where are you going? "asked Mummy".','"where are you going?" asked Mummy.'],a:0,why:'The speech marks go around the spoken words only, the question mark sits inside them, and the spoken words begin with a capital.',tech:'Speech marks wrap only what came out of the mouth. The "asked Mummy" part stays outside.'},
{id:'pel5',subj:'p-ela',strand:'pe-punct',level:5,diff:2,q:'Which sentence uses the apostrophe correctly?',opts:['The girl’s bag is on the desk.','The girls bag is on the desk.','The girl’s bags is on the desk.','The girls’ bag belongs to her.'],a:0,why:'One girl owns the bag, so the apostrophe goes before the s: girl’s.',tech:'Ask how many owners. One owner → apostrophe then s. More than one → s then apostrophe.'},
{id:'pel6',subj:'p-ela',strand:'pe-grammar',level:2,diff:1,q:'Choose the correct word: "She ___ to school every day."',opts:['walks','walk','walking','walked every tomorrow'],a:0,why:'"She" is one person, so the verb takes an s: she walks. "Every day" tells us it happens regularly.',tech:'He, she and it take a verb with s. I, you, we and they do not.'},
{id:'pel7',subj:'p-ela',strand:'pe-grammar',level:3,diff:2,q:'Which word is a verb in this sentence: "The bright parrot flew over the river."',opts:['flew','bright','parrot','river'],a:0,why:'"Flew" is the doing word — it tells you what the parrot did. Parrot and river are nouns, bright is an adjective.',tech:'Ask "what is happening?" The answer is the verb.'},
{id:'pel8',subj:'p-ela',strand:'pe-grammar',level:4,diff:2,q:'Choose the correct word: "There ___ five boys in the yard."',opts:['were','was','is','be'],a:0,why:'"Five boys" is more than one, so the verb must be plural: were.',tech:'Find what the verb is really about. Here it is "boys", not "there".'},
{id:'pel9',subj:'p-ela',strand:'pe-grammar',level:5,diff:2,q:'Which sentence is in the past tense?',opts:['She bought a pattie at the shop.','She buys a pattie at the shop.','She is buying a pattie.','She will buy a pattie.'],a:0,why:'"Bought" is the past tense of buy — it has already happened.',tech:'Past already happened, present is happening now, future has not happened yet. Check the verb, not the rest.'},
{id:'pel10',subj:'p-ela',strand:'pe-vocab',level:4,diff:2,q:'"The path was narrow." The word "narrow" means:',opts:['not wide','very long','very steep','very dark'],a:0,why:'Narrow is the opposite of wide — there is not much room from side to side.',tech:'If you do not know a word, read the whole sentence again and ask what would make sense there.'},
{id:'pel11',subj:'p-ela',strand:'pe-vocab',level:5,diff:2,q:'"The old man was weary after the long walk." The word "weary" most nearly means:',opts:['very tired','very angry','very hungry','very happy'],a:0,why:'Weary means tired out. The clue is "after the long walk".',tech:'The words around the unknown word are the clue. SEA always leaves one.'},
{id:'pel12',subj:'p-ela',strand:'pe-fiction',level:3,diff:2,q:'In a story, the character who the story is mainly about is called the:',opts:['main character','narrator','author','setting'],a:0,why:'The main character is the person the story follows. The author is the person who wrote it, and the setting is where and when it happens.',tech:'Before answering comprehension questions, note who the story is about and where it happens.'},
{id:'pel13',subj:'p-ela',strand:'pe-fiction',level:4,diff:2,q:'A question asks "How did Maya FEEL when she saw the letter?" but the passage never uses a feeling word. You should:',opts:['work it out from what she said and did','write that the passage does not say','copy the whole sentence about the letter','guess any feeling'],a:0,why:'The writer shows feelings through actions — shaking hands, a quiet voice, running away. You use that evidence to work out the feeling.',tech:'Point to the words in the passage that made you think it. That is what earns the mark.'},
{id:'pel14',subj:'p-ela',strand:'pe-nonfict',level:4,diff:2,q:'In a report about turtles, the best place to find out what turtles eat is:',opts:['the paragraph with a heading about food','the first sentence','the picture caption','the title'],a:0,why:'Headings tell you what each part is about, so you can go straight to the right paragraph instead of reading everything again.',tech:'Read the questions first, then scan the headings. It saves minutes you will need later.'},
{id:'pel15',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"The sun smiled down on Maracas Bay." The sun is being described as if it were:',opts:['a person','an animal','a machine','a building'],a:0,why:'Smiling is something people do, so the poet is describing the sun as if it were a person. That is personification.',tech:'When something that is not alive does a human thing, say so and then say what feeling it gives — here, warmth and happiness.'},
{id:'pel16',subj:'p-ela',strand:'pe-graphic',level:5,diff:2,q:'A bus timetable shows buses at 6:00, 6:30, 7:00 and 7:30. How often does a bus come?',opts:['every 30 minutes','every hour','every 15 minutes','twice a day'],a:0,why:'From 6:00 to 6:30 is 30 minutes, and so is each step after it.',tech:'With a timetable or chart, find the pattern between two entries first, then answer.'},

/* ---------------------------- ELA WRITING ---------------------------- */
{id:'pw1',subj:'p-ela-writing',strand:'pw-narrative',level:3,diff:1,q:'Every good story needs:',opts:['a beginning, a middle and an ending','as many characters as possible','lots of long words','a lot of speech'],a:0,why:'A story that just stops has no ending, and markers notice. Plan all three parts before you start writing.',tech:'Spend two minutes planning three boxes: how it starts, what goes wrong, how it ends. Then write.'},
{id:'pw2',subj:'p-ela-writing',strand:'pw-narrative',level:4,diff:2,q:'Which opening is the most interesting?',opts:['The gate creaked, and I knew somebody had been there.','One day I woke up and got out of bed.','This is a story about my holiday.','I am going to tell you what happened.'],a:0,why:'Starting inside the action makes the reader want to know more. The others just announce that a story is coming.',tech:'Never begin with "This is a story about". Start with something happening.'},
{id:'pw3',subj:'p-ela-writing',strand:'pw-language',level:4,diff:2,q:'Which sentence uses the best describing detail?',opts:['The mango was warm and heavy in my hand.','The mango was nice.','The mango was a mango.','The mango was very very good.'],a:0,why:'"Warm and heavy in my hand" lets the reader feel it. "Nice" and "very very good" tell us nothing.',tech:'Use your senses — what you saw, heard, smelled, felt. One good detail beats three weak ones.'},
{id:'pw4',subj:'p-ela-writing',strand:'pw-language',level:5,diff:2,q:'"The rain fell like drums on the galvanise." This comparison is:',opts:['a simile','a fact','a question','a heading'],a:0,why:'It compares the rain to drums using the word "like", which makes it a simile.',tech:'A simile uses "like" or "as". Use one or two in a story — not one in every sentence.'},
{id:'pw5',subj:'p-ela-writing',strand:'pw-organise',level:4,diff:2,q:'A new paragraph should start when:',opts:['you move to a new idea, time or place','the page looks too full','you have written five lines','you use a new word'],a:0,why:'Paragraphs group ideas. A new idea, a jump in time, a change of place or a new speaker all start a new one.',tech:'If you wrote a whole page with no paragraphs, you lost organisation marks before the marker read a word.'},
{id:'pw6',subj:'p-ela-writing',strand:'pw-expository',level:5,diff:2,q:'An expository piece is different from a story because it:',opts:['explains something using facts','has a hero and a villain','always ends happily','must be written in the first person'],a:0,why:'Expository writing informs or explains — a report on an animal, a place or a process. It uses facts, not plot.',tech:'At SEA the writing paper gives you either three narrative items OR three expository ones. Practise both; you do not get to choose which type appears.'},
{id:'pw7',subj:'p-ela-writing',strand:'pw-mechanics',level:3,diff:2,q:'Before you hand in your writing you should ALWAYS:',opts:['read it through to check capitals and full stops','count the words','rub out the plan','make the writing bigger'],a:0,why:'Grammar and mechanics is one of the four things the markers score. Two minutes of checking usually finds three or four easy marks.',tech:'Read your work in a whisper. Your ear catches mistakes your eye slides past.'},
{id:'pw8',subj:'p-ela-writing',strand:'pw-mechanics',level:5,diff:2,q:'Your SEA writing response is marked on Content, Language Use, Organisation and:',opts:['Grammar and Mechanics','Handwriting speed','Length','Number of characters'],a:0,why:'The four criteria are Content, Language Use, Grammar and Mechanics, and Organisation. Two people mark each response.',tech:'Know what you are marked on. A long piece with no paragraphs and no full stops loses on two of the four.'},

/* ------------------------------ SCIENCE ------------------------------ */
{id:'ps1',subj:'p-science',strand:'ps-living',level:2,diff:1,q:'Which of these is a living thing?',opts:['a hibiscus plant','a stone','a spoon','a bicycle'],a:0,why:'Living things grow, need food and water, and can make more of themselves. A plant does all three.',tech:'Remember MRS GREN — movement, respiration, sensitivity, growth, reproduction, excretion, nutrition.'},
{id:'ps2',subj:'p-science',strand:'ps-living',level:3,diff:2,q:'What do green plants need to make their own food?',opts:['sunlight, water and carbon dioxide','only water','only soil','meat and water'],a:0,why:'Green plants use sunlight, water and carbon dioxide from the air to make their food. That is photosynthesis.',tech:'Plants make food; animals must find it. That one sentence answers a lot of questions.'},
{id:'ps3',subj:'p-science',strand:'ps-body',level:3,diff:2,q:'Which organ pumps blood around the body?',opts:['the heart','the lungs','the stomach','the brain'],a:0,why:'The heart pumps blood. The lungs take in air, the stomach digests food and the brain controls everything.',tech:'Match each organ to one job. Questions usually give you the job and ask for the organ.'},
{id:'ps4',subj:'p-science',strand:'ps-body',level:4,diff:2,q:'Which food group should you eat the MOST of for energy?',opts:['carbohydrates','fats','vitamins','minerals'],a:0,why:'Carbohydrates such as rice, roti, ground provision and bread are the body’s main energy source.',tech:'Learn the groups with local examples: carbohydrates — rice and dasheen; protein — fish and peas.'},
{id:'ps5',subj:'p-science',strand:'ps-matter',level:3,diff:1,q:'Water turning into ice is an example of:',opts:['freezing','melting','evaporation','condensation'],a:0,why:'Liquid becoming solid is freezing. Solid to liquid is melting.',tech:'Draw the three states in a triangle and label the arrows between them. It fixes all four words at once.'},
{id:'ps6',subj:'p-science',strand:'ps-matter',level:4,diff:2,q:'Which is a property of a gas?',opts:['it spreads out to fill its container','it has a fixed shape','it cannot be squashed','it always sinks'],a:0,why:'Gases have no fixed shape or volume and spread to fill whatever holds them. Solids keep their shape; liquids take the shape of the container but keep their volume.',tech:'Three states, three behaviours. Learn shape and volume for each.'},
{id:'ps7',subj:'p-science',strand:'ps-energy',level:4,diff:2,q:'Which material will let electricity pass through it?',opts:['copper wire','a rubber band','a plastic ruler','dry wood'],a:0,why:'Metals such as copper are conductors. Rubber, plastic and dry wood are insulators, which is why wires are covered in plastic.',tech:'Metals conduct; most non-metals do not. That is why plugs are plastic outside and metal inside.'},
{id:'ps8',subj:'p-science',strand:'ps-energy',level:5,diff:2,q:'A magnet will attract:',opts:['an iron nail','a copper coin','a glass marble','a plastic button'],a:0,why:'Magnets attract iron, steel, nickel and cobalt. Copper, glass and plastic are not magnetic.',tech:'Not all metals are magnetic. Copper and aluminium are metals but a magnet ignores them.'},
{id:'ps9',subj:'p-science',strand:'ps-earth',level:4,diff:2,q:'In the water cycle, water turning from liquid into vapour is called:',opts:['evaporation','condensation','precipitation','collection'],a:0,why:'The sun heats water and it evaporates into the air. When it cools it condenses into clouds, then falls as precipitation.',tech:'Learn the cycle as a loop with four labels and draw it. The arrows matter as much as the words.'},
{id:'ps10',subj:'p-science',strand:'ps-earth',level:5,diff:2,q:'Which planet is closest to the Sun?',opts:['Mercury','Venus','Earth','Mars'],a:0,why:'Mercury is first, then Venus, then Earth, then Mars.',tech:'Make a sentence where the first letters match the planets in order. Any silly sentence you invent yourself will stick.'},

/* -------------------------- SOCIAL STUDIES -------------------------- */
{id:'pss1',subj:'p-social-studies',strand:'pss-self',level:1,diff:1,q:'Which of these is a RESPONSIBILITY you have at school?',opts:['keeping your classroom clean','being given a desk','having a teacher','getting a lunch break'],a:0,why:'A responsibility is something you must do. The other three are things you receive, which makes them rights.',tech:'Rights are what you get. Responsibilities are what you must do. Questions test whether you can tell them apart.'},
{id:'pss2',subj:'p-social-studies',strand:'pss-comm',level:3,diff:1,q:'Who is the head of the government of Trinidad and Tobago?',opts:['the Prime Minister','the Mayor','the Principal','the Police Commissioner'],a:0,why:'The Prime Minister heads the government. The President is the Head of State, which is a different role.',tech:'Prime Minister runs the government; President is Head of State. Both appear in questions.'},
{id:'pss3',subj:'p-social-studies',strand:'pss-comm',level:3,diff:2,q:'Which is a national emblem of Trinidad and Tobago?',opts:['the Scarlet Ibis','the flamingo','the parrot','the pelican'],a:0,why:'The Scarlet Ibis is the national bird of Trinidad and the Cocrico is the national bird of Tobago.',tech:'Learn the national emblems as a set: flag, coat of arms, anthem, watchwords, flower, birds.'},
{id:'pss4',subj:'p-social-studies',strand:'pss-comm',level:4,diff:2,q:'Which service is provided by the government for everyone?',opts:['public health care','a private doctor’s office','a supermarket','a private taxi'],a:0,why:'Public services such as health centres, schools, water and roads are provided by the government from taxes.',tech:'Ask who pays. If everybody pays through taxes and everybody may use it, it is a public service.'},
{id:'pss5',subj:'p-social-studies',strand:'pss-geog',level:4,diff:2,q:'Trinidad and Tobago is located in which region?',opts:['the Caribbean','West Africa','Central America','South East Asia'],a:0,why:'Trinidad and Tobago is the southernmost country in the Caribbean, just off the coast of South America.',tech:'Know your position: south of the Caribbean chain, close to Venezuela, with the Atlantic to the east.'},
{id:'pss6',subj:'p-social-studies',strand:'pss-geog',level:5,diff:2,q:'Which is a natural resource of Trinidad and Tobago?',opts:['petroleum and natural gas','motor cars','aeroplanes','mobile phones'],a:0,why:'Oil and natural gas occur naturally and are the country’s most valuable resources. The others are manufactured.',tech:'Natural resources come from the earth or the sea. If a factory made it, it is not one.'},
{id:'pss7',subj:'p-social-studies',strand:'pss-history',level:4,diff:2,q:'Who were the first people to live in Trinidad and Tobago?',opts:['the First Peoples','the Spanish','the British','the French'],a:0,why:'The First Peoples, including the Kalinago and Warao, lived here long before Europeans arrived.',tech:'The order is: First Peoples, then Spanish, then British. Everything else hangs off that sequence.'},
{id:'pss8',subj:'p-social-studies',strand:'pss-history',level:5,diff:2,q:'Emancipation Day in Trinidad and Tobago is celebrated on:',opts:['1 August','31 August','30 May','24 September'],a:0,why:'Emancipation Day is 1 August, marking the end of slavery. Independence Day is 31 August and Indian Arrival Day is 30 May.',tech:'Three national days, three different events. Learn the date with the reason, not on its own.'},
{id:'pss9',subj:'p-social-studies',strand:'pss-citizen',level:3,diff:2,q:'Living in a country where people follow many different religions means we should:',opts:['respect beliefs that are not our own','ask everyone to change','only speak to people like us','ignore other festivals'],a:0,why:'Trinidad and Tobago is a plural society. Respecting difference is what allows people to live together peacefully.',tech:'Name real festivals — Divali, Eid, Christmas, Hosay — when a question asks about the plural society.'},
{id:'pss10',subj:'p-social-studies',strand:'pss-citizen',level:5,diff:2,q:'Which action shows good citizenship?',opts:['reporting a burst water main to the authorities','ignoring litter in the street','keeping to yourself always','taking what you need from a neighbour'],a:0,why:'Good citizens look after shared property and help their community, not only themselves.',tech:'Give an example from your own community in the answer. It lifts a general answer into a good one.'}
);

/* ============ BATCH A — Primary Mathematics, all twelve strands ============ */
window.CSEC_QUESTIONS.push(
{id:'pm26',subj:'p-mathematics',strand:'pm-place',level:1,diff:1,q:'Which number comes next: 17, 18, 19, ___ ?',opts:['20','21','19','10'],a:0,why:'After 19 the ones digit goes back to 0 and the tens digit goes up by one, giving 20.',tech:'When the ones reach 9, the next number starts a new ten.'},
{id:'pm27',subj:'p-mathematics',strand:'pm-place',level:2,diff:1,q:'Write "four hundred and six" in figures.',opts:['406','460','4006','46'],a:0,why:'Four hundreds, no tens and six ones gives 406. The 0 holds the tens place.',tech:'Zero is a placeholder, not nothing. Without it 406 would become 46.'},
{id:'pm28',subj:'p-mathematics',strand:'pm-place',level:3,diff:2,q:'What is 1 000 more than 4 736?',opts:['5 736','4 836','4 746','14 736'],a:0,why:'Adding 1 000 changes only the thousands digit: 4 becomes 5, giving 5 736.',tech:'Adding a round number only touches that column, unless it carries.'},
{id:'pm29',subj:'p-mathematics',strand:'pm-place',level:4,diff:2,q:'Round 27 649 to the nearest thousand.',opts:['28 000','27 000','27 600','30 000'],a:0,why:'The hundreds digit is 6, which is five or more, so the thousands digit rounds up from 27 to 28.',tech:'Look at ONE digit to the right of the place you are rounding to. Nothing else matters.'},
{id:'pm30',subj:'p-mathematics',strand:'pm-place',level:5,diff:2,q:'Arrange from smallest to largest: 2.5, 2.05, 2.55',opts:['2.05, 2.5, 2.55','2.5, 2.05, 2.55','2.55, 2.5, 2.05','2.05, 2.55, 2.5'],a:0,why:'Compare tenths first: 2.05 has 0 tenths, 2.5 and 2.55 have 5. Then 2.5 is 2.50, which is less than 2.55.',tech:'Give every decimal the same number of places before comparing: 2.50, 2.05, 2.55.'},
{id:'pm31',subj:'p-mathematics',strand:'pm-ops',level:1,diff:1,q:'What is 8 + 5?',opts:['13','12','14','15'],a:0,why:'Take 2 from the 5 to make the 8 into 10, then add the remaining 3: 10 + 3 = 13.',tech:'Bridge to ten. It is faster and more reliable than counting on fingers.'},
{id:'pm32',subj:'p-mathematics',strand:'pm-ops',level:2,diff:2,q:'What is 63 − 28?',opts:['35','45','41','31'],a:0,why:'You cannot take 8 from 3, so borrow a ten: 13 − 8 = 5, then 5 − 2 = 3, giving 35.',tech:'Check by adding back: 35 + 28 = 63. If it does not come back, you slipped.'},
{id:'pm33',subj:'p-mathematics',strand:'pm-ops',level:3,diff:2,q:'A shop sells 9 crates of 48 bottles. How many bottles?',opts:['432','422','372','452'],a:0,why:'9 × 48. Do 9 × 50 = 450 then take away 9 × 2 = 18, giving 432.',tech:'Round to a friendly number, multiply, then adjust. Much faster than long multiplication.'},
{id:'pm34',subj:'p-mathematics',strand:'pm-ops',level:4,diff:3,q:'What is 736 ÷ 8?',opts:['92','82','90','98'],a:0,why:'8 into 73 goes 9 times with 1 left over; 8 into 16 goes 2. So 92.',tech:'Multiply your answer back by the divisor. 92 × 8 = 736.'},
{id:'pm35',subj:'p-mathematics',strand:'pm-ops',level:5,diff:3,q:'Work out 5 + 3 × 4',opts:['17','32','20','12'],a:0,why:'Multiplication comes before addition: 3 × 4 = 12, then 5 + 12 = 17.',tech:'Do multiplying and dividing before adding and subtracting, unless brackets say otherwise.'},
{id:'pm36',subj:'p-mathematics',strand:'pm-fractions',level:2,diff:1,q:'Which is larger: 1/2 or 1/4?',opts:['1/2','1/4','they are equal','you cannot tell'],a:0,why:'Cutting something into 2 pieces gives bigger pieces than cutting it into 4.',tech:'With the same top number, the SMALLER the bottom, the bigger the fraction.'},
{id:'pm37',subj:'p-mathematics',strand:'pm-fractions',level:3,diff:2,q:'Which fraction is equivalent to 2/3?',opts:['4/6','3/4','2/6','6/8'],a:0,why:'Multiply top and bottom by 2: 2 × 2 = 4 and 3 × 2 = 6, giving 4/6.',tech:'Whatever you do to the top you must do to the bottom. That keeps the value the same.'},
{id:'pm38',subj:'p-mathematics',strand:'pm-fractions',level:4,diff:2,q:'Simplify 6/8 to its lowest terms.',opts:['3/4','2/4','6/8','1/2'],a:0,why:'Both 6 and 8 divide by 2, giving 3/4. Nothing divides both 3 and 4, so it is now simplest.',tech:'Keep dividing top and bottom by the same number until you cannot any more.'},
{id:'pm39',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:3,q:'What is 1/2 + 1/4?',opts:['3/4','2/6','1/6','2/4'],a:0,why:'Change 1/2 into 2/4 so both bottoms match, then add the tops: 2/4 + 1/4 = 3/4.',tech:'Different bottoms? Make them the same FIRST, then add only the tops.'},
{id:'pm40',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:3,q:'What is 2/5 of 45?',opts:['18','9','15','22'],a:0,why:'Find one fifth first: 45 ÷ 5 = 9. Then two fifths is 9 × 2 = 18.',tech:'Divide by the bottom, multiply by the top. Always in that order.'},
{id:'pm41',subj:'p-mathematics',strand:'pm-decimals',level:4,diff:2,q:'What is 3.6 + 2.45?',opts:['6.05','5.81','6.15','3.81'],a:0,why:'Write 3.6 as 3.60 and line up the points: 3.60 + 2.45 = 6.05.',tech:'Line up the decimal points, not the last digits. Fill gaps with zeros.'},
{id:'pm42',subj:'p-mathematics',strand:'pm-decimals',level:4,diff:2,q:'Write 1/4 as a decimal.',opts:['0.25','0.14','0.4','0.75'],a:0,why:'One quarter is 25 hundredths, which is 0.25.',tech:'Learn the four that come up constantly: 1/2 = 0.5, 1/4 = 0.25, 3/4 = 0.75, 1/10 = 0.1.'},
{id:'pm43',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'Find 10% of TT$250.',opts:['TT$25','TT$2.50','TT$50','TT$20'],a:0,why:'Ten per cent means one tenth, so divide by 10: 250 ÷ 10 = TT$25.',tech:'Once you have 10%, you can build others: 20% is double it, 5% is half it.'},
{id:'pm44',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:3,q:'A shirt costs TT$120. In a sale it is reduced by 20%. What is the sale price?',opts:['TT$96','TT$100','TT$24','TT$140'],a:0,why:'20% of 120 is 24. The sale price is 120 − 24 = TT$96.',tech:'Read whether they want the discount or the new price. They are different answers.'},
{id:'pm45',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'Write 0.75 as a fraction in simplest form.',opts:['3/4','75/100','7/5','1/4'],a:0,why:'0.75 is 75 hundredths, 75/100. Dividing both by 25 gives 3/4.',tech:'Two decimal places means hundredths. Then simplify.'},
{id:'pm46',subj:'p-mathematics',strand:'pm-money',level:1,diff:1,q:'How many 25-cent coins make one dollar?',opts:['4','3','5','10'],a:0,why:'Four lots of 25 cents make 100 cents, which is one dollar.',tech:'One dollar is always 100 cents. Work out how many of the coin fit into 100.'},
{id:'pm47',subj:'p-mathematics',strand:'pm-money',level:2,diff:2,q:'Sweets cost 60 cents each. How much for 5?',opts:['TT$3.00','TT$2.60','TT$3.60','TT$30.00'],a:0,why:'5 × 60 cents = 300 cents, and 300 cents is TT$3.00.',tech:'Work in cents, then change to dollars at the end by dividing by 100.'},
{id:'pm48',subj:'p-mathematics',strand:'pm-money',level:3,diff:2,q:'You buy items for TT$12.75 and TT$6.40. What is the total?',opts:['TT$19.15','TT$18.15','TT$19.05','TT$18.95'],a:0,why:'12.75 + 6.40 = 19.15.',tech:'Add the cents first, carry if they pass 100, then add the dollars.'},
{id:'pm49',subj:'p-mathematics',strand:'pm-money',level:4,diff:3,q:'A trader buys a bag for TT$40 and sells it for TT$55. What is the profit?',opts:['TT$15','TT$95','TT$40','TT$55'],a:0,why:'Profit is selling price minus cost price: 55 − 40 = TT$15.',tech:'Selling price above cost is profit; below cost is loss. Write down which is which before you subtract.'},
{id:'pm50',subj:'p-mathematics',strand:'pm-money',level:5,diff:3,q:'A phone bill is TT$180 a month. What is the cost for a year?',opts:['TT$2 160','TT$1 800','TT$2 060','TT$1 080'],a:0,why:'12 months at 180: 180 × 12 = 2 160.',tech:'A year is 12 months. Multiply, do not add twelve times.'},
{id:'pm51',subj:'p-mathematics',strand:'pm-time',level:1,diff:1,q:'How many minutes are in one hour?',opts:['60','100','30','24'],a:0,why:'One hour is 60 minutes, and one minute is 60 seconds.',tech:'Time does not work in tens. Sixty is the number to remember.'},
{id:'pm52',subj:'p-mathematics',strand:'pm-time',level:2,diff:1,q:'How many days are in a week, and weeks in a year?',opts:['7 days, 52 weeks','7 days, 12 weeks','5 days, 52 weeks','7 days, 365 weeks'],a:0,why:'Seven days make a week and there are 52 weeks in a year.',tech:'Learn the block: 7 days, about 4 weeks in a month, 12 months and 52 weeks in a year.'},
{id:'pm53',subj:'p-mathematics',strand:'pm-time',level:3,diff:2,q:'School starts at 8:15 a.m. and ends at 2:30 p.m. How long is the school day?',opts:['6 hours 15 minutes','5 hours 15 minutes','6 hours 45 minutes','7 hours 15 minutes'],a:0,why:'From 8:15 to 2:15 is 6 hours, then 2:15 to 2:30 is another 15 minutes.',tech:'Count up in whole hours first, then add the leftover minutes.'},
{id:'pm54',subj:'p-mathematics',strand:'pm-time',level:4,diff:2,q:'Write 06:45 using a.m. or p.m.',opts:['6:45 a.m.','6:45 p.m.','18:45 a.m.','6:45 midnight'],a:0,why:'Hours below 12 on the 24-hour clock are morning, so 06:45 is 6:45 a.m.',tech:'24-hour times below 12:00 are a.m.; 13:00 and above are p.m. after taking 12 away.'},
{id:'pm55',subj:'p-mathematics',strand:'pm-time',level:5,diff:3,q:'A bus leaves at 09:50 and the journey takes 1 hour 25 minutes. When does it arrive?',opts:['11:15','11:25','10:75','11:05'],a:0,why:'09:50 plus 1 hour is 10:50. Plus 25 minutes: 50 + 25 = 75 minutes, which is 1 hour 15, so 11:15.',tech:'Minutes never go past 59. When they do, carry an hour.'},
{id:'pm56',subj:'p-mathematics',strand:'pm-measure',level:1,diff:1,q:'Which unit would you use to measure the length of your classroom?',opts:['metres','millimetres','kilometres','grams'],a:0,why:'A classroom is a few metres long. Millimetres would be tiny, kilometres far too big, and grams measure mass.',tech:'Pick the unit that gives a sensible number — not 8 000 and not 0.008.'},
{id:'pm57',subj:'p-mathematics',strand:'pm-measure',level:2,diff:1,q:'How many grams are in one kilogram?',opts:['1 000','100','10','1 000 000'],a:0,why:'"Kilo" means a thousand, so one kilogram is 1 000 grams.',tech:'Kilo always means a thousand — kilogram, kilometre, kilolitre.'},
{id:'pm58',subj:'p-mathematics',strand:'pm-measure',level:3,diff:2,q:'How many metres are in 3 kilometres?',opts:['3 000 m','300 m','30 m','3 000 000 m'],a:0,why:'One kilometre is 1 000 metres, so 3 × 1 000 = 3 000 m.',tech:'Going to a smaller unit multiplies. Going to a bigger unit divides.'},
{id:'pm59',subj:'p-mathematics',strand:'pm-measure',level:4,diff:2,q:'A bag of rice weighs 2.5 kg. What is that in grams?',opts:['2 500 g','250 g','25 g','25 000 g'],a:0,why:'2.5 × 1 000 = 2 500 g.',tech:'Move the decimal point three places right when changing kg to g.'},
{id:'pm60',subj:'p-mathematics',strand:'pm-measure',level:5,diff:3,q:'A jug holds 2 litres. How many 250 ml cups can be filled from it?',opts:['8','4','5','20'],a:0,why:'2 litres is 2 000 ml. 2 000 ÷ 250 = 8 cups.',tech:'Change both amounts to the SAME unit before dividing.'},
{id:'pm61',subj:'p-mathematics',strand:'pm-area',level:3,diff:2,q:'A rectangle is 6 cm by 4 cm. What is its perimeter?',opts:['20 cm','24 cm','10 cm','14 cm'],a:0,why:'Perimeter is all four sides: 6 + 4 + 6 + 4 = 20 cm.',tech:'A rectangle has two pairs of equal sides, so perimeter is 2 × (length + width).'},
{id:'pm62',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'A square garden has an area of 36 m². How long is each side?',opts:['6 m','9 m','18 m','4 m'],a:0,why:'Area of a square is side × side. Since 6 × 6 = 36, each side is 6 m.',tech:'Working backwards from area of a square means finding the number that multiplies by itself.'},
{id:'pm63',subj:'p-mathematics',strand:'pm-area',level:5,diff:3,q:'An L-shape is made of a 5 cm × 4 cm rectangle joined to a 3 cm × 2 cm rectangle. What is the total area?',opts:['26 cm²','20 cm²','6 cm²','30 cm²'],a:0,why:'Work out each piece and add: (5 × 4) + (3 × 2) = 20 + 6 = 26 cm².',tech:'Split a compound shape into rectangles, find each area, then add. Draw the split line.'},
{id:'pm64',subj:'p-mathematics',strand:'pm-area',level:5,diff:3,q:'A cuboid tank is 10 cm long, 5 cm wide and 4 cm deep. How much water does it hold?',opts:['200 cm³','19 cm³','40 cm³','100 cm³'],a:0,why:'Volume is length × width × height: 10 × 5 × 4 = 200 cm³.',tech:'Multiply two of them first, then the third. Order does not matter.'},
{id:'pm65',subj:'p-mathematics',strand:'pm-shapes',level:1,diff:1,q:'How many sides does a rectangle have?',opts:['4','3','5','6'],a:0,why:'A rectangle has four sides — two long and two short.',tech:'Count the straight edges around the outside.'},
{id:'pm66',subj:'p-mathematics',strand:'pm-shapes',level:2,diff:1,q:'Which solid shape is a ball?',opts:['a sphere','a cube','a cylinder','a cone'],a:0,why:'A ball is a sphere. It has one curved surface and no edges or corners.',tech:'Match everyday objects to solids: tin is a cylinder, dice is a cube, party hat is a cone.'},
{id:'pm67',subj:'p-mathematics',strand:'pm-shapes',level:3,diff:2,q:'How many edges does a cube have?',opts:['12','6','8','4'],a:0,why:'A cube has 12 edges, 6 faces and 8 vertices.',tech:'Count one face (4 edges), then the opposite face (4), then the 4 joining them.'},
{id:'pm68',subj:'p-mathematics',strand:'pm-shapes',level:4,diff:2,q:'A shape with four equal sides and four right angles is a:',opts:['square','rectangle','rhombus','trapezium'],a:0,why:'A rhombus has four equal sides but not always right angles. A rectangle has right angles but not always equal sides. A square has both.',tech:'Check BOTH conditions the question gives before choosing.'},
{id:'pm69',subj:'p-mathematics',strand:'pm-shapes',level:5,diff:2,q:'How many faces does a cylinder have?',opts:['3','2','1','4'],a:0,why:'A cylinder has two flat circular faces and one curved surface, making three in total.',tech:'Remember to count the curved surface. Most people forget it.'},
{id:'pm70',subj:'p-mathematics',strand:'pm-angles',level:3,diff:1,q:'Two lines that never meet, however far they go, are called:',opts:['parallel','perpendicular','curved','diagonal'],a:0,why:'Parallel lines stay the same distance apart. Perpendicular lines cross at a right angle.',tech:'Parallel looks like railway lines. Perpendicular looks like a corner.'},
{id:'pm71',subj:'p-mathematics',strand:'pm-angles',level:4,diff:2,q:'An angle of 45° is:',opts:['acute','obtuse','right','straight'],a:0,why:'Anything less than 90° is acute. 45° is half a right angle.',tech:'Compare with 90° every time: smaller is acute, bigger is obtuse.'},
{id:'pm72',subj:'p-mathematics',strand:'pm-angles',level:4,diff:2,q:'How many degrees are in a half turn?',opts:['180°','90°','360°','45°'],a:0,why:'A full turn is 360°, so half of that is 180° — a straight line.',tech:'Quarter turn 90°, half turn 180°, three quarters 270°, full turn 360°.'},
{id:'pm73',subj:'p-mathematics',strand:'pm-angles',level:5,diff:2,q:'How many lines of symmetry does a square have?',opts:['4','2','1','8'],a:0,why:'A square can be folded in half two ways through the middle and two ways corner to corner: four lines.',tech:'Imagine folding so both halves match exactly. Each fold that works is a line of symmetry.'},
{id:'pm74',subj:'p-mathematics',strand:'pm-angles',level:5,diff:3,q:'Two angles on a straight line are 110° and x. What is x?',opts:['70°','80°','250°','90°'],a:0,why:'Angles on a straight line add to 180°, so x = 180 − 110 = 70°.',tech:'On a line 180°, round a point 360°, in a triangle 180°. Three facts, most angle questions.'},
{id:'pm75',subj:'p-mathematics',strand:'pm-angles',level:5,diff:3,q:'Two angles of a triangle are 50° and 60°. What is the third?',opts:['70°','80°','110°','60°'],a:0,why:'Angles in a triangle add to 180°: 180 − 50 − 60 = 70°.',tech:'Add what you are given, then take it from 180.'},
{id:'pm76',subj:'p-mathematics',strand:'pm-graphs',level:2,diff:1,q:'A tally of |||| |||| shows how many?',opts:['10','8','9','5'],a:0,why:'Each group of five is a gate of four with one across. Two gates make 10.',tech:'Tallies are grouped in fives so you can count up in fives, then add the leftovers.'},
{id:'pm77',subj:'p-mathematics',strand:'pm-graphs',level:3,diff:2,q:'On a bar graph, the tallest bar tells you:',opts:['which was most common','which was least common','the total','the average'],a:0,why:'Height shows how many, so the tallest bar is the one that happened most often.',tech:'Read the scale on the side. The gaps are not always one.'},
{id:'pm78',subj:'p-mathematics',strand:'pm-graphs',level:4,diff:2,q:'A bar graph scale goes up in 5s. A bar reaches halfway between 20 and 25. What does it show?',opts:['22.5','23','21','24'],a:0,why:'Halfway between 20 and 25 is 22.5.',tech:'Work out what one gridline is worth before reading any bar.'},
{id:'pm79',subj:'p-mathematics',strand:'pm-graphs',level:4,diff:2,q:'In a pie chart, a sector that is half the circle represents:',opts:['half of the total','half of the largest group','two groups','180 items'],a:0,why:'The whole circle is the total, so half the circle is half the total.',tech:'Pie charts show proportions, not amounts, unless you are told the total.'},
{id:'pm80',subj:'p-mathematics',strand:'pm-graphs',level:5,diff:3,q:'A pictograph key shows one symbol = 10 books. A row has 3 and a half symbols. How many books?',opts:['35','30','13','3.5'],a:0,why:'Three whole symbols are 30, and half a symbol is 5, giving 35.',tech:'Half a symbol means half the key value. Read the key before anything else.'},
{id:'pm81',subj:'p-mathematics',strand:'pm-graphs',level:5,diff:2,q:'Which graph is best for showing how temperature changed through one day?',opts:['a line graph','a pie chart','a pictograph','a tally chart'],a:0,why:'Line graphs show change over time, which is exactly what a day of temperature readings is.',tech:'Over time → line. Comparing groups → bar. Parts of a whole → pie.'},
{id:'pm82',subj:'p-mathematics',strand:'pm-average',level:4,diff:2,q:'What is the mode of 3, 7, 3, 9, 5?',opts:['3','5','7','9'],a:0,why:'The mode is the value that appears most often. 3 appears twice and everything else once.',tech:'Mode and "most" both start with M.'},
{id:'pm83',subj:'p-mathematics',strand:'pm-average',level:5,diff:2,q:'What is the median of 2, 9, 4, 7, 5?',opts:['5','4','7','9'],a:0,why:'Put them in order: 2, 4, 5, 7, 9. The middle one is 5.',tech:'You must order them first. Taking the middle of the unordered list is the classic error.'},
{id:'pm84',subj:'p-mathematics',strand:'pm-average',level:5,diff:3,q:'The mean of four numbers is 12. What do they add up to?',opts:['48','16','3','12'],a:0,why:'Mean is the total divided by how many. So the total is 12 × 4 = 48.',tech:'Working backwards from a mean means multiplying, not dividing.'},
{id:'pm85',subj:'p-mathematics',strand:'pm-average',level:5,diff:3,q:'A pupil scores 8, 6 and 10 in three tests. What is the mean score?',opts:['8','7','9','24'],a:0,why:'8 + 6 + 10 = 24, and 24 ÷ 3 = 8.',tech:'The mean should land between the smallest and largest value. If it does not, check your work.'},
{id:'pm86',subj:'p-mathematics',strand:'pm-average',level:4,diff:2,q:'What is the range of 4, 11, 7, 2?',opts:['9','11','2','6'],a:0,why:'Range is the largest minus the smallest: 11 − 2 = 9.',tech:'Range measures spread, not a typical value. It is one subtraction.'}
);

/* ======== BATCH B — Primary English Language Arts & ELA Writing ======== */
window.CSEC_QUESTIONS.push(
{id:'pel17',subj:'p-ela',strand:'pe-spell',level:1,diff:1,q:'Which word is spelled correctly?',opts:['friend','freind','frend','friennd'],a:0,why:'It is f-r-i-e-n-d. The i comes before the e.',tech:'Say it as "fri-end". The word "end" is hiding at the end of friend.'},
{id:'pel18',subj:'p-ela',strand:'pe-spell',level:2,diff:1,q:'Which word is spelled correctly?',opts:['beautiful','beutiful','beautifull','beautyful'],a:0,why:'It is b-e-a-u-t-i-f-u-l, with one l at the end.',tech:'Break it into beau-ti-ful and say each part as you write it.'},
{id:'pel19',subj:'p-ela',strand:'pe-spell',level:3,diff:2,q:'Which is the correct plural of "baby"?',opts:['babies','babys','babyes','babie'],a:0,why:'When a word ends in a consonant followed by y, change the y to i and add es.',tech:'Check the letter before the y. A vowel means just add s (days); a consonant means y becomes ies.'},
{id:'pel20',subj:'p-ela',strand:'pe-spell',level:4,diff:2,q:'Which word is spelled correctly?',opts:['necessary','neccessary','necesary','neccesary'],a:0,why:'One c and two s: n-e-c-e-s-s-a-r-y.',tech:'One collar, two sleeves — one c, two s.'},
{id:'pel21',subj:'p-ela',strand:'pe-spell',level:5,diff:2,q:'Choose the correct word: "The dog wagged ___ tail."',opts:['its','it’s','its’','it is'],a:0,why:'"Its" shows belonging. "It’s" is short for "it is", which would not make sense here.',tech:'Try reading it as "it is". If that sounds wrong, you need "its" with no apostrophe.'},
{id:'pel22',subj:'p-ela',strand:'pe-punct',level:1,diff:1,q:'Which sentence ends with the correct mark?',opts:['Where do you live?','Where do you live.','Where do you live!','where do you live'],a:0,why:'It is a question, so it takes a question mark.',tech:'Asking takes ?, telling takes ., shouting takes !.'},
{id:'pel23',subj:'p-ela',strand:'pe-punct',level:3,diff:2,q:'Which sentence uses commas correctly?',opts:['I bought mangoes, oranges, and bananas.','I bought mangoes oranges and bananas.','I bought, mangoes oranges and bananas.','I bought mangoes, oranges and, bananas.'],a:0,why:'Commas separate items in a list.',tech:'Read the sentence aloud. Where you naturally pause between items is where a comma goes.'},
{id:'pel24',subj:'p-ela',strand:'pe-punct',level:4,diff:2,q:'Which needs a capital letter?',opts:['tobago','island','beach','sand'],a:0,why:'Tobago is the name of a particular place, so it is a proper noun and takes a capital.',tech:'Names of people, places, days, months and countries always take capitals.'},
{id:'pel25',subj:'p-ela',strand:'pe-punct',level:5,diff:3,q:'Which sentence is punctuated correctly?',opts:['After the rain stopped, we went outside.','After the rain stopped we went, outside.','After, the rain stopped we went outside.','After the rain stopped we went outside'],a:0,why:'A comma separates the opening part from the main part of the sentence, and it needs a full stop.',tech:'When a sentence starts with "After", "When" or "Because", a comma usually follows that opening part.'},
{id:'pel26',subj:'p-ela',strand:'pe-grammar',level:1,diff:1,q:'Which word is a noun?',opts:['table','quickly','jump','blue'],a:0,why:'A noun names a person, place or thing. A table is a thing.',tech:'If you can put "the" in front of it, it is probably a noun.'},
{id:'pel27',subj:'p-ela',strand:'pe-grammar',level:2,diff:1,q:'Choose the correct word: "They ___ playing football."',opts:['are','is','am','was all'],a:0,why:'"They" is plural, so it takes "are".',tech:'I am, he/she/it is, we/you/they are. Learn the three together.'},
{id:'pel28',subj:'p-ela',strand:'pe-grammar',level:3,diff:2,q:'Which word is an adjective in: "The tall boy ran fast."',opts:['tall','boy','ran','fast'],a:0,why:'"Tall" describes the boy, so it is an adjective. "Fast" describes how he ran, so it is an adverb.',tech:'Adjectives describe nouns. Adverbs describe verbs and often end in -ly.'},
{id:'pel29',subj:'p-ela',strand:'pe-grammar',level:4,diff:2,q:'Choose the correct pronoun: "Reena and ___ went to the shop."',opts:['I','me','myself','mine'],a:0,why:'Take Reena away and read it: "I went to the shop" is right, "me went" is not.',tech:'Remove the other person and test the sentence on its own.'},
{id:'pel30',subj:'p-ela',strand:'pe-grammar',level:5,diff:3,q:'Which sentence is correct?',opts:['Neither of the girls was late.','Neither of the girls were late.','Neither of the girl were late.','Neither of the girls are late.'],a:0,why:'"Neither" is singular, so it takes "was", even though "girls" sits next to it.',tech:'Cover the "of the ..." part. The verb must agree with what is left.'},
{id:'pel31',subj:'p-ela',strand:'pe-vocab',level:3,diff:2,q:'"The room was gloomy." The word "gloomy" means:',opts:['dark and cheerless','bright and warm','large and empty','clean and tidy'],a:0,why:'Gloomy means dim and rather sad in feeling.',tech:'Look at the whole sentence and ask what would fit the mood being described.'},
{id:'pel32',subj:'p-ela',strand:'pe-vocab',level:4,diff:2,q:'Which word means the OPPOSITE of "ancient"?',opts:['modern','old','historic','aged'],a:0,why:'Ancient means very old, so its opposite is modern. The other three all mean old.',tech:'For an opposite question, cross off every word that means the SAME thing first.'},
{id:'pel33',subj:'p-ela',strand:'pe-vocab',level:5,diff:2,q:'"She was reluctant to speak." Reluctant means:',opts:['unwilling','eager','ready','loud'],a:0,why:'Reluctant means hesitant or unwilling to do something.',tech:'The prefix or the rest of the sentence usually carries the clue. Here, "to speak" suggests holding back.'},
{id:'pel34',subj:'p-ela',strand:'pe-fiction',level:2,diff:1,q:'The SETTING of a story is:',opts:['where and when it takes place','who is in it','what happens','who wrote it'],a:0,why:'Setting is the place and the time. The people are characters and what happens is the plot.',tech:'Note the setting in the first read-through. Later questions often depend on it.'},
{id:'pel35',subj:'p-ela',strand:'pe-fiction',level:3,diff:2,q:'In a story, the PLOT is:',opts:['the series of events that happen','the message of the story','the place it happens','the main character'],a:0,why:'The plot is what happens, in order. The message is the theme.',tech:'Summarise the plot in one sentence after reading. It anchors every other answer.'},
{id:'pel36',subj:'p-ela',strand:'pe-fiction',level:4,diff:2,q:'"Anil clenched his fists and turned away without a word." This suggests he was:',opts:['angry','delighted','sleepy','confused'],a:0,why:'Clenched fists and turning away silently are signs of anger. The writer shows it rather than saying it.',tech:'Writers show feelings through actions. Read the body language.'},
{id:'pel37',subj:'p-ela',strand:'pe-fiction',level:5,diff:3,q:'A question asks for the THEME of a story. You should give:',opts:['the message or idea the story is about','a list of what happened','the name of the main character','where the story is set'],a:0,why:'Theme is the underlying idea — friendship, courage, honesty. It is not the plot.',tech:'Ask what the story is trying to teach, then say it in one short sentence.'},
{id:'pel38',subj:'p-ela',strand:'pe-nonfict',level:3,diff:2,q:'A FACT is different from an OPINION because a fact:',opts:['can be checked and proved','is what somebody believes','is always interesting','is always longer'],a:0,why:'A fact can be checked. An opinion is a belief and may differ from person to person.',tech:'Watch for words like best, worst, should and beautiful. They usually signal an opinion.'},
{id:'pel39',subj:'p-ela',strand:'pe-nonfict',level:4,diff:2,q:'The main purpose of a report about recycling is to:',opts:['inform the reader','tell a funny story','sell something','describe a character'],a:0,why:'Reports inform and explain. Stories entertain and advertisements persuade.',tech:'Ask what the writer wanted: to inform, to entertain, or to persuade.'},
{id:'pel40',subj:'p-ela',strand:'pe-nonfict',level:5,diff:2,q:'Where in a non-fiction book would you look to find which page a topic is on?',opts:['the index','the title page','the glossary','the blurb'],a:0,why:'The index lists topics with page numbers. The glossary explains words.',tech:'Contents is at the front and in order; index is at the back and alphabetical.'},
{id:'pel41',subj:'p-ela',strand:'pe-poetry',level:3,diff:2,q:'A group of lines in a poem is called a:',opts:['stanza','paragraph','chapter','sentence'],a:0,why:'Poems are grouped into stanzas. Prose is grouped into paragraphs.',tech:'Count the stanzas and the lines in each before answering. Form often matters.'},
{id:'pel42',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"The bees buzzed busily." This repeated b sound is called:',opts:['alliteration','rhyme','rhythm','a simile'],a:0,why:'Alliteration is the same sound at the start of nearby words.',tech:'Name the device, then say what it does — here the buzzing sound is echoed in the words.'},
{id:'pel43',subj:'p-ela',strand:'pe-poetry',level:5,diff:2,q:'"Her smile was as bright as the morning sun." This is:',opts:['a simile','a metaphor','alliteration','personification'],a:0,why:'It compares two things using "as", which makes it a simile.',tech:'Like or as means simile. Saying one thing IS another means metaphor.'},
{id:'pel44',subj:'p-ela',strand:'pe-graphic',level:4,diff:2,q:'A label on a diagram of a plant tells you:',opts:['the name of each part','how tall the plant grows','who drew it','where it was found'],a:0,why:'Labels name the parts they point to.',tech:'Read every label before answering a diagram question. The answer is usually on the picture.'},
{id:'pel45',subj:'p-ela',strand:'pe-graphic',level:5,diff:2,q:'An advertisement says a drink is "the best in the world". This is:',opts:['an opinion used to persuade','a proven fact','a warning','an instruction'],a:0,why:'"Best" cannot be proved. It is an opinion designed to make you buy.',tech:'Advertisements persuade. Look for exaggerated words and ask whether they could be checked.'},
{id:'pel46',subj:'p-ela',strand:'pe-graphic',level:5,diff:2,q:'On a map, a key or legend tells you:',opts:['what the symbols mean','how far away places are','who owns the land','the weather'],a:0,why:'The key explains the symbols. Distance comes from the scale.',tech:'Key for symbols, scale for distance. Check both before answering.'},

{id:'pw9',subj:'p-ela-writing',strand:'pw-narrative',level:2,diff:1,q:'Which sentence is the best ENDING for a story?',opts:['As the bus pulled away, Ria finally let herself smile.','And that was my story.','The end of my story is here.','I will stop writing now.'],a:0,why:'A good ending shows the character and closes the feeling. The others just announce that the writing has stopped.',tech:'Never end with "and then I woke up" or "that was my story". Finish inside the moment.'},
{id:'pw10',subj:'p-ela-writing',strand:'pw-narrative',level:3,diff:2,q:'Before you start writing a story you should:',opts:['plan the beginning, the problem and the ending','count how many lines you have','choose the longest words you know','write the title in big letters'],a:0,why:'Two minutes of planning stops a story that wanders and never finishes.',tech:'Three boxes: how it starts, what goes wrong, how it ends. Then write.'},
{id:'pw11',subj:'p-ela-writing',strand:'pw-narrative',level:4,diff:2,q:'Most stories need a PROBLEM because:',opts:['without one nothing happens and the reader stops caring','stories must be sad','it makes the story longer','the marker asks for one'],a:0,why:'The problem is what drives the story. Something must go wrong for there to be anything to tell.',tech:'If you cannot say what goes wrong in your story, it is a description, not a story.'},
{id:'pw12',subj:'p-ela-writing',strand:'pw-narrative',level:5,diff:2,q:'In a story, dialogue is useful because it:',opts:['shows what characters are like through what they say','fills up the page','avoids describing things','is easier than writing sentences'],a:0,why:'How a character speaks tells the reader who they are, without the writer having to explain.',tech:'Use a little dialogue well. Remember the speech marks and start a new line for each speaker.'},
{id:'pw13',subj:'p-ela-writing',strand:'pw-language',level:3,diff:2,q:'Which is the strongest verb?',opts:['She dashed to the gate.','She went to the gate.','She was going to the gate.','She got to the gate.'],a:0,why:'"Dashed" tells you the speed and the urgency. "Went" and "got" tell you almost nothing.',tech:'Replace weak verbs like went, got and said with ones that carry meaning.'},
{id:'pw14',subj:'p-ela-writing',strand:'pw-language',level:4,diff:2,q:'Which sentence appeals to the sense of SOUND?',opts:['The galvanise rattled in the wind.','The house was old.','The yard was wide.','The gate was blue.'],a:0,why:'Rattling is something you hear. The others describe only what you see.',tech:'In a story, try to use at least two senses, not only sight.'},
{id:'pw15',subj:'p-ela-writing',strand:'pw-language',level:5,diff:2,q:'"The wind tugged at her skirt like an impatient child." This works because it:',opts:['compares the wind to something the reader knows','uses a long word','is a true fact','rhymes'],a:0,why:'A good comparison makes the reader picture and feel the thing being described.',tech:'One strong comparison beats three weak ones. Do not put a simile in every sentence.'},
{id:'pw16',subj:'p-ela-writing',strand:'pw-organise',level:3,diff:2,q:'A story should be written in:',opts:['paragraphs','one long block of writing','bullet points','numbered steps'],a:0,why:'Paragraphs group ideas and are one of the four things markers score under Organisation.',tech:'Leave a clear line or indent so the marker can SEE the paragraphs.'},
{id:'pw17',subj:'p-ela-writing',strand:'pw-organise',level:4,diff:2,q:'Words like "first", "next", "later" and "finally" help the reader by:',opts:['showing the order events happened in','making the story longer','adding description','starting new characters'],a:0,why:'They are time connectives. They guide the reader through the sequence.',tech:'Use a few, spread out. Starting every paragraph with "Then" gets repetitive.'},
{id:'pw18',subj:'p-ela-writing',strand:'pw-organise',level:5,diff:3,q:'An expository piece about hurricanes would be best organised as:',opts:['an introduction, then a paragraph on each main point, then a conclusion','a story about one hurricane','a list of every fact you know','a poem'],a:0,why:'Expository writing explains, so it needs a clear structure the reader can follow.',tech:'Plan your main points before writing, and give each one its own paragraph.'},
{id:'pw19',subj:'p-ela-writing',strand:'pw-expository',level:4,diff:2,q:'Which opening suits an expository piece about the Scarlet Ibis?',opts:['The Scarlet Ibis is one of the two national birds of Trinidad and Tobago.','One day I saw a red bird and it was nice.','Once upon a time there was a bird.','I like birds a lot, they are my favourite.'],a:0,why:'Expository writing opens with a clear factual statement about the subject.',tech:'An expository opening tells the reader what the piece is about. Save storytelling for narrative.'},
{id:'pw20',subj:'p-ela-writing',strand:'pw-expository',level:5,diff:2,q:'In expository writing you should use:',opts:['facts and specific details','made-up characters','a surprise twist','lots of dialogue'],a:0,why:'Expository writing informs, so it is built on facts and examples rather than plot.',tech:'If you find yourself writing "suddenly", you have slipped back into a story.'},
{id:'pw21',subj:'p-ela-writing',strand:'pw-mechanics',level:2,diff:1,q:'Every sentence must begin with:',opts:['a capital letter','a describing word','the word "The"','a name'],a:0,why:'Sentences always start with a capital and end with a full stop, question mark or exclamation mark.',tech:'This is the cheapest mark in the whole paper. Check every sentence before you hand in.'},
{id:'pw22',subj:'p-ela-writing',strand:'pw-mechanics',level:4,diff:2,q:'Which is written correctly?',opts:['"I’m coming," she said.','"I’m coming." she said.','"Im coming," she said.','"I’m coming" she said'],a:0,why:'The comma goes inside the speech marks, "she said" is not a new sentence, and I’m needs its apostrophe.',tech:'Speech punctuation is worth learning properly. It appears in almost every narrative.'},
{id:'pw23',subj:'p-ela-writing',strand:'pw-mechanics',level:5,diff:3,q:'Which sentence keeps to ONE tense throughout?',opts:['She walked to the shop and bought a drink.','She walks to the shop and bought a drink.','She walked to the shop and buys a drink.','She is walking to the shop and bought a drink.'],a:0,why:'Both verbs are past tense. The others swap between past and present halfway through.',tech:'Pick past or present at the start and stay in it. Swapping is a common lost mark.'}
);

/* ============ BATCH C — CSEC Mathematics, all nine sections ============ */
window.CSEC_QUESTIONS.push(
{id:'ma21',subj:'mathematics',strand:'ma-number',level:6,diff:1,q:'Simplify: 2/3 × 9/10',opts:['3/5','18/30','11/13','6/5'],a:0,why:'Cancel before multiplying: 3 into 9 gives 3, 2 into 10 gives 5. That leaves 1/1 × 3/5 = 3/5.',tech:'Always cancel diagonally before multiplying. It keeps the numbers small.'},
{id:'ma22',subj:'mathematics',strand:'ma-number',level:7,diff:2,q:'Express 0.000 62 in standard form.',opts:['6.2 × 10⁻⁴','62 × 10⁻⁵','6.2 × 10⁴','0.62 × 10⁻³'],a:0,why:'Move the point four places right to get 6.2, so the index is −4.',tech:'The first number must be between 1 and 10. 62 and 0.62 are both wrong on that count alone.'},
{id:'ma23',subj:'mathematics',strand:'ma-number',level:8,diff:2,q:'Evaluate 2⁻³',opts:['1/8','−8','−6','8'],a:0,why:'A negative index means the reciprocal: 2⁻³ = 1/2³ = 1/8. It does not make the answer negative.',tech:'Negative index means "one over". It never makes the result negative.'},
{id:'ma24',subj:'mathematics',strand:'ma-consumer',level:8,diff:2,q:'A television marked TT$4 000 is sold at a 15% discount. What is the selling price?',opts:['TT$3 400','TT$600','TT$3 600','TT$4 600'],a:0,why:'Multiply by 0.85 in one step: 4 000 × 0.85 = TT$3 400.',tech:'Discount of 15% means multiply by 0.85. Finding the discount then subtracting doubles your chances of error.'},
{id:'ma25',subj:'mathematics',strand:'ma-consumer',level:9,diff:3,q:'TT$12 000 is invested at 6% per annum compound interest. What is it worth after 2 years?',opts:['TT$13 483.20','TT$13 440.00','TT$12 720.00','TT$1 483.20'],a:0,why:'Multiply by 1.06 twice: 12 000 × 1.06² = 12 000 × 1.1236 = TT$13 483.20.',tech:'Compound interest is × (1 + r)ⁿ. Simple interest would give 13 440, which is why that option is there.'},
{id:'ma26',subj:'mathematics',strand:'ma-consumer',level:9,diff:2,q:'A worker earns TT$45 per hour for a 40-hour week, with overtime at time and a half. What is the pay for 46 hours?',opts:['TT$2 205','TT$2 070','TT$2 160','TT$1 800'],a:0,why:'Basic: 40 × 45 = 1 800. Overtime: 6 hours at 67.50 = 405. Total TT$2 205.',tech:'Time and a half means 1.5 × the hourly rate, applied only to the hours above the basic week.'},
{id:'ma27',subj:'mathematics',strand:'ma-sets',level:8,diff:2,q:'If A = {1,2,3,4} and B = {3,4,5}, what is A ∩ B?',opts:['{3,4}','{1,2,5}','{1,2,3,4,5}','{ }'],a:0,why:'The intersection is what appears in BOTH sets: 3 and 4.',tech:'∩ is intersection (both), ∪ is union (either). The ∩ looks like an A for "and".'},
{id:'ma28',subj:'mathematics',strand:'ma-sets',level:9,diff:3,q:'In a group of 50, 30 play cricket, 25 play football and 5 play neither. How many play both?',opts:['10','15','20','5'],a:0,why:'At least one = 50 − 5 = 45. Both = (30 + 25) − 45 = 10.',tech:'n(A∪B) = n(A) + n(B) − n(A∩B). Rearrange it to find the overlap.'},
{id:'ma29',subj:'mathematics',strand:'ma-measure',level:8,diff:2,q:'Find the circumference of a circle of radius 7 cm, taking π = 22/7.',opts:['44 cm','154 cm','22 cm','88 cm'],a:0,why:'C = 2πr = 2 × 22/7 × 7 = 44 cm.',tech:'Circumference uses 2πr, area uses πr². Write both at the top of the page.'},
{id:'ma30',subj:'mathematics',strand:'ma-measure',level:9,diff:3,q:'A cylinder has radius 5 cm and height 14 cm. Taking π = 22/7, find its volume.',opts:['1 100 cm³','220 cm³','440 cm³','350 cm³'],a:0,why:'V = πr²h = 22/7 × 25 × 14 = 22 × 25 × 2 = 1 100 cm³.',tech:'Look for the cancel: 14 ÷ 7 = 2 keeps the arithmetic simple.'},
{id:'ma31',subj:'mathematics',strand:'ma-stats',level:8,diff:2,q:'The mean of 5 numbers is 14. Four of them are 10, 12, 16 and 18. What is the fifth?',opts:['14','12','16','70'],a:0,why:'Total must be 5 × 14 = 70. The four given add to 56, so the fifth is 70 − 56 = 14.',tech:'Turn a mean into a total first. That single step solves most "find the missing value" questions.'},
{id:'ma32',subj:'mathematics',strand:'ma-stats',level:9,diff:2,q:'A bag has 4 red, 5 blue and 3 green marbles. What is P(not blue)?',opts:['7/12','5/12','1/3','7/5'],a:0,why:'Not blue means red or green: 4 + 3 = 7 out of 12.',tech:'P(not A) = 1 − P(A). Here 1 − 5/12 = 7/12, which checks the answer.'},
{id:'ma33',subj:'mathematics',strand:'ma-stats',level:10,diff:3,q:'On a cumulative frequency curve of 80 values, the median is read at which cumulative frequency?',opts:['40','80','20','60'],a:0,why:'The median is the middle value, so read across at half the total: 80 ÷ 2 = 40.',tech:'Median at n/2, lower quartile at n/4, upper quartile at 3n/4. Read across, then down.'},
{id:'ma34',subj:'mathematics',strand:'ma-algebra',level:7,diff:2,q:'Expand and simplify: 3(2x − 1) − 2(x + 4)',opts:['4x − 11','4x − 3','8x − 11','4x + 5'],a:0,why:'3(2x−1) = 6x − 3 and −2(x+4) = −2x − 8. Adding: 4x − 11.',tech:'The minus in front of the second bracket applies to BOTH terms inside it.'},
{id:'ma35',subj:'mathematics',strand:'ma-algebra',level:9,diff:2,q:'Factorise: x² − 16',opts:['(x − 4)(x + 4)','(x − 4)²','(x − 8)(x + 2)','(x − 16)(x + 1)'],a:0,why:'This is a difference of two squares: a² − b² = (a − b)(a + b), with a = x and b = 4.',tech:'Two square terms with a minus between them is always difference of two squares. Spot it and you skip the work.'},
{id:'ma36',subj:'mathematics',strand:'ma-algebra',level:9,diff:3,q:'Make r the subject of: A = πr²',opts:['r = √(A/π)','r = A/π','r = √(Aπ)','r = A²/π'],a:0,why:'Divide both sides by π to get A/π = r², then square root both sides.',tech:'Undo the operations in reverse order. The square root comes last because the squaring was applied last.'},
{id:'ma37',subj:'mathematics',strand:'ma-algebra',level:10,diff:3,q:'Solve 2x² − 5x − 3 = 0',opts:['x = 3 or x = −1/2','x = −3 or x = 1/2','x = 3 or x = 1/2','x = 5 or x = −3'],a:0,why:'Factorising gives (2x + 1)(x − 3) = 0, so x = −1/2 or x = 3.',tech:'When the x² has a coefficient, look for factors of a×c that add to b. Here 2 × −3 = −6, and −6 and 1 work.'},
{id:'ma38',subj:'mathematics',strand:'ma-relations',level:8,diff:2,q:'A line has gradient 2 and passes through (0, −3). What is its equation?',opts:['y = 2x − 3','y = −3x + 2','y = 2x + 3','y = 3x − 2'],a:0,why:'y = mx + c with m = 2 and c = −3, since (0, −3) is the y-intercept.',tech:'A point with x = 0 gives you c straight away.'},
{id:'ma39',subj:'mathematics',strand:'ma-relations',level:9,diff:2,q:'If f(x) = 3x − 5, what is f(4)?',opts:['7','12','17','−2'],a:0,why:'Substitute 4 for x: 3(4) − 5 = 12 − 5 = 7.',tech:'f(4) means put 4 in wherever x appears. It is not f multiplied by 4.'},
{id:'ma40',subj:'mathematics',strand:'ma-relations',level:10,diff:3,q:'Solve the inequality: 3x − 4 > 11',opts:['x > 5','x < 5','x > 7','x > 15'],a:0,why:'Add 4 to both sides: 3x > 15. Divide by 3: x > 5.',tech:'Flip the inequality sign ONLY when you multiply or divide by a negative number.'},
{id:'ma41',subj:'mathematics',strand:'ma-geom',level:8,diff:2,q:'Each exterior angle of a regular polygon is 40°. How many sides has it?',opts:['9','8','40','10'],a:0,why:'Exterior angles always add to 360°, so 360 ÷ 40 = 9 sides.',tech:'Exterior sum is always 360° whatever the polygon. That one fact solves most regular-polygon questions.'},
{id:'ma42',subj:'mathematics',strand:'ma-geom',level:9,diff:3,q:'In a right-angled triangle the side opposite a 30° angle is 5 cm. Find the hypotenuse.',opts:['10 cm','8.66 cm','2.5 cm','5.77 cm'],a:0,why:'sin 30° = opposite ÷ hypotenuse, so 0.5 = 5 ÷ h, giving h = 10 cm.',tech:'Label opposite, adjacent and hypotenuse relative to the angle you are USING, then pick with SOH CAH TOA.'},
{id:'ma43',subj:'mathematics',strand:'ma-geom',level:10,diff:3,q:'A bearing of due west is:',opts:['270°','090°','180°','000°'],a:0,why:'Bearings are measured clockwise from north in three figures. North 000°, east 090°, south 180°, west 270°.',tech:'Always write bearings with three figures, so 45° becomes 045°.'},
{id:'ma44',subj:'mathematics',strand:'ma-vectors',level:9,diff:2,q:'If a = (2, −1), what is 3a?',opts:['(6, −3)','(5, 2)','(6, −1)','(2, −3)'],a:0,why:'Multiply each component by 3: (3×2, 3×−1) = (6, −3).',tech:'A scalar multiplies every component, including the negative one.'},
{id:'ma45',subj:'mathematics',strand:'ma-vectors',level:10,diff:3,q:'Find the determinant of the matrix ( 3 1 ; 4 2 ).',opts:['2','10','14','6'],a:0,why:'Determinant of (a b ; c d) is ad − bc: (3×2) − (1×4) = 6 − 4 = 2.',tech:'Multiply the leading diagonal, then subtract the other diagonal. Order matters.'},
{id:'ma46',subj:'mathematics',strand:'ma-vectors',level:10,diff:3,q:'The magnitude of the vector (3, 4) is:',opts:['5','7','12','25'],a:0,why:'|v| = √(3² + 4²) = √25 = 5.',tech:'Magnitude is Pythagoras on the components. Do not forget the square root.'}
);

/* ============ BATCH D — CSEC English A and English B ============ */
window.CSEC_QUESTIONS.push(
{id:'ea13',subj:'english-a',strand:'ea-comp',level:7,diff:2,q:'A question asks you to state the writer’s TONE. You are being asked about:',opts:['the writer’s attitude to the subject','the feeling created in the reader','the subject of the passage','the structure of the argument'],a:0,why:'Tone belongs to the writer — scornful, admiring, detached. Mood is what the reader feels.',tech:'Find the words that carry attitude: loaded adjectives, sarcasm, or a deliberate understatement.'},
{id:'ea14',subj:'english-a',strand:'ea-comp',level:8,diff:2,q:'"Identify the writer’s PURPOSE" means you should say:',opts:['why the piece was written — to inform, persuade, entertain or describe','what the piece is about','who it was written for','how long it is'],a:0,why:'Purpose is the writer’s intention. Audience is who it is aimed at; subject is what it covers.',tech:'Purpose, audience and register travel together. Questions often ask for one and reward mentioning the link.'},
{id:'ea15',subj:'english-a',strand:'ea-comp',level:9,diff:3,q:'In a comprehension answer, quoting from the passage is:',opts:['essential — it is the evidence for your point','optional if your answer is clear','only needed in English B','a way of filling space'],a:0,why:'A point without evidence is an assertion. The quotation is what converts it into a mark.',tech:'Quote briefly and embed it in your own sentence. Copying three lines wastes time and earns nothing extra.'},
{id:'ea16',subj:'english-a',strand:'ea-comp',level:10,diff:3,q:'A passage says a policy was "described as generous by its architects". The phrasing suggests the writer:',opts:['distances himself from the claim','agrees the policy is generous','is quoting a law','admires the architects'],a:0,why:'Attributing the word "generous" to the people who designed it, rather than stating it, signals scepticism.',tech:'Watch for reported claims. Who is saying it, and does the writer endorse it or merely report it?'},
{id:'ea17',subj:'english-a',strand:'ea-summary',level:8,diff:2,q:'In a summary, you should NOT include:',opts:['examples, statistics and quotations','the main idea of each paragraph','the writer’s overall argument','linking between ideas'],a:0,why:'Examples and figures support ideas; they are not the ideas. Cutting them is how you fit the word limit.',tech:'Underline the main idea of each paragraph, then cross out everything that merely illustrates it.'},
{id:'ea18',subj:'english-a',strand:'ea-summary',level:9,diff:3,q:'A summary must be written:',opts:['in continuous prose, in your own words','in bullet points','as a list of quotations','in note form'],a:0,why:'The question asks for continuous prose. Bullets and notes lose the expression marks entirely.',tech:'Write it as one flowing paragraph unless told otherwise, and state your word count at the end.'},
{id:'ea19',subj:'english-a',strand:'ea-summary',level:9,diff:2,q:'Roughly how much of your summary time should go on reading and planning?',opts:['about half','none — start writing at once','about a tenth','all of it'],a:0,why:'A summary written without a plan repeats itself and runs over the limit. Reading twice and marking main ideas is most of the work.',tech:'Read once for sense, once with a pencil, then write. Writing is the quickest part.'},
{id:'ea20',subj:'english-a',strand:'ea-grammar',level:8,diff:2,q:'Which sentence is a run-on (comma splice)?',opts:['It was raining, we stayed inside.','It was raining, so we stayed inside.','Because it was raining, we stayed inside.','It was raining. We stayed inside.'],a:0,why:'Two complete sentences joined by only a comma is a comma splice. It needs a full stop, a semicolon or a joining word.',tech:'If both halves could stand alone as sentences, a comma alone is not enough.'},
{id:'ea21',subj:'english-a',strand:'ea-grammar',level:9,diff:2,q:'Which sentence uses the semicolon correctly?',opts:['The rain stopped; the match resumed.','The rain stopped; and the match resumed.','The rain stopped; because the match resumed.','The rain; stopped the match resumed.'],a:0,why:'A semicolon joins two closely related complete sentences, with no joining word needed.',tech:'Both sides of a semicolon must work as sentences on their own.'},
{id:'ea22',subj:'english-a',strand:'ea-vocab',level:8,diff:2,q:'"The evidence was scant." Scant means:',opts:['barely sufficient','overwhelming','contradictory','recent'],a:0,why:'Scant means meagre or barely enough.',tech:'Read the sentence twice and test each option in the gap. The wrong ones usually jar.'},
{id:'ea23',subj:'english-a',strand:'ea-vocab',level:9,diff:2,q:'Which word has the most NEGATIVE connotation?',opts:['stubborn','determined','resolute','steadfast'],a:0,why:'All four describe not giving way, but "stubborn" carries disapproval while the others carry praise.',tech:'Denotation is the dictionary meaning; connotation is the attitude it carries. Questions on word choice test connotation.'},
{id:'ea24',subj:'english-a',strand:'ea-vocab',level:10,diff:3,q:'"The minister offered a candid assessment." Candid means:',opts:['frank and honest','lengthy','carefully worded','optimistic'],a:0,why:'Candid means open and truthful, even when the truth is unwelcome.',tech:'Build a vocabulary book from your reading. Comprehension vocabulary cannot be crammed the week before.'},
{id:'ea25',subj:'english-a',strand:'ea-narr',level:7,diff:2,q:'Which opening most effectively draws a reader in?',opts:['The letter had been on the table for three days before anyone opened it.','This story is about a letter.','I am going to write about something that happened.','It was a normal day like any other day.'],a:0,why:'It starts inside a situation and raises a question. The others announce rather than begin.',tech:'Open in the middle of something. Never announce that a story is coming.'},
{id:'ea26',subj:'english-a',strand:'ea-narr',level:8,diff:2,q:'In a narrative, a flashback is used to:',opts:['reveal earlier events that explain the present','slow the story down','avoid writing an ending','describe the setting'],a:0,why:'A flashback gives the reader information from before the story’s present, usually to explain a character or a situation.',tech:'Signal a flashback clearly — a line break or a time phrase — so the reader is not lost.'},
{id:'ea27',subj:'english-a',strand:'ea-narr',level:9,diff:2,q:'Which sentence shows rather than tells?',opts:['He read the letter twice, then folded it into his pocket without speaking.','He was upset about the letter.','The letter made him feel bad.','He had a lot of emotions about the letter.'],a:0,why:'The actions let the reader infer the feeling. The other three name it and stop.',tech:'Naming an emotion is the fastest route to a mid-band mark. Give the reader the evidence instead.'},
{id:'ea28',subj:'english-a',strand:'ea-narr',level:10,diff:3,q:'A narrative written in the first person:',opts:['limits the reader to what the narrator knows','always tells the truth','cannot include dialogue','must be autobiographical'],a:0,why:'First person restricts the view to one character’s knowledge, which can be used deliberately to withhold information.',tech:'Choose the person on purpose. First person for intimacy; third for a wider view.'},
{id:'ea29',subj:'english-a',strand:'ea-arg',level:8,diff:2,q:'In an argumentative essay, a counter-argument paragraph should:',opts:['state the opposing view fairly, then answer it','be left out to stay persuasive','agree with the other side','repeat your own points'],a:0,why:'Facing the strongest objection and answering it shows command of the argument. Ignoring it looks like you had no answer.',tech:'One counter-argument, fairly stated and properly answered, lifts an essay more than a fourth point of your own.'},
{id:'ea30',subj:'english-a',strand:'ea-arg',level:9,diff:2,q:'Which is the weakest support for an argument?',opts:['"Everyone knows this is true."','A named study with a figure.','A specific example from Trinidad and Tobago.','A comparison with a similar country.'],a:0,why:'"Everyone knows" is an appeal to popularity, not evidence. The other three can be examined.',tech:'Every claim needs evidence a reader could check. Assertion is not argument.'},
{id:'ea31',subj:'english-a',strand:'ea-arg',level:9,diff:3,q:'The conclusion of an argumentative essay should:',opts:['return to the thesis and say why it matters','introduce a new point','summarise each paragraph in turn','apologise for the length'],a:0,why:'A conclusion consolidates. New material there is wasted because it cannot be developed.',tech:'Never write "In conclusion I have shown". Return to the argument and land it.'},
{id:'ea32',subj:'english-a',strand:'ea-arg',level:10,diff:3,q:'Expository writing differs from argumentative writing because it:',opts:['explains without taking a side','is always shorter','uses no evidence','is written in the first person'],a:0,why:'Exposition informs and explains a process or idea. Argument takes a position and defends it.',tech:'Read the question wording. "Explain how" wants exposition; "Do you agree" wants argument.'},
{id:'ea33',subj:'english-a',strand:'ea-persuade',level:9,diff:2,q:'You are asked to write a speech to your school. The most important thing to adjust is:',opts:['the register and the direct address to the audience','the length','the handwriting','the number of paragraphs'],a:0,why:'A speech is spoken to a known audience, so it addresses them directly and uses a register suited to them.',tech:'For directed writing, write the format, audience and purpose in the margin first. Marks are awarded for all three.'},
{id:'ea34',subj:'english-a',strand:'ea-persuade',level:9,diff:2,q:'Rhetorical questions are used in persuasive writing to:',opts:['make the reader think and agree','avoid giving evidence','fill space','confuse the reader'],a:0,why:'A rhetorical question invites the reader to reach your conclusion themselves, which is more persuasive than asserting it.',tech:'Use one or two. A page of rhetorical questions reads as though you have no argument.'},
{id:'ea35',subj:'english-a',strand:'ea-persuade',level:10,diff:3,q:'Which appeals to the reader’s emotions rather than reason?',opts:['"Think of the children who go to bed hungry tonight."','"Unemployment rose by four per cent last year."','"Three studies reached the same conclusion."','"The policy has been in force since 2019."'],a:0,why:'The first is an emotional appeal. The others present verifiable information.',tech:'A strong persuasive piece uses both. Emotion alone reads as manipulation; evidence alone reads as a report.'},
{id:'ea36',subj:'english-a',strand:'ea-sba',level:9,diff:2,q:'The English A SBA portfolio is built around:',opts:['a plan of investigation on a chosen theme','a single essay','a set of past papers','a reading log'],a:0,why:'The SBA is a portfolio: a plan of investigation, artefacts gathered around a theme, a written report and reflections.',tech:'Choose a theme with plenty of accessible material. A narrow theme starves the portfolio.'},
{id:'ea37',subj:'english-a',strand:'ea-sba',level:10,diff:2,q:'Reflections in the English A SBA should:',opts:['say what you learned and how your thinking changed','summarise each artefact','list your sources','describe the group’s meetings'],a:0,why:'Reflections are about your own learning and response, not a summary of the material.',tech:'Write reflections as you go, not at the end. Written months later they read as invented.'},
{id:'ea38',subj:'english-a',strand:'ea-sba',level:10,diff:2,q:'The single commonest way marks are lost on the SBA is:',opts:['leaving it until Form 5','choosing an unusual theme','writing too much','using local material'],a:0,why:'SBA work gathered under time pressure is thin, and late or incomplete portfolios lose marks outright.',tech:'Start in Form 4. The SBA is the most recoverable set of marks in the whole examination — if you begin early.'},

{id:'eb13',subj:'english-b',strand:'eb-poetry',level:7,diff:2,q:'The RHYTHM of a poem refers to:',opts:['the pattern of stressed and unstressed beats','which lines rhyme','the number of stanzas','the subject matter'],a:0,why:'Rhythm is the beat. Rhyme is the matching of sounds at line ends.',tech:'Read the poem aloud. Rhythm is heard, not seen.'},
{id:'eb14',subj:'english-b',strand:'eb-poetry',level:8,diff:2,q:'"Death, be not proud" addresses death directly. This device is:',opts:['apostrophe','alliteration','assonance','allegory'],a:0,why:'Apostrophe is addressing something absent, abstract or inanimate as though it could reply.',tech:'Name the device, then explain the effect — here, it makes death small enough to argue with.'},
{id:'eb15',subj:'english-b',strand:'eb-poetry',level:9,diff:3,q:'When asked to comment on a poem’s FORM, you should discuss:',opts:['its structure — stanzas, line lengths, rhyme scheme and how they serve meaning','only what the poem is about','the poet’s biography','the historical period'],a:0,why:'Form is the shape of the poem. The top band always links form to meaning rather than describing it.',tech:'Never describe form without saying what it achieves. "Four quatrains" alone earns nothing.'},
{id:'eb16',subj:'english-b',strand:'eb-prose',level:8,diff:2,q:'A round character is one who:',opts:['is complex and develops through the novel','appears frequently','is physically described in detail','is likeable'],a:0,why:'Round characters are many-sided and change. Flat characters stay the same and serve one function.',tech:'Track how a character changes and what causes it. That is what novel questions reward.'},
{id:'eb17',subj:'english-b',strand:'eb-prose',level:9,diff:2,q:'The narrative point of view of a novel matters because it:',opts:['controls what the reader is allowed to know','decides how long the book is','sets the genre','determines the number of chapters'],a:0,why:'A first-person or limited narrator withholds information that an omniscient one could give, which shapes suspense and sympathy.',tech:'Ask who is telling this, and what they cannot see. The gap is often the point.'},
{id:'eb18',subj:'english-b',strand:'eb-prose',level:10,diff:3,q:'Discussing a novel’s THEME requires you to:',opts:['identify an idea the book explores and trace it through the text','retell the plot','describe the main character','name the setting'],a:0,why:'Theme is an idea — power, belonging, betrayal — and must be traced with evidence across the novel.',tech:'Pick three moments from different parts of the book. A theme argued from one scene looks thin.'},
{id:'eb19',subj:'english-b',strand:'eb-drama',level:8,diff:2,q:'A soliloquy is:',opts:['a character speaking their thoughts aloud, alone on stage','a conversation between two characters','the opening scene','a stage direction'],a:0,why:'A soliloquy gives the audience direct access to a character’s mind, unheard by other characters.',tech:'Distinguish soliloquy (alone) from aside (short, others present but not hearing).'},
{id:'eb20',subj:'english-b',strand:'eb-drama',level:9,diff:2,q:'Stage directions matter in a drama question because they:',opts:['reveal action, tone and setting the dialogue does not state','are optional for the reader','only help the director','were added by publishers'],a:0,why:'Stage directions carry meaning — a pause, a turned back, a darkened stage. Ignoring them loses evidence.',tech:'Quote a stage direction as evidence. Most candidates quote only dialogue.'},
{id:'eb21',subj:'english-b',strand:'eb-drama',level:10,diff:3,q:'Conflict in a play may be:',opts:['between characters, within a character, or with society','only between two people','always resolved happily','only in the final act'],a:0,why:'Drama uses external conflict between characters and internal conflict within one, as well as conflict with social forces.',tech:'Name the type of conflict in your opening sentence. It frames the whole essay.'},
{id:'eb22',subj:'english-b',strand:'eb-short',level:7,diff:2,q:'Short stories often end with a moment of realisation, called:',opts:['an epiphany','a prologue','an epilogue','an epigraph'],a:0,why:'An epiphany is a sudden understanding, often the point the whole story has been building to.',tech:'Find the moment something changes in the character’s understanding. That is usually the heart of the story.'},
{id:'eb23',subj:'english-b',strand:'eb-short',level:9,diff:2,q:'Why does a short story usually have few characters?',opts:['the form is compressed, so every character must earn their place','writers run out of names','it is a rule of the genre','readers cannot follow more'],a:0,why:'Compression is the defining feature. With so little space, each character must serve the single effect.',tech:'Ask what each character is FOR. In a short story there is no room for anyone incidental.'},
{id:'eb24',subj:'english-b',strand:'eb-devices',level:8,diff:2,q:'"The classroom was a zoo." This is:',opts:['a metaphor','a simile','hyperbole','personification'],a:0,why:'It states that one thing IS another, with no "like" or "as".',tech:'Explain what quality transfers — here, noise and disorder — rather than just naming the device.'},
{id:'eb25',subj:'english-b',strand:'eb-devices',level:9,diff:2,q:'Symbolism is when:',opts:['an object stands for a larger idea','a character speaks figuratively','two things are compared','sounds are repeated'],a:0,why:'A symbol is a concrete thing carrying an abstract meaning — a broken clock for stalled time, a caged bird for confinement.',tech:'A symbol usually recurs. If an object appears three times, ask what it is carrying.'},
{id:'eb26',subj:'english-b',strand:'eb-devices',level:10,diff:3,q:'Situational irony occurs when:',opts:['what happens is the opposite of what was expected','a character says the opposite of what is meant','the audience knows more than a character','a symbol is repeated'],a:0,why:'Situational irony is in the outcome. Verbal irony is in the words; dramatic irony is in who knows what.',tech:'Three ironies, three locations: words, outcome, knowledge. Say which you mean.'},
{id:'eb27',subj:'english-b',strand:'eb-essay',level:9,diff:2,q:'A literature essay should quote:',opts:['briefly and accurately, embedded in your own sentence','at length to show you know the text','only from the opening chapter','never — paraphrase instead'],a:0,why:'Short embedded quotations prove the point without eating the time and space you need for analysis.',tech:'If a quotation runs past a line, you are copying rather than choosing.'},
{id:'eb28',subj:'english-b',strand:'eb-essay',level:10,diff:3,q:'The commonest reason a literature essay stays in the lower bands is that it:',opts:['retells the story instead of answering the question','is too short','uses no quotations at all','has spelling mistakes'],a:0,why:'Narrative retelling shows you have read the text but not that you can analyse it. Every paragraph must answer the question.',tech:'Start each paragraph with a point that uses the question’s own words. It forces analysis over retelling.'}
);

/* ===== BATCH F — fill every empty strand, top up the remaining subjects ===== */
window.CSEC_QUESTIONS.push(
/* Spanish */
{id:'sp13',subj:'spanish',strand:'sp-listen',level:6,diff:1,q:'In the listening paper, before the recording starts you should:',opts:['read the questions so you know what to listen for','close your eyes and concentrate','write your name only','translate the questions into English'],a:0,why:'You are given time to read the questions. Knowing what is being asked turns listening into searching.',tech:'Underline the key word in each question. You are listening for that one thing, not for everything.'},
{id:'sp14',subj:'spanish',strand:'sp-listen',level:7,diff:2,q:'You hear "Son las tres y media." What time is it?',opts:['3:30','3:00','2:30','3:15'],a:0,why:'"Son las tres" is three o’clock and "y media" adds half an hour.',tech:'Learn y cuarto (quarter past), y media (half past) and menos cuarto (quarter to) as a block.'},
{id:'sp15',subj:'spanish',strand:'sp-listen',level:8,diff:2,q:'If you miss an answer in the listening paper you should:',opts:['leave it and listen for the next one','stop and try to remember','write anything quickly','go back at the end'],a:0,why:'The recording does not wait. Chasing a missed answer costs you the next two.',tech:'Let a missed item go. Each recording is usually played twice — catch it on the second play.'},
{id:'sp16',subj:'spanish',strand:'sp-speak',level:6,diff:1,q:'In the oral examination, if you do not understand you should say:',opts:['¿Puede repetir, por favor?','I don’t understand','nothing at all','Lo siento, adiós'],a:0,why:'Asking for repetition in Spanish keeps you inside the language and loses no marks. Silence scores nothing.',tech:'Learn three repair phrases before the oral. Using them well shows control, not weakness.'},
{id:'sp17',subj:'spanish',strand:'sp-speak',level:8,diff:2,q:'In the picture-description task you should:',opts:['describe what you can see in full sentences','name one object','speak in English about it','list words only'],a:0,why:'Marks come from full sentences with verbs, not from naming nouns.',tech:'Start with hay (there is/are), then say who, where and what they are doing.'},
{id:'sp18',subj:'spanish',strand:'sp-speak',level:9,diff:2,q:'Which is the best answer to "¿Qué hiciste el fin de semana?"',opts:['Fui a la playa con mi familia.','Voy a la playa.','La playa.','Me gusta la playa.'],a:0,why:'The question is in the past, so the answer must be too. "Fui" is the preterite of ir.',tech:'Match the tense of the question. Answering a past question in the present loses marks even when the Spanish is correct.'},
{id:'sp19',subj:'spanish',strand:'sp-write',level:7,diff:2,q:'When writing a letter in Spanish, a suitable informal opening is:',opts:['Querido Juan:','Estimado señor:','Adiós Juan:','Hola señor director:'],a:0,why:'"Querido" is the informal "Dear" used to a friend. "Estimado" is formal.',tech:'Match the opening and closing to the person. Querido goes with Un abrazo; Estimado with Atentamente.'},
{id:'sp20',subj:'spanish',strand:'sp-write',level:8,diff:2,q:'In the Spanish writing paper, going well over the word limit will:',opts:['lose marks — the limit is part of the task','gain marks for effort','be ignored','only matter in the oral'],a:0,why:'The word count is a stated requirement, and examiners apply it.',tech:'Count in tens as you write. Finishing inside the limit beats one more idea outside it.'},
{id:'sp21',subj:'spanish',strand:'sp-gram',level:9,diff:3,q:'Which sentence uses the subjunctive correctly?',opts:['Espero que tengas un buen día.','Espero que tienes un buen día.','Espero que tenías un buen día.','Espero que tendrás un buen día.'],a:0,why:'Expressions of hope, doubt or emotion trigger the subjunctive: tengas, not tienes.',tech:'WEIRDO triggers — wishes, emotion, impersonal, requests, doubt, ojalá — take the subjunctive.'},
/* French */
{id:'fr13',subj:'french',strand:'fr-listen',level:6,diff:1,q:'In the French listening paper, the recording is normally played:',opts:['twice','once','three times','on request'],a:0,why:'Each item is played twice. The first play is for sense, the second for the detail you missed.',tech:'Listen for gist first, then hunt the specific detail on the second play.'},
{id:'fr14',subj:'french',strand:'fr-listen',level:7,diff:2,q:'You hear "Il est huit heures et quart." What time is it?',opts:['8:15','8:45','8:30','7:45'],a:0,why:'"Huit heures" is eight o’clock and "et quart" adds a quarter of an hour.',tech:'et quart = quarter past, et demie = half past, moins le quart = quarter to.'},
{id:'fr15',subj:'french',strand:'fr-listen',level:8,diff:2,q:'Numbers in French listening are a common trap because:',opts:['soixante-dix, quatre-vingts and quatre-vingt-dix are built from other numbers','they are said very fast','they are the same as English','they are never tested'],a:0,why:'70 is sixty-ten, 80 is four-twenties and 90 is four-twenty-ten. Under pressure these are easily misheard.',tech:'Drill 60 to 100 out loud until they are automatic. Prices, ages and dates all depend on them.'},
{id:'fr16',subj:'french',strand:'fr-speak',level:6,diff:1,q:'In the French oral, a good way to ask for repetition is:',opts:['Pouvez-vous répéter, s’il vous plaît ?','What?','Je ne sais pas.','Au revoir.'],a:0,why:'It is polite, in French, and keeps the conversation going. "Je ne sais pas" ends it.',tech:'Never go silent. A polite request in French is always better than a gap.'},
{id:'fr17',subj:'french',strand:'fr-speak',level:8,diff:2,q:'Which is the best answer to "Qu’est-ce que tu as fait hier ?"',opts:['J’ai joué au football avec mes amis.','Je joue au football.','Le football.','J’aime le football.'],a:0,why:'"Hier" means yesterday, so the answer must be in the passé composé.',tech:'Listen for the time word — hier, demain, maintenant — and match your tense to it.'},
{id:'fr18',subj:'french',strand:'fr-speak',level:9,diff:2,q:'To score well in the oral you should give answers that are:',opts:['developed, with a reason or an example','one word','as long as possible regardless of accuracy','memorised word for word'],a:0,why:'A developed answer shows range. One word shows nothing, and a recited speech cannot respond to the question asked.',tech:'Answer, then add "parce que" and a reason. Two sentences instead of one doubles what you can be credited for.'},
/* Biology */
{id:'bi13',subj:'biology',strand:'bi-coord',level:8,diff:2,q:'Which part of the nervous system carries impulses from the sense organs to the brain?',opts:['sensory neurones','motor neurones','the cerebellum','the spinal cord only'],a:0,why:'Sensory neurones carry impulses towards the central nervous system; motor neurones carry them away to muscles and glands.',tech:'Sensory in, motor out. The reflex arc is receptor → sensory → relay → motor → effector.'},
{id:'bi14',subj:'biology',strand:'bi-coord',level:9,diff:2,q:'A reflex action is rapid because it:',opts:['does not have to travel to the conscious brain','uses larger neurones','uses hormones','skips the spinal cord'],a:0,why:'The reflex arc passes through the spinal cord, so the response happens before the brain is consciously aware.',tech:'Draw the reflex arc and label the five parts. Questions often ask for them in order.'},
{id:'bi15',subj:'biology',strand:'bi-coord',level:9,diff:2,q:'Which hormone lowers blood glucose?',opts:['insulin','glucagon','adrenaline','oestrogen'],a:0,why:'Insulin lowers blood glucose by moving it into cells. Glucagon raises it.',tech:'Insulin IN to cells, so glucose goes down. Glucagon does the opposite.'},
{id:'bi16',subj:'biology',strand:'bi-coord',level:10,diff:3,q:'Homeostasis is:',opts:['keeping internal conditions constant','growing at a steady rate','the movement of the skeleton','the production of gametes'],a:0,why:'Homeostasis maintains a steady internal environment — temperature, water balance, glucose — usually by negative feedback.',tech:'Name the variable, the receptor, the effector and the correction. That structure answers most homeostasis questions.'},
{id:'bi17',subj:'biology',strand:'bi-cells',level:8,diff:2,q:'Which structure controls what enters and leaves an animal cell?',opts:['the cell membrane','the nucleus','the cytoplasm','the mitochondrion'],a:0,why:'The partially permeable cell membrane controls movement in and out. The nucleus controls cell activity.',tech:'Match structure to function. "Controls the cell" is the nucleus; "controls entry and exit" is the membrane.'},
{id:'bi18',subj:'biology',strand:'bi-genes',level:10,diff:3,q:'A person with blood group AB inherited:',opts:['one Iᴬ allele and one Iᴮ allele','two Iᴬ alleles','two recessive alleles','one dominant and one recessive allele'],a:0,why:'Iᴬ and Iᴮ are codominant, so both are expressed, producing group AB.',tech:'Codominance means BOTH show. Incomplete dominance would blend them instead.'},
/* History */
{id:'hi13',subj:'history',strand:'hi-society',level:9,diff:2,q:'United States influence in the Caribbean grew after 1898 largely because of:',opts:['its victory in the Spanish-American War','the end of slavery','the Haitian Revolution','the West Indies Federation'],a:0,why:'The 1898 war gave the United States control of Cuba and Puerto Rico and marked the start of its dominance in the region.',tech:'Link 1898, the Panama Canal and the later US bases as one thread of growing influence.'},
{id:'hi14',subj:'history',strand:'hi-society',level:9,diff:2,q:'The Chaguaramas base in Trinidad was leased to the United States in 1941 under:',opts:['the destroyers-for-bases agreement','the Treaty of Chaguaramas','the Federation Act','the Moyne Commission'],a:0,why:'Britain leased Caribbean bases to the United States in exchange for destroyers during the Second World War. The base later became a nationalist grievance.',tech:'Do not confuse the 1941 base with the 1973 Treaty of Chaguaramas that founded CARICOM.'},
{id:'hi15',subj:'history',strand:'hi-society',level:10,diff:3,q:'Large-scale Caribbean migration to Britain after 1948 was driven mainly by:',opts:['labour shortages in post-war Britain','the end of indentureship','the collapse of the sugar industry alone','a British government ban on emigration elsewhere'],a:0,why:'Post-war Britain needed workers and actively recruited from the colonies. The Windrush arrived in 1948.',tech:'Always give push and pull factors together. Unemployment at home pushed; recruitment abroad pulled.'},
{id:'hi16',subj:'history',strand:'hi-society',level:10,diff:2,q:'The Moyne Commission was appointed to investigate:',opts:['the causes of the 1930s labour disturbances','the abolition of slavery','the failure of the Federation','the Haitian Revolution'],a:0,why:'It was appointed after the labour unrest of 1937-38 and its report exposed severe social conditions across the British Caribbean.',tech:'Link the 1930s riots, the Moyne Commission and the rise of trade unions and universal adult suffrage as one chain.'},
{id:'hi17',subj:'history',strand:'hi-slavery',level:8,diff:2,q:'The Triangular Trade carried which cargo on the leg from Europe to Africa?',opts:['manufactured goods such as cloth and guns','enslaved Africans','sugar and rum','indentured labourers'],a:0,why:'Europe to Africa carried manufactured goods; Africa to the Americas carried enslaved people; the Americas back to Europe carried sugar, rum and cotton.',tech:'Know all three legs and their cargo. Questions name one leg and ask for the cargo.'},
{id:'hi18',subj:'history',strand:'hi-resist',level:8,diff:2,q:'Maroon communities were:',opts:['settlements of self-liberated Africans who resisted recapture','plantations owned by free people of colour','British military outposts','trading posts on the African coast'],a:0,why:'Maroons escaped the plantations and formed independent communities, most famously in Jamaica and Suriname.',tech:'Distinguish day-to-day resistance, marronage and open revolt. Questions often ask for examples of each.'},
/* Visual Arts */
{id:'va13',subj:'visual-arts',strand:'va-3d',level:7,diff:1,q:'Which is a hand-building technique in ceramics?',opts:['coiling','throwing on a wheel','firing','glazing'],a:0,why:'Pinch, coil and slab are the three hand-building methods. Throwing uses a wheel; firing and glazing come afterwards.',tech:'Learn the three hand-building methods and one example of each.'},
{id:'va14',subj:'visual-arts',strand:'va-3d',level:8,diff:2,q:'In sculpture, carving is described as a process of:',opts:['taking material away','adding material on','pouring into a mould','joining flat sheets'],a:0,why:'Carving is subtractive — material is removed. Modelling with clay is additive.',tech:'Subtractive takes away, additive builds up, casting pours into a mould. Three words, three processes.'},
{id:'va15',subj:'visual-arts',strand:'va-3d',level:9,diff:2,q:'Clay must be wedged before use in order to:',opts:['remove air bubbles that would crack it in the kiln','make it a brighter colour','make it heavier','speed up drying'],a:0,why:'Trapped air expands in the kiln and can shatter the piece. Wedging works the air out.',tech:'Know the stages: wedge, build, dry to leather-hard, bisque fire, glaze, glaze fire.'},
{id:'va16',subj:'visual-arts',strand:'va-3d',level:10,diff:2,q:'A form differs from a shape because a form:',opts:['is three-dimensional','is always larger','is always coloured','has straight edges'],a:0,why:'Shape is flat and has two dimensions; form has three and occupies space.',tech:'Shape is 2D, form is 3D. Use the right word in a critique — examiners notice.'},
{id:'va17',subj:'visual-arts',strand:'va-portfolio',level:9,diff:2,q:'A sketchbook in the CSEC Visual Arts portfolio should show:',opts:['the development of an idea, including work you rejected','only your best finished pieces','copied images','written notes alone'],a:0,why:'The portfolio is assessed on development. Rejected experiments prove you explored rather than settled for the first idea.',tech:'Never tear out a page you dislike. The journey is what is being marked.'},
{id:'va18',subj:'visual-arts',strand:'va-portfolio',level:10,diff:2,q:'Working to a theme across your portfolio matters because it:',opts:['shows sustained investigation rather than unrelated pieces','makes the work quicker','saves materials','is required by the school only'],a:0,why:'A coherent body of work demonstrates depth. A folder of unconnected pieces cannot show development.',tech:'Choose a theme with visual possibilities and a personal connection. You will live with it for two years.'},
/* Physical Education */
{id:'pe13',subj:'physical-education',strand:'pe-games',level:6,diff:1,q:'In football, a throw-in is awarded when the ball:',opts:['crosses the touchline','crosses the goal line','hits the crossbar','is handled by the goalkeeper'],a:0,why:'Crossing the touchline gives a throw-in. Crossing the goal line gives a corner or a goal kick.',tech:'For your chosen sport, learn the restart for every way the ball leaves play.'},
{id:'pe14',subj:'physical-education',strand:'pe-games',level:7,diff:2,q:'In cricket, an over consists of how many legal deliveries?',opts:['6','4','8','5'],a:0,why:'An over is six legal deliveries. Wides and no-balls do not count and must be bowled again.',tech:'Know the basic scoring and officiating rules of the sport you offer. They are examinable.'},
{id:'pe15',subj:'physical-education',strand:'pe-games',level:8,diff:2,q:'The main role of an official in a game is to:',opts:['apply the rules fairly and keep players safe','support the home team','decide the result in advance','coach the players'],a:0,why:'Officials enforce the laws impartially and have a duty of care for player safety.',tech:'Questions on officiating usually want the role AND an example of a decision. Give both.'},
{id:'pe16',subj:'physical-education',strand:'pe-games',level:9,diff:2,q:'A tactic differs from a skill because a tactic is:',opts:['a plan for outplaying an opponent','a physical movement','a rule of the game','a fitness component'],a:0,why:'Skills are the movements — passing, shooting. Tactics are how you use them against a particular opponent.',tech:'Give a named tactic from your sport and say when you would use it.'},
{id:'pe17',subj:'physical-education',strand:'pe-anatomy',level:9,diff:2,q:'Which type of joint is the knee?',opts:['hinge','ball and socket','pivot','gliding'],a:0,why:'The knee is a hinge joint, moving mainly in one plane. The hip and shoulder are ball and socket.',tech:'Match joint type to movement: hinge bends one way, ball and socket rotates freely.'},
{id:'pe18',subj:'physical-education',strand:'pe-fitness',level:9,diff:2,q:'Progressive overload means:',opts:['gradually increasing the demand so the body keeps adapting','training until exhausted every session','always using the heaviest weight','training only once a week'],a:0,why:'The body adapts to the demand placed on it. If the demand never rises, improvement stops.',tech:'Overload, progression, specificity and reversibility are the four training principles. Learn all four.'},
/* Information Technology */
{id:'it13',subj:'information-technology',strand:'it-program',level:9,diff:2,q:'In programming, a loop is used to:',opts:['repeat a block of instructions','make a decision','store a value','end the program'],a:0,why:'Loops repeat. Selection (if) makes decisions and variables store values.',tech:'The three constructs are sequence, selection and iteration. Every program is built from them.'},
{id:'it14',subj:'information-technology',strand:'it-program',level:9,diff:2,q:'A variable is best described as:',opts:['a named storage location whose value can change','a fixed number','a type of loop','an error message'],a:0,why:'A variable holds a value that can change while the program runs. A constant cannot.',tech:'Declare variables with meaningful names and the right data type. Both are examinable.'},
{id:'it15',subj:'information-technology',strand:'it-program',level:10,diff:3,q:'What does this output?  x ← 0 ; FOR i ← 1 TO 4 DO x ← x + i ; ENDFOR ; PRINT x',opts:['10','4','24','0'],a:0,why:'It adds 1 + 2 + 3 + 4 = 10.',tech:'Trace it with a table. Write each value of i and the running total on its own row.'},
{id:'it16',subj:'information-technology',strand:'it-program',level:10,diff:3,q:'An array is useful because it:',opts:['stores many related values under one name, reached by index','runs faster than a loop','prevents all errors','replaces the operating system'],a:0,why:'One name and an index gives you a list you can loop through, instead of forty separate variables.',tech:'Note whether the array starts at 0 or 1 in the language you are using. Off-by-one errors start there.'},
{id:'it17',subj:'information-technology',strand:'it-impact',level:8,diff:2,q:'Which is the best defence against losing work to a hardware failure?',opts:['keeping regular backups in a separate place','using a strong password','installing antivirus software','encrypting the file'],a:0,why:'Passwords, antivirus and encryption protect against access and infection. Only a backup protects against the disk dying.',tech:'Match each threat to its countermeasure. Questions test whether you can pair them correctly.'},
{id:'it18',subj:'information-technology',strand:'it-data',level:9,diff:2,q:'Which network covers the smallest geographical area?',opts:['LAN','WAN','MAN','the internet'],a:0,why:'A local area network covers one building or site. A WAN spans cities or countries.',tech:'LAN small, MAN a city, WAN wide. Size is the distinguishing feature.'},
/* Physics, Chemistry, Geography, Social Studies top-ups */
{id:'ph13',subj:'physics',strand:'ph-waves',level:9,diff:2,q:'When light passes from air into glass it slows down and bends. This is:',opts:['refraction','reflection','diffraction','dispersion'],a:0,why:'Refraction is the change of direction caused by a change of speed between media.',tech:'Toward the normal when entering a denser medium; away from it when leaving.'},
{id:'ph14',subj:'physics',strand:'ph-elec',level:9,diff:2,q:'In a series circuit, the current is:',opts:['the same at every point','greatest near the battery','shared between components','zero in the middle'],a:0,why:'There is only one path, so the same current flows everywhere. It is the voltage that is shared.',tech:'Series: current same, voltage shared. Parallel: voltage same, current shared.'},
{id:'ph15',subj:'physics',strand:'ph-thermal',level:9,diff:2,q:'Heat transfer through a vacuum can only occur by:',opts:['radiation','conduction','convection','evaporation'],a:0,why:'Conduction and convection need particles. Radiation is electromagnetic waves and needs no medium, which is how the Sun heats us.',tech:'If a question mentions a vacuum or space, the answer is radiation.'},
{id:'ph16',subj:'physics',strand:'ph-mech',level:9,diff:3,q:'A 2 kg object is lifted 3 m. Taking g = 10 N/kg, how much potential energy does it gain?',opts:['60 J','6 J','20 J','30 J'],a:0,why:'PE = mgh = 2 × 10 × 3 = 60 J.',tech:'Energy is always in joules. If your unit is not J, you have used the wrong formula.'},
{id:'ch13',subj:'chemistry',strand:'ch-atomic',level:9,diff:2,q:'Elements in the same GROUP of the periodic table have the same:',opts:['number of outer-shell electrons','number of neutrons','atomic mass','number of shells'],a:0,why:'Group number gives the outer electrons, which is why a group behaves similarly. Period number gives the number of shells.',tech:'Group = outer electrons = chemistry. Period = shells. That sentence answers most periodic-table questions.'},
{id:'ch14',subj:'chemistry',strand:'ch-acids',level:9,diff:2,q:'Which salt is produced when hydrochloric acid reacts with sodium hydroxide?',opts:['sodium chloride','sodium sulphate','sodium nitrate','sodium carbonate'],a:0,why:'The acid gives the second part of the name and the base gives the first: hydrochloric → chloride, sodium hydroxide → sodium.',tech:'Hydrochloric gives chlorides, sulphuric gives sulphates, nitric gives nitrates.'},
{id:'ch15',subj:'chemistry',strand:'ch-redox',level:9,diff:3,q:'In terms of electrons, oxidation is:',opts:['loss of electrons','gain of electrons','loss of protons','gain of oxygen only'],a:0,why:'Oxidation is loss, reduction is gain — of electrons. Gaining oxygen is only one example of it.',tech:'OIL RIG: Oxidation Is Loss, Reduction Is Gain.'},
{id:'ch16',subj:'chemistry',strand:'ch-organic',level:10,diff:2,q:'Which test distinguishes an alkene from an alkane?',opts:['it decolourises bromine water','it turns limewater milky','it pops with a lit splint','it turns litmus red'],a:0,why:'The double bond in an alkene reacts with bromine water, removing its colour. Alkanes leave it orange.',tech:'Learn one distinguishing test per pair. This is the one examined most often.'},
{id:'ge13',subj:'geography',strand:'ge-weather',level:9,diff:2,q:'Which instrument measures atmospheric pressure?',opts:['barometer','thermometer','anemometer','rain gauge'],a:0,why:'Barometer for pressure, thermometer for temperature, anemometer for wind speed, rain gauge for rainfall.',tech:'Pair each instrument with its element and its unit. All three can be asked for.'},
{id:'ge14',subj:'geography',strand:'ge-pop',level:9,diff:2,q:'A population pyramid with a very wide base indicates:',opts:['a high birth rate','an ageing population','high emigration','a declining population'],a:0,why:'The base shows the youngest age groups, so a wide base means many recent births.',tech:'Wide base, high birth rate. Narrow base with a bulge higher up, an ageing population.'},
{id:'ge15',subj:'geography',strand:'ge-tectonic',level:9,diff:2,q:'Which landform is produced by river DEPOSITION?',opts:['a delta','a waterfall','a gorge','a V-shaped valley'],a:0,why:'Deltas form where a river drops its load on entering a sea or lake. The other three are erosional.',tech:'Sort every landform into erosion or deposition before the examination. Questions name one or the other.'},
{id:'ge16',subj:'geography',strand:'ge-hazard',level:10,diff:2,q:'Which is a PREPAREDNESS measure for a hurricane?',opts:['stocking supplies and agreeing a family plan before the season','rebuilding after the storm','issuing insurance payouts','clearing debris from roads'],a:0,why:'Preparedness happens before, in anticipation. The other three are response and recovery.',tech:'Four stages: mitigation, preparedness, response, recovery. Say which one you are describing.'},
{id:'ss13',subj:'social-studies',strand:'ss-dev',level:9,diff:2,q:'Which indicator is used to measure a country’s standard of living?',opts:['Gross Domestic Product per capita','total population','land area','number of political parties'],a:0,why:'GDP per capita, life expectancy and literacy are standard development indicators. Population and area are not.',tech:'Name two or three indicators and say what each reveals. One indicator alone gives an incomplete picture.'},
{id:'ss14',subj:'social-studies',strand:'ss-family',level:8,diff:2,q:'Which is a function of the family?',opts:['socialising children into the norms of society','setting national laws','providing public transport','issuing passports'],a:0,why:'Families socialise, provide emotional and economic support and reproduce. The others are functions of the state.',tech:'Learn the functions of each institution separately — family, school, religion, government.'},
{id:'ss15',subj:'social-studies',strand:'ss-region',level:10,diff:2,q:'Which is a CHALLENGE to Caribbean regional integration?',opts:['competition between member states producing similar goods','a shared history','a common language in most states','geographic closeness'],a:0,why:'Producing the same goods makes states competitors rather than trading partners. The other three assist integration.',tech:'Prepare three benefits and three challenges with an example each. Balance earns the higher band.'},
{id:'ss16',subj:'social-studies',strand:'ss-issues',level:9,diff:2,q:'Which is the most effective long-term response to youth unemployment?',opts:['skills training matched to available jobs','increasing police patrols','reducing the school leaving age','ignoring the problem'],a:0,why:'Training that matches real vacancies addresses the cause. The others treat symptoms or do nothing.',tech:'Distinguish causes, effects and solutions. Questions ask for one and reward keeping them apart.'},
/* Primary Science & Social Studies top-ups */
{id:'ps11',subj:'p-science',strand:'ps-living',level:4,diff:2,q:'Which group do animals with a backbone belong to?',opts:['vertebrates','invertebrates','insects','plants'],a:0,why:'Vertebrates have a backbone — fish, amphibians, reptiles, birds and mammals. Invertebrates do not.',tech:'Learn the five vertebrate groups and one example of each.'},
{id:'ps12',subj:'p-science',strand:'ps-living',level:5,diff:2,q:'In a food chain, an animal that eats only plants is called a:',opts:['herbivore','carnivore','omnivore','producer'],a:0,why:'Herbivores eat plants, carnivores eat meat, omnivores eat both, and producers make their own food.',tech:'The arrows in a food chain show where the energy goes, not who eats whom.'},
{id:'ps13',subj:'p-science',strand:'ps-body',level:4,diff:2,q:'Which organ takes oxygen from the air into the blood?',opts:['the lungs','the heart','the liver','the kidney'],a:0,why:'The lungs take in oxygen and release carbon dioxide. The heart then pumps the oxygenated blood around the body.',tech:'Match organ to job. Most primary science questions are exactly that pairing.'},
{id:'ps14',subj:'p-science',strand:'ps-matter',level:5,diff:2,q:'Which change can be REVERSED?',opts:['melting ice','burning paper','cooking an egg','rusting iron'],a:0,why:'Melting is a physical change and can be reversed by freezing. The other three are chemical and cannot be undone.',tech:'Physical changes can usually be reversed. Chemical changes make a new substance.'},
{id:'ps15',subj:'p-science',strand:'ps-energy',level:5,diff:2,q:'Which is a source of renewable energy?',opts:['sunlight','petrol','coal','natural gas'],a:0,why:'Sunlight will not run out. The other three are fossil fuels and are finite.',tech:'Renewable means it can be replaced. Sun, wind and water are the main three.'},
{id:'pss11',subj:'p-social-studies',strand:'pss-comm',level:5,diff:2,q:'Taxes are collected by the government mainly to:',opts:['pay for services everyone uses','make the government richer','pay only civil servants','reduce the population'],a:0,why:'Taxes fund schools, hospitals, roads, water and the police — services shared by everybody.',tech:'Give an example of a service near you when answering. It shows real understanding.'},
{id:'pss12',subj:'p-social-studies',strand:'pss-geog',level:5,diff:2,q:'Which is the capital city of Trinidad and Tobago?',opts:['Port of Spain','San Fernando','Scarborough','Chaguanas'],a:0,why:'Port of Spain is the capital. Scarborough is the main town of Tobago.',tech:'Know the capital, the main towns and roughly where they are on the map.'},
{id:'pss13',subj:'p-social-studies',strand:'pss-history',level:5,diff:2,q:'Trinidad and Tobago became independent in:',opts:['1962','1976','1834','1845'],a:0,why:'Independence was 31 August 1962. The country became a Republic in 1976.',tech:'Independence 1962, Republic 1976. Two different events, two different dates.'},
{id:'pss14',subj:'p-social-studies',strand:'pss-citizen',level:4,diff:2,q:'Which shows respect for other people’s property?',opts:['asking before you borrow something','taking what you need','using it and saying nothing','hiding it afterwards'],a:0,why:'Asking first recognises that the thing belongs to somebody else.',tech:'Citizenship questions reward a concrete example, not a general statement.'},
{id:'pss15',subj:'p-social-studies',strand:'pss-self',level:2,diff:1,q:'School rules exist mainly to:',opts:['keep everyone safe and able to learn','punish children','make teachers’ work easier','fill up the notice board'],a:0,why:'Rules protect people and make learning possible for everyone in the room.',tech:'When asked why a rule exists, say who it protects.'}
);

/* ===== BATCH G — depth pass: sciences ===== */
window.CSEC_QUESTIONS.push(
/* Biology */
{id:'bi19',subj:'biology',strand:'bi-health',level:8,diff:2,q:'Which disease is caused by a vector?',opts:['dengue','diabetes','sickle cell anaemia','scurvy'],a:0,why:'Dengue is carried by the Aedes aegypti mosquito. Diabetes and sickle cell are non-communicable and scurvy is a deficiency disease.',tech:'Sort diseases by cause: pathogenic, deficiency, hereditary, physiological. The category decides the control measure.'},
{id:'bi20',subj:'biology',strand:'bi-health',level:9,diff:2,q:'The most effective way to control the mosquito that spreads dengue is to:',opts:['remove standing water where it breeds','spray adults only','treat patients quickly','close windows at night'],a:0,why:'Breaking the life cycle at the larval stage removes the next generation. Spraying kills only the adults present now.',tech:'Control measures that break the life cycle beat those that treat symptoms. Say which stage you are attacking.'},
{id:'bi21',subj:'biology',strand:'bi-health',level:9,diff:2,q:'A vaccine works by:',opts:['causing the body to make antibodies and memory cells','killing pathogens already in the blood','replacing damaged tissue','supplying antibodies directly'],a:0,why:'A vaccine gives active immunity: the body makes its own antibodies and keeps memory cells. Supplying antibodies directly is passive immunity.',tech:'Active means you make them and it lasts. Passive means you are given them and it does not.'},
{id:'bi22',subj:'biology',strand:'bi-health',level:10,diff:3,q:'Which is a NON-communicable disease linked to diet?',opts:['type 2 diabetes','influenza','tuberculosis','cholera'],a:0,why:'Type 2 diabetes is strongly linked to diet and obesity and cannot be passed from person to person. The other three are infectious.',tech:'Non-communicable diseases are a growing Caribbean examination topic. Know two, with a risk factor and a prevention for each.'},
{id:'bi23',subj:'biology',strand:'bi-env',level:6,diff:1,q:'In a food chain, green plants are called:',opts:['producers','consumers','decomposers','predators'],a:0,why:'Producers make their own food by photosynthesis. Everything else in the chain depends on them.',tech:'Every food chain starts with a producer. If yours does not, you have drawn it wrong.'},
{id:'bi24',subj:'biology',strand:'bi-env',level:8,diff:2,q:'Decomposers are important in an ecosystem because they:',opts:['return nutrients to the soil','produce oxygen','eat the top predators','provide shelter'],a:0,why:'Bacteria and fungi break down dead material, releasing nutrients that plants take up again.',tech:'Nutrients cycle; energy flows one way and is lost. That distinction is examined often.'},
{id:'bi25',subj:'biology',strand:'bi-env',level:9,diff:2,q:'Energy is lost between trophic levels mainly through:',opts:['respiration, movement and heat','photosynthesis','decomposition alone','reproduction'],a:0,why:'Only about ten per cent of energy passes to the next level; the rest is used in respiration and lost as heat.',tech:'This is why food chains are short. Use it to explain why there are few top predators.'},
{id:'bi26',subj:'biology',strand:'bi-env',level:10,diff:3,q:'Eutrophication of a river is usually caused by:',opts:['fertiliser run-off causing algal growth that removes oxygen','an increase in fish numbers','a fall in water temperature','too much rainfall alone'],a:0,why:'Nitrates and phosphates feed algae; when the algae die, decomposers use up the dissolved oxygen and fish suffocate.',tech:'Give the chain in order: nutrients, algal bloom, light blocked, plants die, decomposers multiply, oxygen falls, fish die.'},
{id:'bi27',subj:'biology',strand:'bi-repro',level:7,diff:1,q:'Which is an example of ASEXUAL reproduction?',opts:['a potato growing from a tuber','a flower producing seeds','fish releasing eggs and sperm','a bird laying fertilised eggs'],a:0,why:'Asexual reproduction involves one parent and no gametes, so the offspring are genetically identical.',tech:'One parent, identical offspring, no gametes. Two parents, varied offspring, gametes fuse.'},
{id:'bi28',subj:'biology',strand:'bi-repro',level:8,diff:2,q:'In a flowering plant, pollination is:',opts:['the transfer of pollen from anther to stigma','the fusion of male and female nuclei','the growth of the seed','the spreading of seeds'],a:0,why:'Pollination is transfer; fertilisation is fusion. Seed dispersal comes later.',tech:'Pollination, fertilisation, seed formation, dispersal, germination — five stages, five different words.'},
{id:'bi29',subj:'biology',strand:'bi-repro',level:9,diff:2,q:'Fertilisation in humans normally occurs in the:',opts:['oviduct','uterus','ovary','vagina'],a:0,why:'The egg is fertilised in the oviduct (fallopian tube) and the embryo then implants in the uterus.',tech:'Label the diagram and note where each event happens. Questions ask for the site, not the organ name alone.'},
{id:'bi30',subj:'biology',strand:'bi-repro',level:10,diff:2,q:'The placenta allows:',opts:['exchange of nutrients and wastes without the two blood supplies mixing','the mother’s blood to flow into the fetus','the fetus to breathe air','the fetus to digest solid food'],a:0,why:'Diffusion occurs across the placenta, but the two circulations stay separate — which is why blood groups may differ.',tech:'State what crosses and what does not. Oxygen, glucose and antibodies cross; blood cells and most bacteria do not.'},
{id:'bi31',subj:'biology',strand:'bi-genes',level:9,diff:2,q:'A gene is:',opts:['a length of DNA that codes for a characteristic','a whole chromosome','a type of protein','a sex cell'],a:0,why:'Genes are sections of DNA on chromosomes. Each codes for a protein and so for a characteristic.',tech:'Nested order: nucleus contains chromosomes, which contain DNA, which carries genes. Keep them straight.'},
{id:'bi32',subj:'biology',strand:'bi-genes',level:10,diff:3,q:'Two parents both carrying Tt are crossed. What fraction of offspring are expected to show the recessive characteristic?',opts:['1 in 4','1 in 2','3 in 4','none'],a:0,why:'Tt × Tt gives TT, Tt, Tt, tt. Only tt shows the recessive trait — one in four.',tech:'Always draw the Punnett square. Two marks for the square, one for the ratio.'},
{id:'bi33',subj:'biology',strand:'bi-genes',level:10,diff:2,q:'Variation caused by the environment rather than genes includes:',opts:['a scar from an injury','blood group','eye colour','sex'],a:0,why:'A scar is acquired and cannot be inherited. The other three are determined genetically.',tech:'Ask whether it was present in the gametes. If not, it is environmental.'},
{id:'bi34',subj:'biology',strand:'bi-resp',level:8,diff:2,q:'The word equation for aerobic respiration is:',opts:['glucose + oxygen → carbon dioxide + water + energy','carbon dioxide + water → glucose + oxygen','glucose → lactic acid + energy','oxygen + water → glucose'],a:0,why:'Aerobic respiration releases energy from glucose using oxygen. The second equation is photosynthesis.',tech:'Learn both equations and check the direction before you write. They are reverses of each other.'},
{id:'bi35',subj:'biology',strand:'bi-resp',level:9,diff:2,q:'Anaerobic respiration in human muscle produces:',opts:['lactic acid','ethanol and carbon dioxide','carbon dioxide and water','oxygen'],a:0,why:'Human muscle produces lactic acid; yeast produces ethanol and carbon dioxide.',tech:'Two anaerobic pathways, two products. State which organism you mean.'},
{id:'bi36',subj:'biology',strand:'bi-resp',level:9,diff:2,q:'Which organ removes urea from the blood?',opts:['the kidney','the liver','the lung','the skin'],a:0,why:'The liver makes urea from excess amino acids; the kidney removes it from the blood to form urine.',tech:'Liver makes it, kidney excretes it. Questions test whether you can separate the two.'},
{id:'bi37',subj:'biology',strand:'bi-cells',level:9,diff:2,q:'Osmosis is the movement of:',opts:['water through a partially permeable membrane from high to low water potential','any substance from high to low concentration','dissolved salts against a gradient','water using energy from respiration'],a:0,why:'Osmosis is specifically water, through a partially permeable membrane, and needs no energy. Active transport uses energy and moves against the gradient.',tech:'Three processes, three definitions: diffusion, osmosis, active transport. Say which one you are describing.'},
{id:'bi38',subj:'biology',strand:'bi-cells',level:9,diff:3,q:'A plant cell placed in a strong sugar solution will:',opts:['lose water and become plasmolysed','burst','become turgid','stay unchanged'],a:0,why:'The solution outside has lower water potential, so water leaves and the membrane pulls away from the wall. The wall stops the cell bursting in the opposite case.',tech:'Compare water potential inside and outside, then say which way water moves. Work in that order every time.'},
/* Chemistry */
{id:'ch17',subj:'chemistry',strand:'ch-inorg',level:9,diff:2,q:'Which gas turns limewater milky?',opts:['carbon dioxide','oxygen','hydrogen','nitrogen'],a:0,why:'Carbon dioxide forms insoluble calcium carbonate with limewater, making it cloudy.',tech:'Learn the four gas tests: CO₂ limewater, O₂ glowing splint, H₂ squeaky pop, NH₃ damp red litmus turns blue.'},
{id:'ch18',subj:'chemistry',strand:'ch-inorg',level:9,diff:2,q:'The main ore from which aluminium is extracted is:',opts:['bauxite','haematite','limestone','galena'],a:0,why:'Bauxite is the aluminium ore — mined in Jamaica and Guyana. Haematite is iron ore.',tech:'Caribbean examples carry marks. Bauxite in Jamaica and Guyana, petroleum and natural gas in Trinidad.'},
{id:'ch19',subj:'chemistry',strand:'ch-inorg',level:10,diff:3,q:'Aluminium is extracted by electrolysis rather than reduction with carbon because:',opts:['it is too reactive to be displaced by carbon','it is too expensive to heat','its ore contains no oxygen','it melts at too low a temperature'],a:0,why:'Aluminium sits above carbon in the reactivity series, so carbon cannot reduce it. Electrolysis is required.',tech:'The reactivity series decides the extraction method. Above carbon means electrolysis; below means reduction.'},
{id:'ch20',subj:'chemistry',strand:'ch-inorg',level:10,diff:2,q:'Trinidad and Tobago’s ammonia industry uses which process?',opts:['the Haber process','the Contact process','electrolysis of brine','fractional distillation'],a:0,why:'The Haber process combines nitrogen and hydrogen to make ammonia — the basis of Trinidad’s petrochemical sector. The Contact process makes sulphuric acid.',tech:'For each named process, learn the raw materials, conditions and product. All three are examinable.'},
{id:'ch21',subj:'chemistry',strand:'ch-organic',level:9,diff:2,q:'The general formula of the alkanes is:',opts:['CnH2n+2','CnH2n','CnH2n-2','CnHn'],a:0,why:'Alkanes are saturated: CnH2n+2. Alkenes with one double bond are CnH2n.',tech:'Check your formula against the general one before answering. It catches most slips.'},
{id:'ch22',subj:'chemistry',strand:'ch-organic',level:10,diff:2,q:'Fermentation of glucose by yeast produces:',opts:['ethanol and carbon dioxide','methane and water','ethanoic acid only','propanol'],a:0,why:'Yeast respires anaerobically, converting glucose to ethanol and carbon dioxide.',tech:'Know the conditions too — about 37 °C, no air, yeast present. Conditions carry marks.'},
{id:'ch23',subj:'chemistry',strand:'ch-organic',level:10,diff:3,q:'A homologous series is a family of compounds that:',opts:['share a general formula and differ by CH₂','have the same number of carbons','are all gases','all contain oxygen'],a:0,why:'Members differ by one CH₂ unit, share a general formula and show a gradual change in physical properties.',tech:'Three features of a homologous series: same general formula, differ by CH₂, similar chemical properties.'},
{id:'ch24',subj:'chemistry',strand:'ch-redox',level:9,diff:2,q:'During electrolysis, positive ions move to the:',opts:['cathode','anode','electrolyte','power supply'],a:0,why:'Positive ions (cations) move to the negative cathode; negative ions move to the positive anode.',tech:'Cations to the cathode. The names match — use that to remember.'},
{id:'ch25',subj:'chemistry',strand:'ch-redox',level:10,diff:3,q:'In the reaction Zn + CuSO₄ → ZnSO₄ + Cu, zinc is:',opts:['oxidised because it loses electrons','reduced because it gains electrons','unchanged','acting as the acid'],a:0,why:'Zinc goes from 0 to +2, losing two electrons — oxidation. Copper ions gain them and are reduced.',tech:'Write the oxidation numbers above each element first. The change tells you which was oxidised.'},
{id:'ch26',subj:'chemistry',strand:'ch-mole',level:9,diff:2,q:'How many moles are in 36 g of water (Mr = 18)?',opts:['2 mol','0.5 mol','18 mol','36 mol'],a:0,why:'Moles = mass ÷ Mr = 36 ÷ 18 = 2.',tech:'Write the triangle: mass on top, moles and Mr below. Cover what you want.'},
{id:'ch27',subj:'chemistry',strand:'ch-mole',level:10,diff:3,q:'What volume does 0.5 mol of a gas occupy at room temperature and pressure (24 dm³ per mole)?',opts:['12 dm³','24 dm³','48 dm³','0.5 dm³'],a:0,why:'Volume = moles × molar volume = 0.5 × 24 = 12 dm³.',tech:'Check the molar volume given in the question — 22.4 dm³ at s.t.p., 24 dm³ at r.t.p.'},
{id:'ch28',subj:'chemistry',strand:'ch-mole',level:10,diff:3,q:'The concentration of a solution containing 0.2 mol in 500 cm³ is:',opts:['0.4 mol/dm³','0.1 mol/dm³','0.2 mol/dm³','2 mol/dm³'],a:0,why:'500 cm³ is 0.5 dm³, so 0.2 ÷ 0.5 = 0.4 mol/dm³.',tech:'Convert cm³ to dm³ by dividing by 1000 before you start. Forgetting it is the commonest error here.'},
{id:'ch29',subj:'chemistry',strand:'ch-acids',level:8,diff:2,q:'A solution with pH 2 is:',opts:['strongly acidic','weakly acidic','neutral','alkaline'],a:0,why:'Below 7 is acidic and the further from 7, the stronger. pH 2 is strongly acidic.',tech:'Know the colours of universal indicator across the scale. Questions supply a colour and want the pH.'},
{id:'ch30',subj:'chemistry',strand:'ch-acids',level:9,diff:2,q:'Which reaction produces a salt, water and carbon dioxide?',opts:['acid + carbonate','acid + base','acid + metal','base + water'],a:0,why:'Only carbonates release carbon dioxide. Acid with a metal gives salt and hydrogen; with a base, salt and water only.',tech:'Three acid reactions, three sets of products. Learn them as a block and the equations follow.'},
{id:'ch31',subj:'chemistry',strand:'ch-atomic',level:8,diff:2,q:'An atom with 11 protons and 12 neutrons has a mass number of:',opts:['23','11','12','1'],a:0,why:'Mass number is protons plus neutrons: 11 + 12 = 23.',tech:'Atomic number is protons alone. Mass number is protons plus neutrons. Neutrons are the difference.'},
{id:'ch32',subj:'chemistry',strand:'ch-atomic',level:9,diff:3,q:'An ionic bond is formed when:',opts:['electrons are transferred from a metal to a non-metal','electrons are shared between non-metals','protons are exchanged','atoms collide without change'],a:0,why:'Transfer produces charged ions that attract each other. Sharing produces a covalent bond.',tech:'Metal plus non-metal means ionic. Non-metal plus non-metal means covalent. Check the elements first.'},
{id:'ch33',subj:'chemistry',strand:'ch-matter',level:8,diff:2,q:'Which method separates a solid dissolved in a liquid, keeping the liquid?',opts:['distillation','filtration','evaporation','decanting'],a:0,why:'Distillation collects the condensed liquid. Evaporation drives it off and keeps the solid.',tech:'Ask which part you are told to keep. That decides between evaporation and distillation.'},
{id:'ch34',subj:'chemistry',strand:'ch-matter',level:9,diff:2,q:'Chromatography separates mixtures according to differences in:',opts:['solubility in the solvent and attraction to the paper','boiling point','particle size only','density'],a:0,why:'Components that dissolve more readily and are less attracted to the paper travel further, so they separate.',tech:'Draw the start line in pencil, not ink — ink would separate too. That detail is often a mark.'},
/* Physics */
{id:'ph17',subj:'physics',strand:'ph-measure',level:6,diff:1,q:'The SI unit of length is the:',opts:['metre','centimetre','kilogram','second'],a:0,why:'The metre is the SI base unit of length. The centimetre is a submultiple of it.',tech:'Learn the seven base units. Every other unit is built from them.'},
{id:'ph18',subj:'physics',strand:'ph-measure',level:7,diff:2,q:'Which instrument measures the diameter of a wire most precisely?',opts:['a micrometer screw gauge','a metre rule','a measuring cylinder','a stopwatch'],a:0,why:'A micrometer reads to 0.01 mm. A metre rule reads only to 1 mm.',tech:'Match the instrument to the size and precision required. Choosing it is itself an examinable skill.'},
{id:'ph19',subj:'physics',strand:'ph-measure',level:8,diff:2,q:'Which is a DERIVED quantity?',opts:['speed','mass','time','length'],a:0,why:'Speed is length divided by time, so it is derived. The other three are base quantities.',tech:'If the unit contains a division or a power, it is derived.'},
{id:'ph20',subj:'physics',strand:'ph-measure',level:9,diff:3,q:'Reading a scale from an angle causes:',opts:['a parallax error','a zero error','a random error only','no error'],a:0,why:'Parallax error comes from the line of sight. Zero error is an instrument fault present before you start.',tech:'Read at eye level, square to the scale. Check for a zero error before the first reading.'},
{id:'ph21',subj:'physics',strand:'ph-atom',level:9,diff:2,q:'Which type of radiation is stopped by a sheet of paper?',opts:['alpha','beta','gamma','X-rays'],a:0,why:'Alpha is the least penetrating: paper stops it. Beta needs aluminium, gamma needs thick lead.',tech:'Paper, aluminium, lead — in order of penetrating power. Ionising power runs the other way.'},
{id:'ph22',subj:'physics',strand:'ph-atom',level:9,diff:2,q:'The half-life of a radioactive isotope is the time for:',opts:['half the undecayed nuclei to decay','the substance to disappear','the mass to double','the radiation to stop'],a:0,why:'Half-life is constant for a given isotope and describes the nuclei remaining, not the total mass.',tech:'Halve, halve, halve. Count how many half-lives have passed and halve that many times.'},
{id:'ph23',subj:'physics',strand:'ph-atom',level:10,diff:3,q:'A sample has a half-life of 5 days. What fraction remains after 15 days?',opts:['one eighth','one third','one half','one fifteenth'],a:0,why:'15 days is three half-lives: 1 → 1/2 → 1/4 → 1/8.',tech:'Divide the time by the half-life to get the number of halvings, then halve that many times.'},
{id:'ph24',subj:'physics',strand:'ph-atom',level:10,diff:2,q:'The nucleus of an atom contains:',opts:['protons and neutrons','protons and electrons','neutrons and electrons','electrons only'],a:0,why:'The nucleus holds protons and neutrons; electrons orbit outside it.',tech:'Nearly all the mass is in the nucleus, nearly all the volume is outside it.'},
{id:'ph25',subj:'physics',strand:'ph-elec',level:8,diff:2,q:'Which unit measures electric current?',opts:['ampere','volt','ohm','watt'],a:0,why:'Current is measured in amperes, potential difference in volts, resistance in ohms and power in watts.',tech:'Pair each quantity with its unit and its symbol before the examination.'},
{id:'ph26',subj:'physics',strand:'ph-elec',level:9,diff:3,q:'A 12 V supply drives 3 A through a component. Its resistance is:',opts:['4 Ω','36 Ω','15 Ω','0.25 Ω'],a:0,why:'R = V ÷ I = 12 ÷ 3 = 4 Ω.',tech:'V = IR. Write the formula, substitute, then rearrange — in that order.'},
{id:'ph27',subj:'physics',strand:'ph-elec',level:10,diff:2,q:'A fuse protects a circuit by:',opts:['melting and breaking the circuit if the current is too high','reducing the voltage','storing charge','increasing resistance gradually'],a:0,why:'The fuse wire melts above its rated current, cutting the supply before the cable overheats.',tech:'Choose a fuse rated just above the normal operating current. Questions ask you to pick one from a list.'},
{id:'ph28',subj:'physics',strand:'ph-thermal',level:8,diff:2,q:'Convection occurs in:',opts:['liquids and gases','solids only','a vacuum','solids and liquids only'],a:0,why:'Convection needs particles free to move, so it happens in fluids. Solids transfer heat by conduction.',tech:'State the mechanism as well as the name: warm fluid is less dense, rises, cools, sinks.'},
{id:'ph29',subj:'physics',strand:'ph-thermal',level:9,diff:2,q:'When a liquid evaporates, the liquid left behind:',opts:['cools down','warms up','stays the same temperature','freezes instantly'],a:0,why:'The fastest molecules escape first, lowering the average energy of those remaining — which is why sweating cools you.',tech:'Give an everyday example. Evaporative cooling questions usually ask for one.'},
{id:'ph30',subj:'physics',strand:'ph-thermal',level:10,diff:3,q:'Specific heat capacity is the energy needed to raise the temperature of:',opts:['1 kg of a substance by 1 °C','any mass by 1 °C','1 kg by 10 °C','1 g by 1 K'],a:0,why:'It is defined per kilogram and per degree, which is why the formula is E = mcΔT.',tech:'Watch the units in the data. Mixing grams and kilograms is the usual source of a wrong answer.'},
{id:'ph31',subj:'physics',strand:'ph-waves',level:9,diff:2,q:'In a transverse wave, the particles vibrate:',opts:['at right angles to the direction of travel','along the direction of travel','in circles only','not at all'],a:0,why:'Transverse vibrations are perpendicular to the travel direction; longitudinal ones are parallel.',tech:'Light is transverse, sound is longitudinal. Name an example when you define each.'},
{id:'ph32',subj:'physics',strand:'ph-waves',level:10,diff:3,q:'A wave has frequency 50 Hz and wavelength 4 m. Its speed is:',opts:['200 m/s','12.5 m/s','54 m/s','0.08 m/s'],a:0,why:'v = fλ = 50 × 4 = 200 m/s.',tech:'Frequency in hertz, wavelength in metres, speed in metres per second. Check units before substituting.'},
/* Primary Science */
{id:'ps16',subj:'p-science',strand:'ps-earth',level:3,diff:1,q:'Which of these causes day and night?',opts:['the Earth spinning on its axis','the Earth going round the Sun','the Moon moving','clouds covering the Sun'],a:0,why:'One spin takes 24 hours, giving day and night. Going round the Sun takes a year and gives the seasons.',tech:'Spin means day. Orbit means year. Two different movements, two different effects.'},
{id:'ps17',subj:'p-science',strand:'ps-earth',level:4,diff:2,q:'In the water cycle, water vapour turning back into liquid is called:',opts:['condensation','evaporation','precipitation','collection'],a:0,why:'Evaporation goes up as vapour; condensation forms droplets; precipitation falls as rain.',tech:'Name the four stages in order and say what happens to the water in each.'},
{id:'ps18',subj:'p-science',strand:'ps-earth',level:5,diff:2,q:'Soil that holds water for a long time and feels sticky is most likely:',opts:['clay','sand','gravel','loam'],a:0,why:'Clay has the smallest particles and the smallest gaps, so water drains slowly through it.',tech:'Link particle size to drainage: the bigger the particles, the faster the water passes.'},
{id:'ps19',subj:'p-science',strand:'ps-energy',level:4,diff:2,q:'Which force slows a ball rolling across the ground?',opts:['friction','gravity','magnetism','upthrust'],a:0,why:'Friction acts between the ball and the ground, opposing the motion. Gravity pulls downwards, not backwards.',tech:'Draw arrows for each force and say which way it points. Direction is what distinguishes them.'},
{id:'ps20',subj:'p-science',strand:'ps-energy',level:5,diff:2,q:'A torch changes electrical energy mainly into:',opts:['light energy','sound energy','chemical energy','elastic energy'],a:0,why:'The bulb converts electrical energy into light, with some heat. The chemical energy is in the battery, before the change.',tech:'State the change as "from … to …". Both halves are needed for the mark.'},
{id:'ps21',subj:'p-science',strand:'ps-matter',level:3,diff:1,q:'Which material is a good conductor of electricity?',opts:['copper','plastic','rubber','wood'],a:0,why:'Metals conduct. Plastic, rubber and wood are insulators, which is why wires are covered in plastic.',tech:'Say why the material is used, not just what it is. That is where the second mark sits.'},
{id:'ps22',subj:'p-science',strand:'ps-matter',level:5,diff:2,q:'Which method would separate sand from water?',opts:['filtering','melting','burning','freezing'],a:0,why:'Sand does not dissolve, so a filter traps it while the water passes through.',tech:'Ask first whether the solid dissolves. If it does, filtering will not work.'},
{id:'ps23',subj:'p-science',strand:'ps-body',level:3,diff:1,q:'Which food group gives the body most of its energy?',opts:['carbohydrates','vitamins','minerals','water'],a:0,why:'Carbohydrates are the main energy source. Vitamins and minerals are needed in small amounts for health.',tech:'Match each food group to its job and one food that supplies it.'},
{id:'ps24',subj:'p-science',strand:'ps-body',level:5,diff:2,q:'The job of the skeleton includes:',opts:['supporting the body and protecting organs','digesting food','pumping blood','making urine'],a:0,why:'The skeleton supports, protects and allows movement, and makes blood cells in the marrow.',tech:'Give three jobs of the skeleton. Questions often ask for more than one.'}
);

/* ===== BATCH H — depth pass: humanities and arts ===== */
window.CSEC_QUESTIONS.push(
/* History */
{id:'hi19',subj:'history',strand:'hi-emanc',level:8,diff:2,q:'Slavery was abolished in the British Caribbean by an Act passed in:',opts:['1833','1807','1838','1865'],a:0,why:'The Abolition of Slavery Act was passed in 1833 and took effect in 1834. The 1807 Act abolished the slave TRADE, not slavery.',tech:'1807 trade, 1834 slavery, 1838 full freedom. Three dates, three different events.'},
{id:'hi20',subj:'history',strand:'hi-emanc',level:9,diff:2,q:'Which was an ECONOMIC argument used by the abolitionists?',opts:['free labour would be cheaper and more productive than enslaved labour','slavery was morally wrong','the enslaved suffered on the Middle Passage','Christianity condemned slavery'],a:0,why:'The other three are humanitarian or religious arguments. Only the first is economic.',tech:'Sort abolition arguments into economic, humanitarian, religious and resistance. Questions name the category.'},
{id:'hi21',subj:'history',strand:'hi-emanc',level:9,diff:2,q:'The Apprenticeship system introduced in 1834 was intended to:',opts:['make the enslaved work unpaid for their former owners during a transition','give freed people land','train people in new trades of their choosing','pay full wages immediately'],a:0,why:'Apprentices had to give their former owners unpaid labour for a further four years. It was widely resented and ended early, in 1838.',tech:'Explain both the stated purpose and what actually happened. The gap between them is the answer.'},
{id:'hi22',subj:'history',strand:'hi-emanc',level:10,diff:3,q:'Which of these contributed MOST directly to Britain ending Apprenticeship early in 1838?',opts:['protest in the colonies and pressure from British reformers','a fall in sugar prices','the Haitian Revolution','the arrival of Indian indentured workers'],a:0,why:'Continued resistance in the colonies, reported abuses and campaigning in Britain made the system untenable.',tech:'When asked for the MOST direct cause, rank your reasons and justify the top one. Listing alone earns less.'},
{id:'hi23',subj:'history',strand:'hi-adjust',level:8,diff:2,q:'After emancipation, many freed people left the plantations in order to:',opts:['establish free villages and farm their own land','join the British army','migrate to Africa in large numbers','work in factories in Britain'],a:0,why:'Free villages were bought or settled so that families could work for themselves rather than for a former owner.',tech:'Name a free village and a colony where they were common. A specific example lifts the answer.'},
{id:'hi24',subj:'history',strand:'hi-adjust',level:9,diff:2,q:'Indentured labourers were brought to Trinidad mainly from:',opts:['India','China only','West Africa','Portugal'],a:0,why:'From 1845 the great majority came from India, though Chinese, Portuguese and African immigrants also arrived.',tech:'Know the start date, the main source and the terms of the contract. All three are examinable.'},
{id:'hi25',subj:'history',strand:'hi-adjust',level:9,diff:2,q:'Planters recruited indentured labour after emancipation in order to:',opts:['secure a cheap, controlled labour supply and keep wages down','reward freed people','develop new crops','settle empty land for the Crown'],a:0,why:'A surplus of workers under contract weakened the bargaining position of freed people and held wages down.',tech:'Give the planters’ motive AND the effect on freed people. Both sides earn marks.'},
{id:'hi26',subj:'history',strand:'hi-adjust',level:10,diff:3,q:'One lasting effect of indentureship on Trinidad was:',opts:['a plural society with a large Indo-Trinidadian population','the end of the sugar industry','the departure of all freed Africans','the abolition of the Crown Colony system'],a:0,why:'Indentureship reshaped the population, religion, language and food of Trinidad and produced its plural society.',tech:'Separate short-term from long-term effects. Questions usually specify which they want.'},
{id:'hi27',subj:'history',strand:'hi-skills',level:8,diff:2,q:'A PRIMARY source is one that was:',opts:['produced at the time by someone involved','written later by a historian','always printed in a book','always reliable'],a:0,why:'Primary sources come from the period itself. Being primary does not make a source reliable — it may still be biased.',tech:'Never say a source is reliable just because it is primary. Ask who made it and why.'},
{id:'hi28',subj:'history',strand:'hi-skills',level:9,diff:2,q:'When a question asks you to assess the USEFULNESS of a source, you should comment on:',opts:['its content and its origin, purpose and limitations','its length','how easy it is to read','whether you agree with it'],a:0,why:'Usefulness depends on what the source says and on who produced it, why, and what it leaves out.',tech:'Use the frame: what it tells us, who made it, why, and what is missing. Four sentences, four marks.'},
{id:'hi29',subj:'history',strand:'hi-skills',level:9,diff:2,q:'A plantation owner’s diary describing enslaved people as content is:',opts:['still useful, because it shows how owners justified slavery','useless, because it is biased','proof that they were content','unusable as it is primary'],a:0,why:'Bias is evidence in itself. The source is poor evidence of how people felt but good evidence of the owner’s outlook.',tech:'Turn bias into a finding. "This tells us about the author" is a stronger answer than "this is biased".'},
{id:'hi30',subj:'history',strand:'hi-skills',level:10,diff:3,q:'The strongest structure for a History essay paragraph is:',opts:['point, evidence, explanation, link back to the question','story told in order','a list of dates','opinion followed by a quotation'],a:0,why:'Examiners credit an argument supported by specific evidence and tied back to the question, not narrative.',tech:'Finish every paragraph with a sentence containing the question’s own words. It forces the link.'},
{id:'hi31',subj:'history',strand:'hi-resist',level:8,diff:2,q:'The Haitian Revolution succeeded in 1804 in:',opts:['creating the first independent Black republic','restoring French rule','ending the slave trade in Britain','uniting the Caribbean'],a:0,why:'Haiti became independent in 1804, the only enslaved revolt to found a nation.',tech:'Know its causes, its leaders and its effects on other colonies. All three appear in questions.'},
{id:'hi32',subj:'history',strand:'hi-resist',level:9,diff:2,q:'Which is an example of PASSIVE resistance on the plantations?',opts:['working slowly and breaking tools','armed revolt','escaping to form a maroon community','burning the cane fields'],a:0,why:'Passive resistance disrupted work without open confrontation. The others are active or violent resistance.',tech:'Classify each example before you write. Questions ask for one kind specifically.'},
{id:'hi33',subj:'history',strand:'hi-resist',level:10,diff:3,q:'The 1831 Christmas Rebellion in Jamaica is significant because it:',opts:['hastened the abolition of slavery by showing the system could not be held','restored planter control','was entirely peaceful','had no effect on Britain'],a:0,why:'The scale of the revolt and the brutality of its suppression strengthened the abolitionist case in Britain.',tech:'Link a named revolt to a named consequence. That pairing is what the marks reward.'},
{id:'hi34',subj:'history',strand:'hi-slavery',level:8,diff:2,q:'The Middle Passage refers to the voyage from:',opts:['West Africa to the Americas','Europe to West Africa','the Americas to Europe','the Caribbean to North America'],a:0,why:'It is the middle leg of the Triangular Trade, on which enslaved Africans were carried across the Atlantic.',tech:'Know the conditions and the estimated mortality. Questions ask you to describe, then to explain the effects.'},
{id:'hi35',subj:'history',strand:'hi-slavery',level:9,diff:2,q:'Sugar dominated Caribbean plantation economies because it:',opts:['was highly profitable in Europe and suited the climate and soil','required little labour','was grown for local use','could be stored indefinitely without processing'],a:0,why:'European demand made sugar enormously profitable, and it grew well in the region — but it demanded intensive labour.',tech:'Link the crop, the labour system and the profits as one argument, not three separate facts.'},
{id:'hi36',subj:'history',strand:'hi-indigenous',level:7,diff:2,q:'The indigenous people of Trinidad at the time of Columbus’s arrival included the:',opts:['Kalinago and Taino','Maya and Aztec','Arawak of Guyana only','Maroons'],a:0,why:'The Taino and Kalinago peoples inhabited the islands. Maya and Aztec civilisations were on the mainland.',tech:'Use the peoples’ own names. Compare their economy, social organisation and technology.'},
{id:'hi37',subj:'history',strand:'hi-indigenous',level:9,diff:3,q:'The indigenous population collapsed after European contact mainly because of:',opts:['European diseases to which they had no immunity','emigration','a change in climate','war between indigenous groups'],a:0,why:'Smallpox, measles and influenza killed far more than warfare or forced labour, though all three contributed.',tech:'Give the main cause first and support it, then name the others briefly. Ranking earns the higher band.'},
{id:'hi38',subj:'history',strand:'hi-indep',level:9,diff:2,q:'Universal adult suffrage was introduced in Trinidad and Tobago in:',opts:['1946','1962','1976','1937'],a:0,why:'Adult suffrage came in 1946, sixteen years before independence in 1962.',tech:'Build a timeline: 1937 riots, 1946 suffrage, 1956 PNM, 1962 independence, 1976 republic.'},
{id:'hi39',subj:'history',strand:'hi-indep',level:10,diff:3,q:'The West Indies Federation collapsed in 1962 largely because of:',opts:['disagreement over taxation, freedom of movement and the dominance of larger islands','a hurricane','British opposition','a lack of a common language'],a:0,why:'Jamaica’s withdrawal after its 1961 referendum ended it, following disputes over finance and representation.',tech:'Quote the remark that "one from ten leaves nought" and explain what it meant for Trinidad.'},
/* Geography */
{id:'ge17',subj:'geography',strand:'ge-econ',level:8,diff:2,q:'Farming, fishing and mining belong to which sector?',opts:['primary','secondary','tertiary','quaternary'],a:0,why:'Primary industries take raw materials from the earth or sea. Secondary manufactures; tertiary provides services.',tech:'Sort any named job into a sector before answering. The sector decides the rest of the answer.'},
{id:'ge18',subj:'geography',strand:'ge-econ',level:9,diff:2,q:'Trinidad’s economy depends most heavily on:',opts:['oil and natural gas','bananas','tourism','bauxite'],a:0,why:'Energy dominates Trinidad’s exports and revenue. Tourism is far more important to Tobago and to other islands.',tech:'Know one economic strength and one vulnerability for Trinidad and Tobago. Both appear in questions.'},
{id:'ge19',subj:'geography',strand:'ge-econ',level:10,diff:3,q:'A major risk of depending on a single export commodity is that:',opts:['a fall in world prices damages the whole economy','production becomes too efficient','workers become overqualified','the currency cannot be traded'],a:0,why:'Monocrop or single-resource economies have no cushion when prices fall. Diversification reduces the risk.',tech:'Name the risk, then name diversification as the response and give one example of it.'},
{id:'ge20',subj:'geography',strand:'ge-hazard',level:8,diff:2,q:'Which scale measures the strength of a hurricane?',opts:['Saffir-Simpson','Richter','Mercalli','Beaufort'],a:0,why:'Saffir-Simpson rates hurricanes by wind speed. Richter and Mercalli are used for earthquakes.',tech:'Pair each scale with its hazard. Confusing them costs an easy mark.'},
{id:'ge21',subj:'geography',strand:'ge-hazard',level:9,diff:2,q:'Which is a MITIGATION measure against earthquake damage?',opts:['enforcing a building code for new construction','holding an evacuation drill','distributing relief supplies afterwards','issuing a warning'],a:0,why:'Mitigation reduces the impact before any event. Drills are preparedness; relief is response.',tech:'Use the four-stage framework and label your example with the stage it belongs to.'},
{id:'ge22',subj:'geography',strand:'ge-hazard',level:10,diff:3,q:'Caribbean islands are vulnerable to hurricanes partly because:',opts:['much of the population and infrastructure is on low-lying coasts','they have no warning systems','hurricanes are unpredictable in season','they lie outside the tropics'],a:0,why:'Concentration of settlement, ports and tourism on the coast raises exposure to storm surge and wind.',tech:'Vulnerability combines the hazard with human exposure. Discuss both, not the weather alone.'},
{id:'ge23',subj:'geography',strand:'ge-pop',level:7,diff:2,q:'Population density is calculated as:',opts:['total population divided by land area','births minus deaths','total population of a country','the number of towns'],a:0,why:'Density measures people per square kilometre. Births minus deaths is natural increase.',tech:'Learn density, natural increase and growth rate as three separate calculations.'},
{id:'ge24',subj:'geography',strand:'ge-pop',level:9,diff:2,q:'Rural to urban migration is usually driven by the PUSH factor of:',opts:['limited employment in rural areas','better schools in the city','bright city lights','higher urban wages'],a:0,why:'Push factors operate at the origin. The other three are pull factors at the destination.',tech:'Split your answer into push and pull columns. Putting one in the wrong column loses the mark.'},
{id:'ge25',subj:'geography',strand:'ge-pop',level:10,diff:3,q:'A consequence of rapid urban growth in Caribbean cities is:',opts:['pressure on housing, water and transport','a falling birth rate in the city','a shortage of workers','the expansion of farmland'],a:0,why:'Services cannot expand as quickly as the population, producing overcrowding, squatting and congestion.',tech:'Give consequences under social, economic and environmental headings. Three headings, three marks.'},
{id:'ge26',subj:'geography',strand:'ge-tectonic',level:8,diff:2,q:'Volcanoes and earthquakes occur mainly:',opts:['at plate boundaries','in the centre of plates','only at the equator','where rainfall is highest'],a:0,why:'Plate margins are where crust is created, destroyed or dragged past itself, releasing energy.',tech:'Name the boundary type as well — destructive, constructive or conservative — and what it produces.'},
{id:'ge27',subj:'geography',strand:'ge-tectonic',level:10,diff:3,q:'The eastern Caribbean islands are volcanic because they lie:',opts:['along a destructive boundary where the Atlantic plate subducts','on a constructive boundary','far from any plate margin','on a conservative boundary'],a:0,why:'The Atlantic plate is forced beneath the Caribbean plate, melting and producing the island arc.',tech:'Use a regional example: Montserrat’s Soufrière Hills. Named examples separate grade one answers.'},
{id:'ge28',subj:'geography',strand:'ge-weather',level:8,diff:2,q:'Relief rainfall occurs when:',opts:['moist air is forced to rise over high land','the ground heats up strongly','two air masses meet','air sinks over the sea'],a:0,why:'Rising air cools, condenses and rains on the windward slope, leaving a rain shadow beyond.',tech:'Three rainfall types: relief, convectional, frontal. Draw each and label the direction of the air.'},
{id:'ge29',subj:'geography',strand:'ge-weather',level:9,diff:2,q:'The Caribbean dry season generally runs from:',opts:['January to May','June to December','all year round','September to November'],a:0,why:'The dry season runs roughly January to May and the wet season June to December, with hurricanes peaking August to October.',tech:'Tie the seasons to the hurricane season. Questions often combine them.'},
/* Social Studies (CSEC) */
{id:'ss17',subj:'social-studies',strand:'ss-research',level:9,diff:2,q:'In the Social Studies SBA, a hypothesis is best described as:',opts:['a statement you set out to test','a question you ask','a summary of findings','a list of sources'],a:0,why:'The hypothesis is a testable statement. The findings come later and either support it or do not.',tech:'Keep the hypothesis narrow enough to test with the data you can actually collect.'},
{id:'ss18',subj:'social-studies',strand:'ss-research',level:9,diff:2,q:'A questionnaire is most suitable when you want:',opts:['the same information from a large number of people','deep detail from one person','to observe behaviour','historical records'],a:0,why:'Questionnaires standardise the questions, making responses comparable across many people. Interviews give depth instead.',tech:'Justify your chosen instrument in the SBA. Marks are awarded for the reason, not the choice.'},
{id:'ss19',subj:'social-studies',strand:'ss-research',level:10,diff:3,q:'A random sample is used in order to:',opts:['reduce bias by giving everyone an equal chance of selection','make the sample larger','save time','choose the most helpful respondents'],a:0,why:'Equal chance of selection is what makes the sample representative. Choosing helpful respondents introduces bias.',tech:'Name the sampling method and say what bias it avoids. Both halves are credited.'},
{id:'ss20',subj:'social-studies',strand:'ss-research',level:10,diff:2,q:'Which section of the SBA states what you found, without interpreting it?',opts:['presentation of data','discussion of findings','recommendations','statement of the problem'],a:0,why:'Presentation shows the data in tables and charts; discussion explains what it means; recommendations propose action.',tech:'Keep the sections distinct. Interpreting inside the presentation section loses structure marks.'},
{id:'ss21',subj:'social-studies',strand:'ss-dev',level:8,diff:2,q:'Sustainable development means meeting present needs:',opts:['without preventing future generations from meeting theirs','as quickly as possible','using only imported resources','regardless of environmental cost'],a:0,why:'The definition balances present use against future availability.',tech:'Learn the definition word for word. It is worth a mark on its own and frames every answer in this unit.'},
{id:'ss22',subj:'social-studies',strand:'ss-dev',level:9,diff:2,q:'Which is a RENEWABLE resource?',opts:['solar energy','natural gas','petroleum','asphalt'],a:0,why:'Solar energy is continuously replaced. The other three are finite fossil or mineral resources.',tech:'For Trinidad and Tobago, connect resource dependence to the need for diversification.'},
{id:'ss23',subj:'social-studies',strand:'ss-dev',level:10,diff:3,q:'One way individuals can reduce environmental damage is by:',opts:['reducing, reusing and recycling household waste','increasing consumption','burning rubbish in the yard','using more single-use plastic'],a:0,why:'The three Rs cut the waste stream at source. Burning rubbish creates air pollution.',tech:'Give individual, community and government measures separately. Questions often ask for a specific level.'},
{id:'ss24',subj:'social-studies',strand:'ss-gov',level:8,diff:2,q:'In a parliamentary democracy, laws are made by the:',opts:['legislature','judiciary','executive','civil service'],a:0,why:'The legislature makes laws, the executive carries them out and the judiciary interprets them.',tech:'Three arms, three functions. Name all three when asked about the separation of powers.'},
{id:'ss25',subj:'social-studies',strand:'ss-gov',level:10,diff:2,q:'A responsibility that comes with the right to vote is:',opts:['becoming informed about the candidates and issues','voting for the largest party','telling others how to vote','voting only in general elections'],a:0,why:'Rights carry matching responsibilities; an informed vote is the responsibility attached to the franchise.',tech:'Pair each right with its responsibility. Questions on citizenship ask for the pairing.'},
{id:'ss26',subj:'social-studies',strand:'ss-region',level:8,diff:2,q:'CARICOM was established by which treaty?',opts:['the Treaty of Chaguaramas','the Treaty of Basseterre','the Treaty of Rome','the Treaty of Port of Spain'],a:0,why:'The Treaty of Chaguaramas, signed in 1973, created the Caribbean Community. The OECS came from the Treaty of Basseterre.',tech:'Match each organisation to its founding treaty and year.'},
{id:'ss27',subj:'social-studies',strand:'ss-region',level:9,diff:2,q:'One benefit of regional integration is:',opts:['a larger combined market for goods and services','higher tariffs between members','separate currencies for each state','reduced movement of skilled workers'],a:0,why:'Pooling small markets raises bargaining power and widens trade. Integration removes barriers rather than raising them.',tech:'Support each benefit with a CARICOM example, such as the CSME or the CXC itself.'},
{id:'ss28',subj:'social-studies',strand:'ss-issues',level:8,diff:2,q:'Which best describes a social problem?',opts:['a condition affecting many people that society judges harmful and wants changed','any event people dislike','a problem faced by one family','a natural disaster'],a:0,why:'A social problem is widespread, harmful and recognised as needing collective action.',tech:'Apply all three tests — widespread, harmful, recognised — before calling something a social problem.'},
{id:'ss29',subj:'social-studies',strand:'ss-issues',level:10,diff:3,q:'When asked to EVALUATE a solution to a social problem, you should:',opts:['weigh its strengths against its limitations and reach a judgement','list it only','describe the problem again','give your opinion without reasons'],a:0,why:'Evaluate means judge, using evidence on both sides.',tech:'Learn the command words: state, describe, explain, discuss, evaluate. Each demands a different depth.'},
/* Primary Social Studies */
{id:'pss16',subj:'p-social-studies',strand:'pss-self',level:1,diff:1,q:'Which one shows good manners at home?',opts:['saying please and thank you','shouting for what you want','taking food without asking','leaving a mess for others'],a:0,why:'Good manners show respect for the people you live with.',tech:'Think about how the other person feels. That is usually the answer.'},
{id:'pss17',subj:'p-social-studies',strand:'pss-self',level:2,diff:1,q:'A family member who is your mother’s brother is your:',opts:['uncle','cousin','nephew','grandfather'],a:0,why:'Your mother’s or father’s brother is your uncle. Their child would be your cousin.',tech:'Draw a simple family tree and label each person. It makes these questions easy.'},
{id:'pss18',subj:'p-social-studies',strand:'pss-self',level:3,diff:2,q:'Working together in a group at school works best when:',opts:['everyone has a job and listens to each other','one person does everything','nobody speaks','everyone talks at once'],a:0,why:'Sharing tasks and listening lets the group use everyone’s effort.',tech:'Give a reason with your answer. "Because everyone helps" turns one mark into two.'},
{id:'pss19',subj:'p-social-studies',strand:'pss-citizen',level:3,diff:2,q:'Which action helps to keep your community clean?',opts:['putting litter in a bin','throwing litter in the drain','burning rubbish in the street','leaving bottles on the beach'],a:0,why:'Bins keep waste out of drains, which flood when they are blocked.',tech:'Link the action to its effect. Blocked drains cause flooding — that link earns the mark.'},
{id:'pss20',subj:'p-social-studies',strand:'pss-citizen',level:5,diff:2,q:'The national motto of Trinidad and Tobago is:',opts:['Together we aspire, together we achieve','Out of many, one people','Discipline, Production, Tolerance','One people, one nation, one destiny'],a:0,why:'That is the motto of Trinidad and Tobago. "Out of many, one people" is Jamaica’s and "Discipline, Production, Tolerance" is Guyana’s.',tech:'Learn the flag, the motto, the national anthem, the birds and the flowers. All are examined.'},
{id:'pss21',subj:'p-social-studies',strand:'pss-geog',level:4,diff:2,q:'On most maps, the direction at the top of the page is:',opts:['north','south','east','west'],a:0,why:'Maps are conventionally drawn with north at the top, which is why a compass rose is included.',tech:'Find the compass rose and the scale before reading any map question.'},
{id:'pss22',subj:'p-social-studies',strand:'pss-geog',level:5,diff:2,q:'Trinidad’s Northern Range is best described as:',opts:['a chain of mountains along the north of the island','a large swamp','a coral reef','a river valley'],a:0,why:'The Northern Range runs east to west across northern Trinidad and contains its highest peaks.',tech:'Know the main physical features and roughly where each one lies.'},
{id:'pss23',subj:'p-social-studies',strand:'pss-history',level:4,diff:2,q:'Emancipation Day in Trinidad and Tobago is celebrated on:',opts:['1 August','31 August','24 September','30 May'],a:0,why:'Emancipation Day is 1 August. Independence Day is 31 August and Indian Arrival Day is 30 May.',tech:'Make a calendar of national holidays and what each one remembers.'},
{id:'pss24',subj:'p-social-studies',strand:'pss-history',level:5,diff:2,q:'Indian Arrival Day remembers the arrival in 1845 of:',opts:['the first indentured labourers from India','Christopher Columbus','the first Governor','the first steel band'],a:0,why:'The Fatel Razack brought the first indentured labourers from India to Trinidad in 1845.',tech:'Link each holiday to the event and the year. Both are asked for.'},
/* Visual Arts */
{id:'va19',subj:'visual-arts',strand:'va-history',level:8,diff:2,q:'Carnival costume design in Trinidad draws most strongly on:',opts:['African, Indian and European traditions blended locally','European traditions only','Asian traditions only','no earlier traditions'],a:0,why:'Trinidad Carnival grew from the mixing of African, Indian, French and other traditions into a distinct local form.',tech:'Name a specific mas character — Moko Jumbie, Midnight Robber, Dame Lorraine — and its origin.'},
{id:'va20',subj:'visual-arts',strand:'va-history',level:9,diff:2,q:'When writing about an artwork, "composition" refers to:',opts:['how the elements are arranged within the picture','the colours used alone','the size of the canvas','the artist’s biography'],a:0,why:'Composition is the arrangement — balance, focal point, use of space. Colour is one element within it.',tech:'Use the vocabulary of the elements and principles when you critique. It is what the mark scheme looks for.'},
{id:'va21',subj:'visual-arts',strand:'va-history',level:9,diff:2,q:'A Moko Jumbie is a mas character known for:',opts:['performing on tall stilts','wearing a mirrored suit','carrying a whip','playing a steelpan'],a:0,why:'The Moko Jumbie is a stilt-walker whose origins lie in West African tradition.',tech:'Know three traditional mas characters and where each came from.'},
{id:'va22',subj:'visual-arts',strand:'va-history',level:10,diff:3,q:'Describing an artwork’s CONTEXT means discussing:',opts:['the time, place and circumstances in which it was made','its price','the materials alone','your personal preference'],a:0,why:'Context explains why the work looks as it does — its period, society and the artist’s situation.',tech:'Structure a critique as describe, analyse, interpret, judge. Context belongs in the interpretation.'},
{id:'va23',subj:'visual-arts',strand:'va-print',level:7,diff:1,q:'In printmaking, the areas cut away from a lino block will print:',opts:['as the colour of the paper','as the darkest areas','not at all on any part','as raised texture'],a:0,why:'Ink sits on the raised surface. Whatever is cut away stays unprinted and shows the paper.',tech:'Plan in reverse: decide what you want white, and cut exactly that.'},
{id:'va24',subj:'visual-arts',strand:'va-print',level:8,diff:2,q:'A design that repeats at regular intervals across a fabric is called a:',opts:['repeat pattern','monoprint','collage','still life'],a:0,why:'Repeat patterns tile across a surface and are the basis of textile design.',tech:'Test your repeat by drawing the unit four times side by side. Joins show up immediately.'},
{id:'va25',subj:'visual-arts',strand:'va-print',level:9,diff:2,q:'Batik produces its pattern by:',opts:['using wax to resist the dye','printing with a roller','stitching threads into cloth','bleaching the whole cloth'],a:0,why:'Wax blocks the dye from reaching the covered areas, leaving the pattern when it is removed.',tech:'Resist methods — batik, tie-dye — work by blocking dye. Say what does the blocking.'},
{id:'va26',subj:'visual-arts',strand:'va-print',level:10,diff:2,q:'In graphic design, legibility is most affected by:',opts:['the contrast between the text and the background','the number of colours used','the size of the paper','the use of a border'],a:0,why:'Low contrast makes text hard to read regardless of size or styling.',tech:'View your design small and in grey scale. If it fails either test, the contrast is too low.'},
{id:'va27',subj:'visual-arts',strand:'va-draw',level:6,diff:1,q:'In observational drawing you should draw:',opts:['what you actually see in front of you','what you think the object should look like','from memory','a copy of a photograph'],a:0,why:'Observational drawing trains you to record what is there, including the parts that surprise you.',tech:'Measure with your pencil at arm’s length and compare proportions before committing a line.'},
{id:'va28',subj:'visual-arts',strand:'va-draw',level:8,diff:2,q:'Shading that suggests a curved surface should:',opts:['change gradually from light to dark','be one flat tone','use hard outlines only','be applied at random'],a:0,why:'Gradual tonal change reads as curvature; flat tone reads as a flat surface.',tech:'Find the light source first, then work out where the highlight, mid-tone, core shadow and reflected light fall.'},
{id:'va29',subj:'visual-arts',strand:'va-draw',level:9,diff:2,q:'In one-point perspective, parallel lines going away from the viewer:',opts:['meet at a single vanishing point on the horizon','stay parallel','curve upwards','meet at two points'],a:0,why:'One vanishing point on the eye-level horizon line is what defines one-point perspective.',tech:'Draw the horizon line first and place the vanishing point on it. Everything else is ruled to that point.'},
{id:'va30',subj:'visual-arts',strand:'va-portfolio',level:9,diff:2,q:'Recording the source of an image you worked from matters because:',opts:['using another artist’s work without acknowledgement is plagiarism','it makes the folder longer','it is optional decoration','it proves you can write'],a:0,why:'Influence is welcomed and must be acknowledged. Unacknowledged copying is penalised.',tech:'Note the artist and where you saw the work beside every reference image as you collect it.'},
{id:'va31',subj:'visual-arts',strand:'va-portfolio',level:10,diff:2,q:'Annotating your sketchbook should explain:',opts:['what you tried, what worked and what you will do next','only what the piece is called','the price of materials','what your friend thinks'],a:0,why:'Annotation evidences your reasoning. Naming the piece shows nothing about your thinking.',tech:'Three sentences per page: what I tried, what happened, what next. Write it while the work is fresh.'}
);

/* ===== BATCH I — depth pass: languages, IT, PE, remaining English & Maths ===== */
window.CSEC_QUESTIONS.push(
/* Spanish */
{id:'sp22',subj:'spanish',strand:'sp-read',level:6,diff:1,q:'You meet an unknown word in a Spanish reading passage. You should first:',opts:['use the rest of the sentence to work out what it means','stop reading','skip the whole paragraph','translate every word before continuing'],a:0,why:'Context usually gives enough to answer the question. Translating everything wastes the time you need.',tech:'Read the questions before the passage. Then read hunting for those answers only.'},
{id:'sp23',subj:'spanish',strand:'sp-read',level:7,diff:2,q:'"Ayer fuimos al mercado" tells you the action happened:',opts:['in the past','today','tomorrow','every day'],a:0,why:'"Ayer" means yesterday and "fuimos" is the preterite of ir.',tech:'Time markers — ayer, mañana, siempre — are the quickest clue to the tense of a passage.'},
{id:'sp24',subj:'spanish',strand:'sp-read',level:8,diff:2,q:'A cognate is a word that:',opts:['looks and means much the same in Spanish and English','sounds the same but means something different','has no English equivalent','is always a verb'],a:0,why:'Cognates such as hospital, familia and importante give you free comprehension. False friends such as embarazada do not.',tech:'Use cognates, but check them against the sentence. A false friend can flip your whole answer.'},
{id:'sp25',subj:'spanish',strand:'sp-read',level:10,diff:3,q:'When a comprehension question says "según el texto", your answer must:',opts:['come from the passage, not from your own knowledge','be in English only','be your opinion','be one word'],a:0,why:'"According to the text" restricts you to what the passage actually says.',tech:'Point to the line you took the answer from before you write it. If you cannot, it is not in the text.'},
{id:'sp26',subj:'spanish',strand:'sp-write',level:9,diff:2,q:'To raise the level of a piece of Spanish writing you should:',opts:['use connectives such as porque, sin embargo and además','use longer nouns','repeat the same verb','write only short sentences'],a:0,why:'Connectives show range and link ideas, which is exactly what the language criterion rewards.',tech:'Learn six connectives and place one in each paragraph deliberately.'},
{id:'sp27',subj:'spanish',strand:'sp-write',level:10,diff:3,q:'Before handing in a Spanish composition, the most valuable check is:',opts:['adjective agreement and verb endings','the neatness of your handwriting','the number of paragraphs','whether you used a dictionary'],a:0,why:'Agreement and verb endings are where most accuracy marks are won or lost.',tech:'Check one thing per pass: verbs, then agreements, then accents. Three quick passes beat one vague one.'},
{id:'sp28',subj:'spanish',strand:'sp-listen',level:9,diff:2,q:'In a listening item you hear a price. The safest way to record it is:',opts:['write the digits immediately, then check on the second play','memorise it until the end','write it in words','wait and guess'],a:0,why:'Working memory fails under pressure. Digits on paper survive to the second play.',tech:'Note numbers, names and times the instant you hear them. Everything else can wait.'},
{id:'sp29',subj:'spanish',strand:'sp-speak',level:10,diff:3,q:'If you make a mistake mid-sentence in the oral, you should:',opts:['correct yourself and carry on','stop and start the whole task again','switch to English','say nothing more'],a:0,why:'Self-correction shows awareness of the language and is credited. Abandoning the task is not.',tech:'Practise the phrase "perdón, quiero decir…" so the correction sounds natural.'},
/* French */
{id:'fr19',subj:'french',strand:'fr-read',level:6,diff:1,q:'In a French reading passage, the title and any picture are useful because they:',opts:['tell you the topic before you start reading','contain the answers','can be ignored','are always in English'],a:0,why:'Knowing the topic activates the vocabulary you already have for it.',tech:'Spend ten seconds on the title and picture. It makes the first read far faster.'},
{id:'fr20',subj:'french',strand:'fr-read',level:7,diff:2,q:'"Il y a trois chambres dans la maison" means there are three:',opts:['bedrooms','kitchens','cars','schools'],a:0,why:'"Chambre" is a bedroom. A room in general is "pièce" and a kitchen is "cuisine".',tech:'Learn vocabulary in topic sets — house, school, food, health. Papers are built around those themes.'},
{id:'fr21',subj:'french',strand:'fr-read',level:8,diff:2,q:'"Actuellement" is a false friend because it means:',opts:['currently','actually','rarely','accurately'],a:0,why:'It means at present, not "actually". Assuming the English meaning changes the sense of the sentence.',tech:'Keep a list of false friends as you meet them. They are deliberately placed in papers.'},
{id:'fr22',subj:'french',strand:'fr-read',level:10,diff:3,q:'A question asking you to "justifier votre réponse" requires you to:',opts:['quote or refer to the part of the text that supports your answer','give a longer answer','answer in English','give your opinion'],a:0,why:'Justification means evidence from the text.',tech:'Answer, then add the supporting phrase from the passage. Two parts, two marks.'},
{id:'fr23',subj:'french',strand:'fr-write',level:8,diff:2,q:'In French, most adjectives:',opts:['come after the noun and agree with it','come before the noun always','never change form','agree only in the plural'],a:0,why:'Most French adjectives follow the noun and agree in gender and number. A small group (BAGS adjectives) comes before.',tech:'Check every adjective against its noun before you hand in. Agreement errors are the most common loss.'},
{id:'fr24',subj:'french',strand:'fr-write',level:9,diff:2,q:'Which is a suitable formal closing for a French letter?',opts:['Veuillez agréer, Monsieur, mes salutations distinguées.','Bisous','Salut','À plus'],a:0,why:'The first is the standard formal closing. The others are informal and would be wrong in a business letter.',tech:'Learn one formal and one informal opening and closing. That covers every letter task.'},
{id:'fr25',subj:'french',strand:'fr-write',level:10,diff:3,q:'Which sentence uses the passé composé correctly?',opts:['Je suis allé au cinéma.','J’ai allé au cinéma.','Je vais allé au cinéma.','J’suis aller au cinéma.'],a:0,why:'Aller takes être in the passé composé, and the participle agrees with the subject.',tech:'Learn the être verbs as a set. Everything else takes avoir.'},
{id:'fr26',subj:'french',strand:'fr-listen',level:9,diff:2,q:'French listening passages often test dates. "Le premier août" is:',opts:['1 August','31 August','1 April','8 January'],a:0,why:'"Premier" is used for the first of the month; other days use ordinary numbers.',tech:'Practise months and dates aloud. They appear in almost every listening paper.'},
{id:'fr27',subj:'french',strand:'fr-listen',level:10,diff:3,q:'You hear a speaker say "je n’aime pas du tout". They are expressing:',opts:['strong dislike','mild liking','uncertainty','strong liking'],a:0,why:'"Pas du tout" intensifies the negative: not at all.',tech:'Listen for the intensifier as well as the verb. It often decides between two similar options.'},
{id:'fr28',subj:'french',strand:'fr-speak',level:7,diff:2,q:'Good pronunciation in French requires you to remember that final consonants are:',opts:['usually silent','always sounded','sounded only in questions','the same as in English'],a:0,why:'Final consonants are generally not pronounced, which is why petit and petite sound different.',tech:'Read aloud daily for five minutes. Pronunciation is a skill, not knowledge.'},
{id:'fr29',subj:'french',strand:'fr-themes',level:7,diff:1,q:'Which set of words belongs to the theme "la santé"?',opts:['médecin, hôpital, malade','école, cahier, professeur','voiture, train, avion','cuisine, salon, jardin'],a:0,why:'Doctor, hospital and ill all belong to health. The others are school, transport and house.',tech:'Revise by theme, not alphabetically. Papers are organised by theme.'},
{id:'fr30',subj:'french',strand:'fr-themes',level:9,diff:2,q:'For the theme "l’environnement", a useful phrase is:',opts:['il faut protéger la planète','j’ai faim','il fait beau','je vais au marché'],a:0,why:'"We must protect the planet" fits the environment theme; the others belong to hunger, weather and shopping.',tech:'Prepare two ready-made opinion sentences per theme. They lift both the oral and the writing.'},
/* Information Technology */
{id:'it19',subj:'information-technology',strand:'it-database',level:8,diff:2,q:'In a database, a record is:',opts:['all the data about one item or person','a single column','the name of the table','a printed report'],a:0,why:'A record is one row — everything known about one entity. A field is one column.',tech:'Table, record, field, key. Four words you must use precisely.'},
{id:'it20',subj:'information-technology',strand:'it-database',level:9,diff:2,q:'A primary key must be:',opts:['unique for every record','the first field in the table','a number','the longest field'],a:0,why:'Uniqueness is what lets the key identify one record with certainty.',tech:'Ask whether two records could ever share the value. If so, it cannot be the primary key.'},
{id:'it21',subj:'information-technology',strand:'it-database',level:9,diff:2,q:'A query is used to:',opts:['find records that match stated criteria','enter new data','print a report','design the table'],a:0,why:'Queries select and filter. Forms enter data and reports present it.',tech:'Match the object to the job: table stores, form enters, query finds, report presents.'},
{id:'it22',subj:'information-technology',strand:'it-database',level:10,diff:3,q:'In HTML, the tag that creates a link to another page is:',opts:['<a>','<p>','<img>','<h1>'],a:0,why:'The anchor tag with an href attribute creates a hyperlink. <img> embeds an image.',tech:'Learn ten core tags and what each does. Web page questions are built from them.'},
{id:'it23',subj:'information-technology',strand:'it-productivity',level:6,diff:1,q:'In a spreadsheet, a formula must begin with:',opts:['an equals sign','a plus sign','a letter','a bracket'],a:0,why:'Without the equals sign the cell treats the entry as text and shows it literally.',tech:'If a cell shows the formula instead of the answer, check the equals sign first.'},
{id:'it24',subj:'information-technology',strand:'it-productivity',level:8,diff:2,q:'=SUM(A1:A10) will:',opts:['add the values in cells A1 to A10','count how many cells are filled','find the largest value','average the values'],a:0,why:'SUM adds; COUNT counts; MAX finds the largest; AVERAGE means.',tech:'Learn SUM, AVERAGE, COUNT, MAX, MIN and IF. Those six cover most of the paper.'},
{id:'it25',subj:'information-technology',strand:'it-productivity',level:9,diff:3,q:'The reference $A$1 in a spreadsheet is:',opts:['absolute, so it does not change when copied','relative, so it shifts when copied','a text label','an error'],a:0,why:'Dollar signs fix the column and row, so copying the formula keeps pointing at the same cell.',tech:'Use absolute references for a fixed rate or total. Copying a relative one down a column is the usual bug.'},
{id:'it26',subj:'information-technology',strand:'it-productivity',level:9,diff:2,q:'Mail merge in word processing is used to:',opts:['produce many personalised letters from one template and a data source','check spelling','change the font','insert page numbers'],a:0,why:'The template supplies the wording and the data source supplies the names and details.',tech:'Know the two ingredients — main document and data source — and name both.'},
{id:'it27',subj:'information-technology',strand:'it-solve',level:8,diff:2,q:'The correct order in solving a problem by computer is:',opts:['define the problem, plan the solution, code it, test it','code it, then define it','test first, then plan','plan and code at the same time'],a:0,why:'Defining and planning before coding is what makes the code work. Testing follows.',tech:'Learn the stages of the problem-solving cycle in order. Questions ask you to name them.'},
{id:'it28',subj:'information-technology',strand:'it-solve',level:9,diff:2,q:'In a flowchart, a diamond shape represents:',opts:['a decision','a process','input or output','the start or end'],a:0,why:'Diamond is decision, rectangle is process, parallelogram is input/output, oval is terminal.',tech:'Memorise the four shapes. Using the wrong one loses marks even when the logic is right.'},
{id:'it29',subj:'information-technology',strand:'it-solve',level:10,diff:3,q:'A trace table is used to:',opts:['record the value of each variable at each step of an algorithm','write the final program','design the user interface','store data permanently'],a:0,why:'Tracing shows exactly where the logic goes wrong, which is why it is examined.',tech:'One column per variable, one row per pass through the loop. Fill it in slowly.'},
{id:'it30',subj:'information-technology',strand:'it-data',level:8,diff:2,q:'How many bits are in one byte?',opts:['8','4','16','1024'],a:0,why:'A byte is eight bits. 1024 bytes make a kilobyte.',tech:'Learn the ladder: bit, byte, KB, MB, GB, TB — and the factor between each.'},
{id:'it31',subj:'information-technology',strand:'it-data',level:10,diff:3,q:'The binary number 1011 is equal in denary to:',opts:['11','13','9','7'],a:0,why:'8 + 0 + 2 + 1 = 11.',tech:'Write the place values 8 4 2 1 above the digits, then add the ones that are switched on.'},
{id:'it32',subj:'information-technology',strand:'it-impact',level:7,diff:2,q:'Phishing is an attempt to:',opts:['trick you into giving away passwords or account details','physically damage a computer','speed up a network','back up your files'],a:0,why:'Phishing uses a fake message or site to harvest credentials. It attacks the person, not the machine.',tech:'Check the sender and never follow a link asking you to "confirm" a password.'},
{id:'it33',subj:'information-technology',strand:'it-impact',level:10,diff:2,q:'Which is a valid concern about storing personal data online?',opts:['it may be accessed or shared without the owner’s consent','it takes up space at home','it cannot be edited','it is always free'],a:0,why:'Privacy and unauthorised access are the central concerns of data protection.',tech:'Balance benefits against risks when asked to discuss ICT. One-sided answers cap the band.'},
/* Physical Education */
{id:'pe19',subj:'physical-education',strand:'pe-sport',level:8,diff:2,q:'Sportsmanship is best shown by:',opts:['accepting the official’s decision and respecting opponents','winning at any cost','arguing every call','celebrating over a beaten opponent'],a:0,why:'Sportsmanship means fair play, respect and grace in both victory and defeat.',tech:'Give a concrete example from a real situation. It shows you mean it.'},
{id:'pe20',subj:'physical-education',strand:'pe-sport',level:9,diff:2,q:'Why are performance-enhancing drugs banned in sport?',opts:['they are unfair and endanger the athlete’s health','they are expensive','they are difficult to obtain','they make matches shorter'],a:0,why:'Doping breaks the principle of fair competition and carries serious health risks.',tech:'Give both reasons — fairness and health. Questions expect the pair.'},
{id:'pe21',subj:'physical-education',strand:'pe-sport',level:9,diff:2,q:'One social benefit of participating in sport is:',opts:['building teamwork and community belonging','increasing muscle mass','improving lung capacity','lowering resting heart rate'],a:0,why:'The last three are physical benefits. Teamwork and belonging are social.',tech:'Sort benefits into physical, social and mental. Questions name the category they want.'},
{id:'pe22',subj:'physical-education',strand:'pe-sport',level:10,diff:3,q:'Sport can contribute to a national economy through:',opts:['tourism, employment and sponsorship around major events','reducing the population','lowering taxes automatically','replacing manufacturing'],a:0,why:'Hosting and participation generate visitor spending, jobs and commercial investment.',tech:'Use a Caribbean example — a regional cricket tournament or Carnival sports events — to anchor the point.'},
{id:'pe23',subj:'physical-education',strand:'pe-nutri',level:6,diff:1,q:'Which nutrient is the body’s main source of energy during exercise?',opts:['carbohydrate','protein','vitamins','minerals'],a:0,why:'Carbohydrate is the primary fuel. Protein is mainly for growth and repair.',tech:'Match nutrient to function: carbohydrate fuels, protein repairs, fat stores and insulates.'},
{id:'pe24',subj:'physical-education',strand:'pe-nutri',level:8,diff:2,q:'Dehydration during exercise can lead to:',opts:['reduced performance and a higher risk of heat illness','faster recovery','stronger muscles','improved concentration'],a:0,why:'Losing fluid reduces blood volume and the body’s ability to cool itself.',tech:'Drink before, during and after activity — not only when thirsty. Thirst is already a late signal.'},
{id:'pe25',subj:'physical-education',strand:'pe-nutri',level:10,diff:2,q:'A balanced diet for an athlete should be based on:',opts:['the right proportions of all nutrient groups for their energy needs','protein alone','supplements','as few calories as possible'],a:0,why:'Balance and sufficient energy matter more than any single nutrient or supplement.',tech:'Link the diet to the demands of the sport. An endurance athlete and a sprinter do not eat identically.'},
{id:'pe26',subj:'physical-education',strand:'pe-injury',level:7,diff:2,q:'The immediate treatment for a sprained ankle follows the sequence:',opts:['rest, ice, compression, elevation','heat, massage, exercise','run it off','bandage and continue playing'],a:0,why:'RICE limits swelling in the first 48 hours. Heat and massage early can make it worse.',tech:'Remember RICE as four words and say what each one does.'},
{id:'pe27',subj:'physical-education',strand:'pe-injury',level:8,diff:2,q:'Warming up before activity mainly serves to:',opts:['raise muscle temperature and reduce injury risk','burn calories','build muscle','improve technique permanently'],a:0,why:'Warmer muscles are more elastic and the raised heart rate prepares the body for effort.',tech:'Describe the three parts: pulse raiser, mobility, sport-specific activity.'},
{id:'pe28',subj:'physical-education',strand:'pe-injury',level:10,diff:3,q:'A player suffers a suspected concussion. The correct action is to:',opts:['remove them from play and seek medical assessment','let them rest briefly then return','give them water and continue','wait until the end of the match'],a:0,why:'Returning to play risks a second, far more serious injury. Removal is immediate and non-negotiable.',tech:'For any head injury, the rule is: if in doubt, sit them out.'},
/* English and Mathematics gaps */
{id:'ea39',subj:'english-a',strand:'ea-sba',level:9,diff:2,q:'The reflection in the English A SBA should explain:',opts:['what you learned and how the process changed your thinking','what the group did each day','how long the work took','which sources were hardest to find'],a:0,why:'Reflection is about your own learning, not a diary of activity.',tech:'Write "Before this I thought… now I understand…". That sentence starts a strong reflection.'},
{id:'ea40',subj:'english-a',strand:'ea-sba',level:10,diff:3,q:'Sources used in the SBA must be:',opts:['acknowledged fully in the required format','paraphrased without acknowledgement','quoted only if long','listed only if they were online'],a:0,why:'All borrowed material must be credited. Unacknowledged use is plagiarism, whether quoted or paraphrased.',tech:'Record the full reference the moment you use a source. Reconstructing it later wastes time and loses detail.'},
{id:'eb29',subj:'english-b',strand:'eb-essay',level:9,diff:2,q:'A literature essay paragraph is strongest when it:',opts:['makes a point, quotes briefly, and analyses the effect of the words','retells the plot','gives a long quotation with no comment','describes the author’s life'],a:0,why:'Marks come from analysis of the writer’s choices, not from narration.',tech:'Keep quotations short — a few words — so you have room to analyse them.'},
{id:'eb30',subj:'english-b',strand:'eb-essay',level:10,diff:3,q:'When an essay question asks about a THEME, you should:',opts:['trace how the writer develops it across the whole text','summarise the opening chapter','describe one character only','list every event'],a:0,why:'Themes develop. Showing that development across the text is what earns the higher band.',tech:'Choose three moments — early, middle, late — and show how the theme shifts between them.'},
{id:'eb31',subj:'english-b',strand:'eb-short',level:7,diff:2,q:'In a short story, the climax is:',opts:['the point of greatest tension, where the conflict comes to a head','the opening description','the final sentence','the list of characters'],a:0,why:'The climax is the turning point; the resolution follows it.',tech:'Plot the story on a line: exposition, rising action, climax, falling action, resolution.'},
{id:'eb32',subj:'english-b',strand:'eb-short',level:9,diff:2,q:'A first-person narrator is useful to a writer because it:',opts:['gives direct access to one character’s thoughts, while limiting what the reader knows','tells the reader everything','removes all bias','is always more reliable'],a:0,why:'The limitation is the point. An unreliable or partial narrator creates tension and irony.',tech:'Ask what the narrator cannot see. That gap is usually where the meaning sits.'},
{id:'ma47',subj:'mathematics',strand:'ma-sets',level:8,diff:2,q:'If A = {1,2,3,4} and B = {3,4,5}, then A ∩ B is:',opts:['{3,4}','{1,2,5}','{1,2,3,4,5}','{ }'],a:0,why:'Intersection is the elements in BOTH sets: 3 and 4.',tech:'Intersection is the overlap, union is everything. The symbol ∩ looks like a cap that catches the middle.'},
{id:'ma48',subj:'mathematics',strand:'ma-sets',level:9,diff:3,q:'In a class of 30, 18 play cricket, 15 play football and 7 play both. How many play neither?',opts:['4','3','5','8'],a:0,why:'Cricket only 11, football only 8, both 7, total 26. So 30 − 26 = 4.',tech:'Fill the intersection of the Venn diagram FIRST, then work outwards. Doing it in that order avoids double counting.'},
{id:'pw24',subj:'p-ela-writing',strand:'pw-expository',level:4,diff:2,q:'In a paragraph explaining how to do something, the steps should be:',opts:['in the order they happen','in order of importance','in any order','at the end only'],a:0,why:'A reader follows instructions in sequence, so the order must match the doing.',tech:'Use First, Next, Then, Finally. Those four words hold the paragraph together.'},
{id:'pw25',subj:'p-ela-writing',strand:'pw-expository',level:5,diff:2,q:'The best closing sentence for an expository paragraph:',opts:['restates the main idea in different words','introduces a new idea','apologises for the length','asks an unrelated question'],a:0,why:'The closing sentence should tie the paragraph off by returning to its main idea.',tech:'Read your first and last sentences together. They should match without repeating word for word.'}
);

/* ===== BATCH J — primary depth, so the SEA papers stop repeating ===== */
window.CSEC_QUESTIONS.push(
/* --- Number: place value --- */
{id:'pm87',subj:'p-mathematics',strand:'pm-place',level:4,diff:1,q:'What is the value of the 7 in 4 719?',opts:['700','70','7','7 000'],a:0,why:'The 7 sits in the hundreds place, so its value is 7 hundreds, or 700.',tech:'Write the place names above the digits: thousands, hundreds, tens, ones.'},
{id:'pm88',subj:'p-mathematics',strand:'pm-place',level:4,diff:2,q:'Which number is 1 000 more than 26 480?',opts:['27 480','26 580','36 480','26 490'],a:0,why:'Adding 1 000 changes only the thousands digit: 26 becomes 27 thousand.',tech:'Adding a power of ten changes one column. Find the column first.'},
{id:'pm89',subj:'p-mathematics',strand:'pm-place',level:5,diff:2,q:'Round 38 649 to the nearest thousand.',opts:['39 000','38 000','38 600','40 000'],a:0,why:'The hundreds digit is 6, which is 5 or more, so round the thousands up from 38 to 39.',tech:'Underline the rounding digit, then look at the ONE digit to its right. Nothing else matters.'},
{id:'pm90',subj:'p-mathematics',strand:'pm-place',level:5,diff:2,q:'Write 60 000 + 3 000 + 40 + 9 as a single number.',opts:['63 049','63 409','6 349','63 490'],a:0,why:'There are no hundreds, so a zero must hold that place: 63 049.',tech:'When a place is missing, a zero holds it open. Leaving it out shifts every digit.'},
{id:'pm91',subj:'p-mathematics',strand:'pm-place',level:5,diff:3,q:'Which list is in order from smallest to largest?',opts:['9 087, 9 807, 9 870','9 870, 9 807, 9 087','9 807, 9 087, 9 870','9 087, 9 870, 9 807'],a:0,why:'Compare from the left. The thousands are equal, so compare hundreds: 0, 8, 8; then tens for the last two.',tech:'Line the numbers up and compare one column at a time from the left.'},
{id:'pm92',subj:'p-mathematics',strand:'pm-place',level:3,diff:1,q:'Which number comes just before 1 000?',opts:['999','1 001','990','900'],a:0,why:'Counting back one from 1 000 gives 999.',tech:'Crossing a thousand, every 9 rolls over at once. Say the numbers aloud.'},
{id:'pm93',subj:'p-mathematics',strand:'pm-place',level:5,diff:2,q:'In 507 362, which digit is in the ten thousands place?',opts:['0','5','7','3'],a:0,why:'Reading from the right: 2 ones, 6 tens, 3 hundreds, 7 thousands, 0 ten thousands, 5 hundred thousands.',tech:'Count place names from the RIGHT, not the left. That is where most errors start.'},
/* --- Number: operations --- */
{id:'pm94',subj:'p-mathematics',strand:'pm-ops',level:4,diff:2,q:'A shop had 1 250 bottles and sold 867. How many are left?',opts:['383','393','417','1 383'],a:0,why:'1 250 − 867 = 383.',tech:'Subtracting across zeros needs regrouping. Check by adding your answer back to 867.'},
{id:'pm95',subj:'p-mathematics',strand:'pm-ops',level:4,diff:2,q:'What is 36 × 20?',opts:['720','560','72','7 200'],a:0,why:'36 × 2 = 72, then multiply by 10 to get 720.',tech:'Multiplying by 20 is doubling, then adding a zero. Far quicker than long multiplication.'},
{id:'pm96',subj:'p-mathematics',strand:'pm-ops',level:5,diff:2,q:'What is 504 ÷ 8?',opts:['63','62','64','630'],a:0,why:'8 × 63 = 504.',tech:'Check every division by multiplying back. It takes five seconds and catches most slips.'},
{id:'pm97',subj:'p-mathematics',strand:'pm-ops',level:5,diff:3,q:'Work out 24 + 6 × 5.',opts:['54','150','35','30'],a:0,why:'Multiplication comes before addition: 6 × 5 = 30, then 24 + 30 = 54.',tech:'Brackets, then × and ÷, then + and −. Working strictly left to right gives 150, which is wrong.'},
{id:'pm98',subj:'p-mathematics',strand:'pm-ops',level:5,diff:3,q:'A box holds 24 pencils. How many boxes are needed for 150 pencils?',opts:['7','6','6.25','5'],a:0,why:'150 ÷ 24 = 6 remainder 6. Six boxes leave 6 pencils over, so a seventh box is needed.',tech:'When the question is how many are NEEDED, always round the remainder up.'},
{id:'pm99',subj:'p-mathematics',strand:'pm-ops',level:3,diff:1,q:'What is 400 + 350?',opts:['750','700','450','7 500'],a:0,why:'4 hundreds plus 3 hundreds is 7 hundreds, plus 50 gives 750.',tech:'Add the hundreds, then the rest. Breaking it up beats writing it out.'},
{id:'pm100',subj:'p-mathematics',strand:'pm-ops',level:5,diff:2,q:'Which calculation gives the same answer as 48 × 25?',opts:['12 × 100','48 × 20','24 × 25','48 + 25'],a:0,why:'Halving 48 to 24 and doubling 25 to 50 gives 24 × 50; halving and doubling again gives 12 × 100 = 1 200.',tech:'Doubling one factor and halving the other keeps the product the same. It turns hard sums into easy ones.'},
{id:'pm101',subj:'p-mathematics',strand:'pm-ops',level:4,diff:2,q:'What is the remainder when 95 is divided by 7?',opts:['4','3','5','13'],a:0,why:'7 × 13 = 91, and 95 − 91 = 4.',tech:'Find the largest multiple below the number, then subtract.'},
/* --- Number: fractions --- */
{id:'pm102',subj:'p-mathematics',strand:'pm-fractions',level:4,diff:2,q:'Which fraction is equivalent to 3/4?',opts:['9/12','6/9','4/5','3/8'],a:0,why:'Multiplying top and bottom by 3 gives 9/12.',tech:'Whatever you do to the top you must do to the bottom. That is the whole rule.'},
{id:'pm103',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:2,q:'What is 1/2 + 1/4?',opts:['3/4','2/6','1/6','2/4'],a:0,why:'Change 1/2 to 2/4, then 2/4 + 1/4 = 3/4.',tech:'Never add the bottoms. Make them the same first, then add only the tops.'},
{id:'pm104',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:2,q:'What is 2/3 of 24?',opts:['16','8','12','36'],a:0,why:'24 ÷ 3 = 8, then 8 × 2 = 16.',tech:'Divide by the bottom, multiply by the top. In that order it always works.'},
{id:'pm105',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:3,q:'Which fraction is the largest?',opts:['5/8','1/2','3/8','1/4'],a:0,why:'As eighths: 5/8, 4/8, 3/8, 2/8. So 5/8 is largest.',tech:'Give them all the same bottom number, then just compare the tops.'},
{id:'pm106',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:2,q:'Write 7/4 as a mixed number.',opts:['1 3/4','1 1/4','2 3/4','3/4'],a:0,why:'4 goes into 7 once with 3 left over, so 1 3/4.',tech:'Divide the top by the bottom. The answer is the whole number, the remainder stays on top.'},
{id:'pm107',subj:'p-mathematics',strand:'pm-fractions',level:4,diff:1,q:'A pizza is cut into 8 equal slices and 3 are eaten. What fraction is left?',opts:['5/8','3/8','5/3','8/5'],a:0,why:'8 − 3 = 5 slices remain out of 8.',tech:'The bottom number is the total pieces; it does not change when pieces are eaten.'},
{id:'pm108',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:3,q:'What is 3/4 − 1/3?',opts:['5/12','2/1','1/2','4/7'],a:0,why:'Twelfths: 9/12 − 4/12 = 5/12.',tech:'When the bottoms share no factor, multiply them for the common denominator.'},
/* --- Number: decimals & percent --- */
{id:'pm109',subj:'p-mathematics',strand:'pm-decimals',level:4,diff:2,q:'Which decimal is the same as 3/10?',opts:['0.3','0.03','3.10','0.310'],a:0,why:'Three tenths is written 0.3.',tech:'Tenths go one place after the point, hundredths two.'},
{id:'pm110',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'What is 2.6 + 0.45?',opts:['3.05','2.11','3.5','6.6'],a:0,why:'Line up the points: 2.60 + 0.45 = 3.05.',tech:'Add a zero so both numbers have the same number of decimal places, then line up the points.'},
{id:'pm111',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'What is 25% of 80?',opts:['20','25','40','16'],a:0,why:'25% is one quarter, and 80 ÷ 4 = 20.',tech:'Learn 50% is half, 25% a quarter, 10% divide by ten. Those three cover most questions.'},
{id:'pm112',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:3,q:'A shirt costs $240 and is reduced by 15%. What is the new price?',opts:['$204','$225','$36','$216'],a:0,why:'10% is $24 and 5% is $12, so 15% is $36. $240 − $36 = $204.',tech:'Find 10%, halve it for 5%, then combine. No calculator needed.'},
{id:'pm113',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'Write 0.75 as a fraction in its simplest form.',opts:['3/4','75/100','7/5','1/4'],a:0,why:'0.75 is 75/100, and dividing both by 25 gives 3/4.',tech:'Know the common pairs by heart: 0.5 = 1/2, 0.25 = 1/4, 0.75 = 3/4, 0.2 = 1/5.'},
{id:'pm114',subj:'p-mathematics',strand:'pm-decimals',level:5,diff:2,q:'Which is the smallest?  0.4,  0.39,  0.5,  0.44',opts:['0.39','0.4','0.44','0.5'],a:0,why:'As hundredths: 0.40, 0.39, 0.50, 0.44. The smallest is 0.39.',tech:'Give every decimal the same number of places by adding zeros, then compare as whole numbers.'},
{id:'pm115',subj:'p-mathematics',strand:'pm-decimals',level:4,diff:2,q:'What is 4.7 × 10?',opts:['47','4.70','0.47','470'],a:0,why:'Multiplying by 10 moves every digit one place left: 4.7 becomes 47.',tech:'The point stays put and the digits move. Thinking of it that way avoids mistakes with zeros.'},
/* --- Number: money --- */
{id:'pm116',subj:'p-mathematics',strand:'pm-money',level:4,diff:2,q:'A pen costs $3.50. How much do 4 pens cost?',opts:['$14.00','$12.00','$13.50','$7.00'],a:0,why:'3.50 × 4 = 14.00.',tech:'Multiply the dollars and the cents separately if that is easier, then add.'},
{id:'pm117',subj:'p-mathematics',strand:'pm-money',level:5,diff:2,q:'Anaya pays with a $100 note for goods costing $63.25. What change does she get?',opts:['$36.75','$37.75','$36.25','$43.75'],a:0,why:'100.00 − 63.25 = 36.75.',tech:'Count up from the price to the note: 75 cents to $64, then $36 to $100.'},
{id:'pm118',subj:'p-mathematics',strand:'pm-money',level:5,diff:3,q:'A shop buys a bag for $80 and sells it for $100. What is the profit as a percentage of the cost?',opts:['25%','20%','80%','125%'],a:0,why:'Profit is $20, and 20 ÷ 80 = 0.25, which is 25%.',tech:'Percentage profit is always worked on the COST, not the selling price.'},
{id:'pm119',subj:'p-mathematics',strand:'pm-money',level:5,diff:3,q:'Which is the better buy: 6 pens for $27 or 8 pens for $32?',opts:['8 pens for $32','6 pens for $27','they cost the same each','not enough information'],a:0,why:'$27 ÷ 6 = $4.50 each; $32 ÷ 8 = $4.00 each.',tech:'Always work out the cost of ONE. That is the only fair comparison.'},
{id:'pm120',subj:'p-mathematics',strand:'pm-money',level:4,diff:2,q:'Ravi saves $15 each week. How much has he saved after 8 weeks?',opts:['$120','$23','$105','$150'],a:0,why:'15 × 8 = 120.',tech:'Read carefully whether the question wants a total or a weekly amount.'},
{id:'pm121',subj:'p-mathematics',strand:'pm-money',level:5,diff:2,q:'A worker earns $45 an hour and works 7 hours. What is the pay?',opts:['$315','$305','$52','$280'],a:0,why:'45 × 7 = 315.',tech:'Rate questions are one multiplication. Identify the rate and the number of units.'},
{id:'pm122',subj:'p-mathematics',strand:'pm-money',level:5,diff:3,q:'A bill for $180 is shared equally among 4 people, and one person pays double. How much does that person pay?',opts:['$72','$45','$90','$36'],a:0,why:'Five equal shares are needed: $180 ÷ 5 = $36. The one paying double pays $72.',tech:'When someone pays double, count the shares, not the people.'},
/* --- Geometry: shapes --- */
{id:'pm123',subj:'p-mathematics',strand:'pm-shapes',level:4,diff:1,q:'How many faces does a cube have?',opts:['6','8','12','4'],a:0,why:'A cube has 6 square faces, 8 vertices and 12 edges.',tech:'Learn faces, edges and vertices for the cube, cuboid, cylinder, cone and pyramid.'},
{id:'pm124',subj:'p-mathematics',strand:'pm-shapes',level:4,diff:2,q:'Which shape has exactly one pair of parallel sides?',opts:['trapezium','square','rectangle','rhombus'],a:0,why:'A trapezium has one pair. The other three all have two pairs.',tech:'Sort quadrilaterals by parallel sides, equal sides and right angles.'},
{id:'pm125',subj:'p-mathematics',strand:'pm-shapes',level:5,diff:2,q:'A shape has 5 sides. It is called a:',opts:['pentagon','hexagon','quadrilateral','octagon'],a:0,why:'Pentagon 5, hexagon 6, octagon 8.',tech:'Penta 5, hexa 6, hepta 7, octa 8. The prefixes carry the number.'},
{id:'pm126',subj:'p-mathematics',strand:'pm-shapes',level:5,diff:2,q:'How many edges does a cuboid have?',opts:['12','8','6','4'],a:0,why:'A cuboid has 12 edges, 6 faces and 8 vertices, the same counts as a cube.',tech:'Count in groups: 4 top, 4 bottom, 4 upright.'},
{id:'pm127',subj:'p-mathematics',strand:'pm-shapes',level:3,diff:1,q:'Which solid has a curved surface and two flat circular faces?',opts:['cylinder','cone','sphere','cube'],a:0,why:'A cylinder has two circles joined by a curved surface. A cone has one circle.',tech:'Count the flat faces first. It separates the cylinder, the cone and the sphere at once.'},
/* --- Geometry: angles & symmetry --- */
{id:'pm128',subj:'p-mathematics',strand:'pm-angles',level:4,diff:1,q:'An angle of 90° is called a:',opts:['right angle','acute angle','obtuse angle','straight angle'],a:0,why:'Right is exactly 90°, acute is less, obtuse is between 90° and 180°.',tech:'Acute is small and sharp, obtuse is fat, reflex is more than 180°.'},
{id:'pm129',subj:'p-mathematics',strand:'pm-angles',level:5,diff:2,q:'Two angles on a straight line are 130° and x. What is x?',opts:['50°','70°','230°','30°'],a:0,why:'Angles on a straight line add to 180°, so x = 180 − 130 = 50.',tech:'Straight line 180°, full turn 360°, right angle 90°. Nearly every angle question uses one of these.'},
{id:'pm130',subj:'p-mathematics',strand:'pm-angles',level:5,diff:2,q:'How many lines of symmetry does a square have?',opts:['4','2','1','8'],a:0,why:'Two through the middles of opposite sides and two along the diagonals.',tech:'Imagine folding the shape so both halves match exactly. Each fold is a line of symmetry.'},
{id:'pm131',subj:'p-mathematics',strand:'pm-angles',level:5,diff:3,q:'The angles of a triangle are 65°, 45° and x. What is x?',opts:['70°','80°','110°','60°'],a:0,why:'Angles in a triangle add to 180°: 180 − 65 − 45 = 70.',tech:'Triangle 180°, quadrilateral 360°. Learn both.'},
{id:'pm132',subj:'p-mathematics',strand:'pm-angles',level:4,diff:2,q:'Lines that never meet, however far they are extended, are:',opts:['parallel','perpendicular','intersecting','curved'],a:0,why:'Parallel lines stay the same distance apart. Perpendicular lines meet at 90°.',tech:'Parallel lines are marked with matching arrows on a diagram.'},
/* --- Measurement: time --- */
{id:'pm133',subj:'p-mathematics',strand:'pm-time',level:4,diff:2,q:'A film starts at 6:45 p.m. and lasts 1 hour 40 minutes. When does it end?',opts:['8:25 p.m.','8:15 p.m.','7:25 p.m.','8:45 p.m.'],a:0,why:'6:45 plus one hour is 7:45; plus 40 minutes is 8:25.',tech:'Add the hours first, then the minutes. Count up to the next hour if it helps.'},
{id:'pm134',subj:'p-mathematics',strand:'pm-time',level:5,diff:2,q:'How many minutes are there in 3 1/2 hours?',opts:['210','180','230','350'],a:0,why:'3 × 60 = 180, plus 30 = 210.',tech:'Convert to the smaller unit before doing anything else.'},
{id:'pm135',subj:'p-mathematics',strand:'pm-time',level:5,diff:2,q:'Written as a 24-hour time, 4:30 p.m. is:',opts:['16:30','04:30','14:30','18:30'],a:0,why:'After midday, add 12 to the hour: 4 + 12 = 16.',tech:'Before noon the hour is unchanged; after noon add 12.'},
{id:'pm136',subj:'p-mathematics',strand:'pm-time',level:5,diff:3,q:'A bus leaves at 09:50 and arrives at 12:15. How long is the journey?',opts:['2 h 25 min','2 h 35 min','3 h 25 min','2 h 65 min'],a:0,why:'09:50 to 12:00 is 2 hours 10 minutes; plus 15 minutes is 2 hours 25.',tech:'Count up to the next whole hour first. Subtracting times directly causes borrowing errors.'},
{id:'pm137',subj:'p-mathematics',strand:'pm-time',level:3,diff:1,q:'How many days are there in the month of June?',opts:['30','31','28','29'],a:0,why:'April, June, September and November have 30 days.',tech:'Use the knuckle method, or the rhyme. It is examined most years.'},
/* --- Measurement: length, mass, capacity --- */
{id:'pm138',subj:'p-mathematics',strand:'pm-measure',level:4,diff:2,q:'How many centimetres are there in 2.5 metres?',opts:['250','25','2 500','0.025'],a:0,why:'1 m = 100 cm, so 2.5 × 100 = 250.',tech:'Going to a smaller unit, the number gets bigger. Check the answer makes sense.'},
{id:'pm139',subj:'p-mathematics',strand:'pm-measure',level:5,diff:2,q:'A bag holds 2.4 kg. What is this in grams?',opts:['2 400 g','240 g','24 g','24 000 g'],a:0,why:'1 kg = 1 000 g, so 2.4 × 1 000 = 2 400.',tech:'kilo means a thousand. The same factor works for km to m.'},
{id:'pm140',subj:'p-mathematics',strand:'pm-measure',level:5,diff:2,q:'How many millilitres are in 1.5 litres?',opts:['1 500 ml','150 ml','15 ml','15 000 ml'],a:0,why:'1 litre = 1 000 ml, so 1.5 litres = 1 500 ml.',tech:'milli means a thousandth. 1 000 ml in a litre, 1 000 mm in a metre.'},
{id:'pm141',subj:'p-mathematics',strand:'pm-measure',level:5,diff:3,q:'A rope 5 m long is cut into pieces each 40 cm long. How many pieces are there?',opts:['12','125','20','8'],a:0,why:'5 m = 500 cm, and 500 ÷ 40 = 12 remainder 20. So 12 whole pieces.',tech:'Convert both measures to the same unit before dividing.'},
{id:'pm142',subj:'p-mathematics',strand:'pm-measure',level:4,diff:1,q:'Which unit would you use to measure the mass of a schoolbag?',opts:['kilograms','millimetres','litres','seconds'],a:0,why:'Mass is measured in grams and kilograms; a schoolbag is a few kilograms.',tech:'Match the unit to what is being measured and to a sensible size.'},
/* --- Measurement: perimeter, area, volume --- */
{id:'pm143',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'A rectangle is 9 cm long and 4 cm wide. What is its area?',opts:['36 cm²','26 cm²','13 cm²','36 cm'],a:0,why:'Area = length × width = 9 × 4 = 36 square centimetres.',tech:'Area is always in SQUARE units. An answer in cm alone is marked wrong.'},
{id:'pm144',subj:'p-mathematics',strand:'pm-area',level:4,diff:2,q:'What is the perimeter of a square of side 7 cm?',opts:['28 cm','49 cm','14 cm','21 cm'],a:0,why:'Perimeter is the distance all the way round: 7 × 4 = 28 cm.',tech:'Perimeter adds the sides, area multiplies. Decide which the question wants before calculating.'},
{id:'pm145',subj:'p-mathematics',strand:'pm-area',level:5,diff:3,q:'A box measures 5 cm by 4 cm by 3 cm. What is its volume?',opts:['60 cm³','12 cm³','47 cm³','60 cm²'],a:0,why:'Volume = length × width × height = 5 × 4 × 3 = 60 cubic centimetres.',tech:'Volume uses CUBIC units. Three measurements multiplied means three little threes.'},
{id:'pm146',subj:'p-mathematics',strand:'pm-area',level:5,diff:3,q:'A rectangle has an area of 48 cm² and a length of 8 cm. What is its width?',opts:['6 cm','40 cm','384 cm','24 cm'],a:0,why:'Width = area ÷ length = 48 ÷ 8 = 6 cm.',tech:'When the area is given, divide to find the missing side.'},
{id:'pm147',subj:'p-mathematics',strand:'pm-area',level:5,diff:2,q:'How many square metres of tiles are needed for a floor 6 m by 5 m?',opts:['30 m²','22 m²','11 m²','30 m'],a:0,why:'6 × 5 = 30 square metres.',tech:'Real-life area questions still reduce to length × width. Sketch it first.'},
/* --- Statistics: graphs --- */
{id:'pm148',subj:'p-mathematics',strand:'pm-graphs',level:4,diff:2,q:'On a pictograph, if one symbol stands for 5 books, how many books do 4 symbols show?',opts:['20','9','4','5'],a:0,why:'Each symbol is 5, so 4 × 5 = 20.',tech:'Read the key first. A pictograph is meaningless without it.'},
{id:'pm149',subj:'p-mathematics',strand:'pm-graphs',level:5,diff:2,q:'On a bar graph, the tallest bar shows:',opts:['the largest value','the smallest value','the average','the total'],a:0,why:'Bar height represents the value, so the tallest bar is the greatest.',tech:'Check the scale on the vertical axis before reading any bar.'},
{id:'pm150',subj:'p-mathematics',strand:'pm-graphs',level:5,diff:3,q:'A bar graph has a scale going up in 4s. A bar reaches halfway between 12 and 16. What value is it?',opts:['14','13','15','12'],a:0,why:'Halfway between 12 and 16 is 14.',tech:'Work out what one small square is worth before reading any value between the lines.'},
{id:'pm151',subj:'p-mathematics',strand:'pm-graphs',level:4,diff:2,q:'In a tally chart, the marks ||||̸ ||| stand for:',opts:['8','5','3','53'],a:0,why:'A gate of five plus three more is 8.',tech:'Tallies are grouped in fives with the fifth struck across. Count the gates, then the extras.'},
{id:'pm152',subj:'p-mathematics',strand:'pm-graphs',level:5,diff:2,q:'A pie chart shows half the class chose football. If there are 30 pupils, how many chose football?',opts:['15','30','10','60'],a:0,why:'Half of 30 is 15.',tech:'On a pie chart, work out what fraction of the circle the slice is, then take that fraction of the total.'},
/* --- Statistics: average --- */
{id:'pm153',subj:'p-mathematics',strand:'pm-average',level:5,diff:2,q:'What is the mean of 4, 7, 9 and 8?',opts:['7','8','28','6'],a:0,why:'4 + 7 + 9 + 8 = 28, and 28 ÷ 4 = 7.',tech:'Add them all, divide by how many there are. Count the numbers carefully.'},
{id:'pm154',subj:'p-mathematics',strand:'pm-average',level:5,diff:2,q:'What is the mode of 3, 5, 5, 7, 9?',opts:['5','7','29','3'],a:0,why:'The mode is the value appearing most often, which is 5.',tech:'Mode is MOST often. The two words start the same way.'},
{id:'pm155',subj:'p-mathematics',strand:'pm-average',level:5,diff:2,q:'What is the median of 2, 8, 5, 9, 4?',opts:['5','8','4','5.6'],a:0,why:'In order: 2, 4, 5, 8, 9. The middle value is 5.',tech:'ALWAYS put the numbers in order first. Skipping that is the commonest median error.'},
{id:'pm156',subj:'p-mathematics',strand:'pm-average',level:5,diff:3,q:'The mean of 5 numbers is 12. What is their total?',opts:['60','17','2.4','12'],a:0,why:'Total = mean × how many = 12 × 5 = 60.',tech:'Working backwards from a mean, multiply instead of divide.'},
{id:'pm157',subj:'p-mathematics',strand:'pm-average',level:5,diff:3,q:'What is the range of 12, 5, 19, 8?',opts:['14','19','11','44'],a:0,why:'Range is largest minus smallest: 19 − 5 = 14.',tech:'Range is a single number measuring spread, not a pair of numbers.'},
{id:'pm158',subj:'p-mathematics',strand:'pm-average',level:4,diff:2,q:'Four children have 6, 6, 7 and 9 sweets. Which is true?',opts:['the mode is 6','the mode is 9','the median is 6','the mean is 6'],a:0,why:'6 appears twice, more than any other value, so the mode is 6. The mean is 7 and the median is 6.5.',tech:'Work out all three when the question offers a choice. It takes seconds and removes the guess.'}
);

/* ===== BATCH K — primary ELA depth (poetry and graphic text were the block) ===== */
window.CSEC_QUESTIONS.push(
/* --- Poetry --- */
{id:'pel47',subj:'p-ela',strand:'pe-poetry',level:3,diff:1,q:'Two lines of a poem that end in rhyming words are said to have:',opts:['rhyme','rhythm','alliteration','a simile'],a:0,why:'Rhyme is matching end sounds. Rhythm is the beat.',tech:'Read the poem aloud in your head. Rhyme is heard, not seen — "cough" and "though" do not rhyme.'},
{id:'pel48',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"The wind whispered through the trees." The wind is given a human action. This is:',opts:['personification','a simile','alliteration','onomatopoeia'],a:0,why:'Personification gives human qualities to something that is not human.',tech:'Ask whether a person could do it. If only a person could whisper, and the wind is whispering, it is personification.'},
{id:'pel49',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"Her smile was like sunshine" is an example of:',opts:['a simile','a metaphor','personification','rhyme'],a:0,why:'A simile compares using "like" or "as". A metaphor says one thing IS another.',tech:'Look for "like" or "as". Present means simile, absent means metaphor.'},
{id:'pel50',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"Silly Sally sang softly" repeats the same opening sound. This is:',opts:['alliteration','rhyme','a metaphor','a stanza'],a:0,why:'Alliteration repeats the consonant sound at the start of nearby words.',tech:'Listen to the first sound of each word, not the first letter — "city" and "cat" do not alliterate.'},
{id:'pel51',subj:'p-ela',strand:'pe-poetry',level:5,diff:2,q:'A group of lines in a poem, set apart by a space, is called a:',opts:['stanza','paragraph','chapter','verse line'],a:0,why:'Poems are divided into stanzas; prose is divided into paragraphs.',tech:'Use the poetry words when writing about a poem. It is credited.'},
{id:'pel52',subj:'p-ela',strand:'pe-poetry',level:5,diff:2,q:'The mood of a poem means:',opts:['the feeling it creates in the reader','how long it is','how many stanzas it has','who wrote it'],a:0,why:'Mood is the atmosphere — sad, joyful, tense — created by word choice and imagery.',tech:'Name the mood AND quote the word that creates it. Both halves earn marks.'},
{id:'pel53',subj:'p-ela',strand:'pe-poetry',level:5,diff:3,q:'"The thunder growled and grumbled all night." Which sound device is used?',opts:['onomatopoeia','simile','rhyme','stanza'],a:0,why:'"Growled" and "grumbled" imitate the sound they describe.',tech:'Onomatopoeia words sound like the noise: crash, hiss, buzz, rumble.'},
{id:'pel54',subj:'p-ela',strand:'pe-poetry',level:5,diff:3,q:'When a question asks what a line of poetry SUGGESTS, you should give:',opts:['the meaning beyond the literal words','a dictionary definition','the number of syllables','the rhyme scheme'],a:0,why:'"Suggests" asks for inference — what the words imply rather than state.',tech:'Answer, then point to the word that made you think it. Inference without evidence scores low.'},
{id:'pel55',subj:'p-ela',strand:'pe-poetry',level:5,diff:2,q:'Imagery in a poem is language that:',opts:['appeals to the five senses','always rhymes','tells a story','repeats sounds'],a:0,why:'Imagery makes the reader see, hear, smell, taste or feel something.',tech:'Say WHICH sense the image appeals to. "Sight imagery" is a stronger answer than "imagery".'},
{id:'pel56',subj:'p-ela',strand:'pe-poetry',level:4,diff:2,q:'"The classroom was a zoo." This is:',opts:['a metaphor','a simile','alliteration','onomatopoeia'],a:0,why:'It says the classroom WAS a zoo, without "like" or "as", so it is a metaphor.',tech:'A metaphor states the comparison as fact. Explain what the two things share.'},
/* --- Graphic text --- */
{id:'pel57',subj:'p-ela',strand:'pe-graphic',level:4,diff:1,q:'On a poster advertising an event, the largest print usually gives:',opts:['the most important information','the price','the small print','the designer’s name'],a:0,why:'Size signals importance in a graphic text — usually what the event is.',tech:'Read a graphic text in size order: biggest first, then next biggest.'},
{id:'pel58',subj:'p-ela',strand:'pe-graphic',level:4,diff:2,q:'A key or legend on a map or chart tells you:',opts:['what the symbols and colours mean','who made it','when it was printed','how big it is'],a:0,why:'Without the key the symbols cannot be interpreted.',tech:'Find the key before answering any question about a chart or map.'},
{id:'pel59',subj:'p-ela',strand:'pe-graphic',level:5,diff:2,q:'The purpose of an advertisement is mainly to:',opts:['persuade','entertain only','describe neutrally','instruct'],a:0,why:'Advertisements persuade you to buy, attend or believe something.',tech:'Identify the purpose — to inform, persuade, instruct or entertain — before answering. It shapes every answer.'},
{id:'pel60',subj:'p-ela',strand:'pe-graphic',level:5,diff:3,q:'A notice reads "Entry FREE for children under 12". A child of 12 must:',opts:['pay','enter free','bring a parent','wait outside'],a:0,why:'"Under 12" does not include 12, so a twelve-year-old pays.',tech:'Read the small words exactly — under, over, up to, from. They decide the answer.'},
{id:'pel61',subj:'p-ela',strand:'pe-graphic',level:5,diff:2,q:'On a timetable, to find when a bus reaches a stop you should read:',opts:['across the row for that stop','the first column only','the title','the bottom row'],a:0,why:'Timetables are grids: find the stop, then read across to the column for the service you want.',tech:'Put a finger on the row and another on the column. The answer is where they meet.'},
/* --- Fiction / non-fiction comprehension --- */
{id:'pel62',subj:'p-ela',strand:'pe-fiction',level:4,diff:2,q:'The setting of a story is:',opts:['where and when it happens','the main problem','the people in it','the message'],a:0,why:'Setting is place and time. The people are characters and the problem is the conflict.',tech:'Setting can matter to the plot. Ask whether the story could happen anywhere else.'},
{id:'pel63',subj:'p-ela',strand:'pe-fiction',level:5,diff:3,q:'A character slams a door and refuses to speak. The writer is showing that the character is:',opts:['angry','delighted','confused','tired'],a:0,why:'Actions reveal feeling without naming it. Slamming and silence signal anger.',tech:'When a feeling is not stated, look at what the character DOES. That is inference.'},
{id:'pel64',subj:'p-ela',strand:'pe-nonfict',level:4,diff:2,q:'The main idea of a paragraph is usually found:',opts:['in the topic sentence','in the last word','in the title only','in the longest sentence'],a:0,why:'The topic sentence states the main idea; the rest of the paragraph supports it.',tech:'Cover the paragraph and ask what it was mostly about. That is the main idea.'},
{id:'pel65',subj:'p-ela',strand:'pe-nonfict',level:5,diff:2,q:'A fact differs from an opinion because a fact:',opts:['can be checked and proved','is what someone believes','is always longer','appears first'],a:0,why:'Facts can be verified. Opinions express a view and cannot be proved true or false.',tech:'Watch for opinion signals: best, should, beautiful, terrible.'},
/* --- Spelling --- */
{id:'pel66',subj:'p-ela',strand:'pe-spell',level:4,diff:2,q:'Which word is spelt correctly?',opts:['necessary','neccessary','necesary','necessery'],a:0,why:'One c, two s: necessary.',tech:'Remember: one Collar, two Sleeves.'},
{id:'pel67',subj:'p-ela',strand:'pe-spell',level:5,diff:2,q:'Which word is spelt correctly?',opts:['separate','seperate','separete','sepparate'],a:0,why:'Separate has an "a" in the middle, not an "e".',tech:'There is A RAT in sepARATe.'},
{id:'pel68',subj:'p-ela',strand:'pe-spell',level:4,diff:2,q:'The plural of "leaf" is:',opts:['leaves','leafs','leafes','leave'],a:0,why:'Words ending in -f often change to -ves: leaf, leaves; knife, knives.',tech:'Learn the -f to -ves group. It is examined most years.'},
{id:'pel69',subj:'p-ela',strand:'pe-spell',level:5,diff:3,q:'Which sentence uses the right word?',opts:['Their house is over there.','There house is over their.','They’re house is over there.','Their house is over they’re.'],a:0,why:'"Their" shows belonging; "there" is a place; "they’re" means they are.',tech:'Try "they are" in the sentence. If it works, the word is they’re.'},
{id:'pel70',subj:'p-ela',strand:'pe-spell',level:5,diff:2,q:'Which word is spelt correctly?',opts:['definitely','definately','defenitely','definitly'],a:0,why:'Definitely contains the word "finite".',tech:'Look for a smaller word inside the longer one. It anchors the spelling.'},
/* --- Punctuation & capitalisation --- */
{id:'pel71',subj:'p-ela',strand:'pe-punct',level:4,diff:2,q:'Which sentence is punctuated correctly?',opts:['"Where are you going?" asked Mother.','"Where are you going" asked Mother.','"Where are you going?" Asked Mother.','Where are you going? asked Mother.'],a:0,why:'The question mark goes inside the quotation marks, and "asked" is not a new sentence, so it stays lower case.',tech:'In direct speech the punctuation goes INSIDE the quotation marks.'},
{id:'pel72',subj:'p-ela',strand:'pe-punct',level:5,diff:2,q:'Which sentence uses the apostrophe correctly?',opts:['The boy’s books are on the desk.','The boys books are on the desk.','The boys’s books are on the desk.','The boy’s books’ are on the desk.'],a:0,why:'One boy owns the books, so the apostrophe goes before the s.',tech:'Ask who owns it. One owner takes ’s; more than one ending in s takes s’.'},
{id:'pel73',subj:'p-ela',strand:'pe-punct',level:4,diff:2,q:'Which sentence uses capital letters correctly?',opts:['We visited Port of Spain in August.','we visited port of spain in august.','We visited port of Spain in august.','We Visited Port Of Spain In August.'],a:0,why:'Place names and months are proper nouns and take capitals; ordinary words do not.',tech:'Capitalise names of people, places, months, days and titles — not seasons.'},
{id:'pel74',subj:'p-ela',strand:'pe-punct',level:5,diff:3,q:'Which sentence uses the comma correctly?',opts:['We bought bread, cheese, milk and eggs.','We bought bread cheese milk and eggs.','We bought, bread, cheese, milk and eggs.','We bought bread, cheese, milk, and, eggs.'],a:0,why:'Commas separate items in a list, and the last two are joined by "and".',tech:'A comma marks a short pause. Read it aloud and put commas where you naturally pause.'},
{id:'pel75',subj:'p-ela',strand:'pe-punct',level:5,diff:2,q:'Which punctuation mark introduces a list?',opts:['the colon','the comma','the full stop','the apostrophe'],a:0,why:'A colon introduces a list or an explanation.',tech:'Colon introduces, semicolon joins two related sentences.'}
);

/* Two more Number items take Mathematics from three complete papers to four. */
window.CSEC_QUESTIONS.push(
{id:'pm159',subj:'p-mathematics',strand:'pm-ops',level:5,diff:2,q:'What is 15 × 12?',opts:['180','170','27','150'],a:0,why:'15 × 10 = 150 and 15 × 2 = 30, so 150 + 30 = 180.',tech:'Split the second number into tens and ones, multiply each, then add.'},
{id:'pm160',subj:'p-mathematics',strand:'pm-fractions',level:5,diff:2,q:'Simplify 12/18 to its lowest terms.',opts:['2/3','6/9','4/6','12/18'],a:0,why:'Both divide by 6: 12 ÷ 6 = 2 and 18 ÷ 6 = 3.',tech:'Divide top and bottom by the largest number that goes into both.'},
{id:'pm161',subj:'p-mathematics',strand:'pm-money',level:5,diff:2,q:'Three friends share $96 equally. How much does each get?',opts:['$32','$33','$30','$288'],a:0,why:'96 ÷ 3 = 32.',tech:'Sharing equally always means divide by the number of people.'}
);
